const OBJECTIVE_CARDS = [
{cat:0,catName:"D1 General Concepts",acr:"Technical",full:"1.1 Compare and contrast various types of security controls.",def:"Definition:\nSecurity control implemented with technology, such as firewall rules, endpoint protection, operating system settings, or authentication systems.\n\nClue:\nLook for a system, tool, device, or software enforcing the control.\n\nExample:\nA firewall blocks traffic automatically.\n\nContrast:\nManagerial = policy/oversight; Operational = people/process; Physical = real-world protection.",trick:"Exam map: Categories > Technical"},
{cat:0,catName:"D1 General Concepts",acr:"Managerial",full:"1.1 Compare and contrast various types of security controls.",def:"Definition:\nAdministrative security control used to manage and direct security, such as policies, standards, procedures, risk decisions, and oversight.\n\nClue:\nLook for leadership decisions, policies, standards, risk planning, or oversight.\n\nExample:\nLeadership approves the security policy.\n\nContrast:\nTechnical = tools enforce it; Operational = people do it; Physical = locks/guards/barriers.",trick:"Exam map: Categories > Managerial"},
{cat:0,catName:"D1 General Concepts",acr:"Operational",full:"1.1 Compare and contrast various types of security controls.",def:"Definition:\nSecurity control performed by people or processes, such as guard duties, user training, reviews, and incident handling.\n\nClue:\nLook for people performing a process or routine security activity.\n\nExample:\nA guard checks badges at the door.\n\nContrast:\nTechnical = systems enforce it; Managerial = policies and oversight.",trick:"Exam map: Categories > Operational"},
{cat:0,catName:"D1 General Concepts",acr:"Physical",full:"1.1 Compare and contrast various types of security controls.",def:"Definition:\nSecurity control category that protects real-world facilities, rooms, people, equipment, and media. It includes things like fences, locks, guards, cameras, lighting, badges, and environmental protections.\n\nClue:\nLook for buildings, rooms, doors, locks, guards, cameras, lights, or badges.\n\nExample:\nA fence protects the building.\n\nContrast:\nTechnical = digital controls; Physical = real-world access and facility controls.",trick:"Exam map: Categories > Physical"},
{cat:0,catName:"D1 General Concepts",acr:"Preventive",full:"1.1 Compare and contrast various types of security controls.",def:"Definition:\nControl designed to stop a security event before it happens.\n\nClue:\nLook for stopping the event before it happens.\n\nExample:\nA locked door stops entry before it happens.\n\nContrast:\nDetective = finds events; Corrective = fixes after events.",trick:"Exam map: Control types > Preventive"},
{cat:0,catName:"D1 General Concepts",acr:"Deterrent",full:"1.1 Compare and contrast various types of security controls.",def:"Definition:\nControl designed to discourage an attack or policy violation without necessarily blocking it.\n\nClue:\nLook for discouraging behavior without directly blocking it.\n\nExample:\nA warning sign makes attackers think twice.\n\nContrast:\nPreventive blocks; Deterrent discourages.",trick:"Exam map: Control types > Deterrent"},
{cat:0,catName:"D1 General Concepts",acr:"Detective",full:"1.1 Compare and contrast various types of security controls.",def:"Definition:\nControl that identifies, logs, or alerts on suspicious activity.\n\nClue:\nLook for logging, alerting, monitoring, or identifying an event.\n\nExample:\nA log alert shows someone tried to log in.\n\nContrast:\nPreventive stops; Detective alerts or records.",trick:"Exam map: Control types > Detective"},
{cat:0,catName:"D1 General Concepts",acr:"Corrective",full:"1.1 Compare and contrast various types of security controls.",def:"Definition:\nControl used after an event to restore operations or reduce damage.\n\nClue:\nLook for fixing, restoring, or reducing damage after an event.\n\nExample:\nRestoring a backup after ransomware.\n\nContrast:\nPreventive stops before; Corrective fixes after.",trick:"Exam map: Control types > Corrective"},
{cat:0,catName:"D1 General Concepts",acr:"Compensating",full:"1.1 Compare and contrast various types of security controls.",def:"Definition:\nAlternate control used when the preferred control is not possible or not enough.\n\nClue:\nLook for an alternate control because the normal control is not possible.\n\nExample:\nAdd a firewall rule when a patch cannot be installed yet.\n\nContrast:\nPrimary control = preferred control; Compensating = alternate control.",trick:"Exam map: Control types > Compensating"},
{cat:0,catName:"D1 General Concepts",acr:"Directive",full:"1.1 Compare and contrast various types of security controls.",def:"Definition:\nControl that tells users what they should do, usually through policies, procedures, signs, or training.\n\nClue:\nLook for instructions, signs, policies, procedures, or training.\n\nExample:\nA sign says “Authorized personnel only.”\n\nContrast:\nPreventive blocks action; Directive tells people what to do.",trick:"Exam map: Control types > Directive"},
{cat:0,catName:"D1 General Concepts",acr:"Non-repudiation",full:"1.2 Summarize fundamental security concepts.",def:"Definition:\nProof that someone performed an action or sent a message, so they cannot credibly deny it later.\n\nClue:\nLook for the exact scenario words and match them to the safest, most specific answer.\n\nExample:\nA digital signature proves who signed a message.\n\nContrast:\nCompare it with nearby terms in the same objective to see why this answer fits best.",trick:"Exam map: 1.0 General Security Concepts"},
{cat:0,catName:"D1 General Concepts",acr:"Authenticating people",full:"1.2 Summarize fundamental security concepts.",def:"Definition:\nVerifying a human user identity with factors such as passwords, tokens, biometrics, or security keys.\n\nClue:\nLook for proving identity, assigning access, limiting privileges, or removing access.\n\nExample:\nPassword plus authenticator app.\n\nContrast:\nAuthentication proves identity; authorization decides access.",trick:"Exam map: Authentication, Authorization, and Accounting > Authenticating people"},
{cat:0,catName:"D1 General Concepts",acr:"Authenticating systems",full:"1.2 Summarize fundamental security concepts.",def:"Definition:\nVerifying a device, service, or application identity, often with certificates, keys, or mutual authentication.\n\nClue:\nLook for proving identity, assigning access, limiting privileges, or removing access.\n\nExample:\nA laptop uses a certificate to join VPN.\n\nContrast:\nAuthentication proves identity; authorization decides access.",trick:"Exam map: Authentication, Authorization, and Accounting > Authenticating systems"},
{cat:0,catName:"D1 General Concepts",acr:"Authorization models",full:"1.2 Summarize fundamental security concepts.",def:"Definition:\nMethods for deciding what an authenticated subject can access, such as role-based, rule-based, attribute-based, discretionary, or mandatory access control.\n\nClue:\nLook for proving identity, assigning access, limiting privileges, or removing access.\n\nExample:\nA nurse can open patient charts, not payroll.\n\nContrast:\nAuthentication proves identity; authorization decides access.",trick:"Exam map: Authentication, Authorization, and Accounting > Authorization models"},
{cat:0,catName:"D1 General Concepts",acr:"Gap analysis",full:"1.2 Summarize fundamental security concepts.",def:"Definition:\nComparison of the current state to a desired baseline so missing controls, processes, or capabilities can be identified.\n\nClue:\nLook for the exact scenario words and match them to the safest, most specific answer.\n\nExample:\nCompare current controls to NIST requirements.\n\nContrast:\nCompare it with nearby terms in the same objective to see why this answer fits best.",trick:"Exam map: 1.0 General Security Concepts"},
{cat:0,catName:"D1 General Concepts",acr:"Zero Trust",full:"1.2 Summarize fundamental security concepts.",def:"Definition:\nSecurity model where nothing is trusted automatically and every user, device, request, and session must be verified and authorized.\n\nClue:\nLook for the exact scenario words and match them to the safest, most specific answer.\n\nExample:\nEven inside the office, users must use MFA.\n\nContrast:\nCompare it with nearby terms in the same objective to see why this answer fits best.",trick:"Exam map: 1.0 General Security Concepts"},
{cat:0,catName:"D1 General Concepts",acr:"Control Plane",full:"1.2 Summarize fundamental security concepts.",def:"Definition:\nPart of a system or network that makes decisions, defines policy, and controls how data-plane actions should happen.\n\nClue:\nLook for whether the control must stop, detect, fix, discourage, substitute, or limit damage.\n\nExample:\nIt decides routing or access policy.\n\nContrast:\nThreat/vulnerability = problem; control/mitigation = defense.",trick:"Exam map: Zero Trust > Control Plane"},
{cat:0,catName:"D1 General Concepts",acr:"Adaptive identity",full:"1.2 Summarize fundamental security concepts.",def:"Definition:\nIdentity decision-making that changes based on risk signals such as location, device, behavior, and requested resource.\n\nClue:\nLook for proving identity, assigning access, limiting privileges, or removing access.\n\nExample:\nA login from a new country triggers MFA.\n\nContrast:\nThreat/vulnerability = problem; control/mitigation = defense.",trick:"Exam map: Zero Trust > Control Plane > Adaptive identity"},
{cat:0,catName:"D1 General Concepts",acr:"Threat scope reduction",full:"1.2 Summarize fundamental security concepts.",def:"Definition:\nReducing what an attacker can reach by limiting trust, segmenting access, and minimizing exposed systems.\n\nClue:\nLook for whether the control must stop, detect, fix, discourage, substitute, or limit damage.\n\nExample:\nSegment payroll away from guest Wi-Fi.\n\nContrast:\nMitigation/control = defense; this term describes the problem or weakness.",trick:"Exam map: Zero Trust > Control Plane > Threat scope reduction"},
{cat:0,catName:"D1 General Concepts",acr:"Policy-driven access control",full:"1.2 Summarize fundamental security concepts.",def:"Definition:\nAccess control where policies decide whether a request should be allowed, denied, or challenged.\n\nClue:\nLook for proving identity, assigning access, limiting privileges, or removing access.\n\nExample:\nOnly compliant laptops can access email.\n\nContrast:\nThreat/vulnerability = problem; control/mitigation = defense.",trick:"Exam map: Zero Trust > Control Plane > Policy-driven access control"},
{cat:0,catName:"D1 General Concepts",acr:"Policy Administrator",full:"1.2 Summarize fundamental security concepts.",def:"Definition:\nZero Trust component that applies policy decisions by creating, changing, or ending access sessions.\n\nClue:\nLook for ownership, documentation, testing scope, evidence, compliance, or risk decisions.\n\nExample:\nIt opens or closes the access session.\n\nContrast:\nThreat/vulnerability = problem; control/mitigation = defense.",trick:"Exam map: Zero Trust > Control Plane > Policy Administrator"},
{cat:0,catName:"D1 General Concepts",acr:"Policy Engine",full:"1.2 Summarize fundamental security concepts.",def:"Definition:\nZero Trust component that evaluates policy and risk signals to decide whether access should be allowed.\n\nClue:\nLook for ownership, documentation, testing scope, evidence, compliance, or risk decisions.\n\nExample:\nIt checks user, device, and location.\n\nContrast:\nThreat/vulnerability = problem; control/mitigation = defense.",trick:"Exam map: Zero Trust > Control Plane > Policy Engine"},
{cat:0,catName:"D1 General Concepts",acr:"Data Plane",full:"1.2 Summarize fundamental security concepts.",def:"Definition:\nPart of a system or network that actually forwards, processes, encrypts, or carries user traffic and data.\n\nClue:\nLook for where the asset lives, what can fail, and how the design protects or restores CIA.\n\nExample:\nIt forwards packets to the destination.\n\nContrast:\nThreat/vulnerability = problem; control/mitigation = defense.",trick:"Exam map: Zero Trust > Control Plane > Data Plane"},
{cat:0,catName:"D1 General Concepts",acr:"Implicit trust zones",full:"1.2 Summarize fundamental security concepts.",def:"Definition:\nAreas where access is trusted simply because of location or network position; Zero Trust tries to reduce these.\n\nClue:\nLook for whether the control must stop, detect, fix, discourage, substitute, or limit damage.\n\nExample:\nInternal users still need verification.\n\nContrast:\nThreat/vulnerability = problem; control/mitigation = defense.",trick:"Exam map: Zero Trust > Control Plane > Implicit trust zones"},
{cat:0,catName:"D1 General Concepts",acr:"Subject/System",full:"1.2 Summarize fundamental security concepts.",def:"Definition:\nThe user, service, device, or workload requesting access to a resource.\n\nClue:\nLook for whether the control must stop, detect, fix, discourage, substitute, or limit damage.\n\nExample:\nA user, app, or device requests access.\n\nContrast:\nThreat/vulnerability = problem; control/mitigation = defense.",trick:"Exam map: Zero Trust > Control Plane > Subject/System"},
{cat:0,catName:"D1 General Concepts",acr:"Policy Enforcement Point",full:"1.2 Summarize fundamental security concepts.",def:"Definition:\nThe gatekeeper that allows, blocks, or terminates access based on policy decisions.\n\nClue:\nLook for ownership, documentation, testing scope, evidence, compliance, or risk decisions.\n\nExample:\nIt blocks a risky login.\n\nContrast:\nThreat/vulnerability = problem; control/mitigation = defense.",trick:"Exam map: Zero Trust > Control Plane > Policy Enforcement Point"},
{cat:0,catName:"D1 General Concepts",acr:"Physical security",full:"1.2 Summarize fundamental security concepts.",def:"Definition:\nBroad category covering controls that protect real-world facilities, equipment, and people. Includes bollards, fences, guards, cameras, locks, lighting, access badges, mantrap vestibules, and environmental sensors.\n\nClue:\nLook for a tangible, real-world barrier, deterrent, or monitor at a physical location.\n\nExample:\nData center uses cameras, guards, badge readers, and bollards together as layered physical controls.\n\nContrast:\nTechnical = software/system controls; Physical = tangible controls protecting the physical environment.",trick:"Exam map: Physical security"},
{cat:0,catName:"D1 General Concepts",acr:"Bollards",full:"1.2 Summarize fundamental security concepts.",def:"Definition:\nPhysical posts used to stop or slow vehicles from entering protected areas.\n\nClue:\nLook for the exact scenario words and match them to the safest, most specific answer.\n\nExample:\nPosts stop a vehicle from ramming a lobby.\n\nContrast:\nCompare it with nearby terms in the same objective to see why this answer fits best.",trick:"Exam map: Physical security > Bollards"},
{cat:0,catName:"D1 General Concepts",acr:"Access control vestibule",full:"1.2 Summarize fundamental security concepts.",def:"Definition:\nSmall controlled entry area with two doors that limits tailgating and controls physical access.\n\nClue:\nLook for proving identity, assigning access, limiting privileges, or removing access.\n\nExample:\nA mantrap stops tailgating.\n\nContrast:\nThreat/vulnerability = problem; control/mitigation = defense.",trick:"Exam map: Physical security > Access control vestibule"},
{cat:0,catName:"D1 General Concepts",acr:"Fencing",full:"1.2 Summarize fundamental security concepts.",def:"Definition:\nPhysical boundary used to deter, delay, or direct access around a protected area.\n\nClue:\nLook for the exact scenario words and match them to the safest, most specific answer.\n\nExample:\nA fence slows entry to a data center yard.\n\nContrast:\nCompare it with nearby terms in the same objective to see why this answer fits best.",trick:"Exam map: Physical security > Fencing"},
{cat:0,catName:"D1 General Concepts",acr:"Video surveillance",full:"1.2 Summarize fundamental security concepts.",def:"Definition:\nCamera monitoring used to detect, record, and investigate physical security events.\n\nClue:\nLook for the exact scenario words and match them to the safest, most specific answer.\n\nExample:\nCCTV records who entered after hours.\n\nContrast:\nCompare it with nearby terms in the same objective to see why this answer fits best.",trick:"Exam map: Physical security > Video surveillance"},
{cat:0,catName:"D1 General Concepts",acr:"Security guard",full:"1.2 Summarize fundamental security concepts.",def:"Definition:\nPerson assigned to monitor, control, and respond to physical security events.\n\nClue:\nLook for the exact scenario words and match them to the safest, most specific answer.\n\nExample:\nA guard verifies visitors before entry.\n\nContrast:\nCompare it with nearby terms in the same objective to see why this answer fits best.",trick:"Exam map: Physical security > Security guard"},
{cat:0,catName:"D1 General Concepts",acr:"Access badge",full:"1.2 Summarize fundamental security concepts.",def:"Definition:\nPhysical or electronic credential used to identify a person and grant controlled access.\n\nClue:\nLook for proving identity, assigning access, limiting privileges, or removing access.\n\nExample:\nTap a badge to enter the server room.\n\nContrast:\nAuthentication proves identity; authorization decides access.",trick:"Exam map: Physical security > Access badge"},
{cat:0,catName:"D1 General Concepts",acr:"Lighting",full:"1.2 Summarize fundamental security concepts.",def:"Definition:\nPhysical security control that improves visibility and deters unauthorized activity.\n\nClue:\nLook for the exact scenario words and match them to the safest, most specific answer.\n\nExample:\nParking lot lights reduce hiding places.\n\nContrast:\nCompare it with nearby terms in the same objective to see why this answer fits best.",trick:"Exam map: Physical security > Lighting"},
{cat:0,catName:"D1 General Concepts",acr:"Sensors",full:"1.2 Summarize fundamental security concepts.",def:"Definition:\nDevices that detect physical conditions or movement and trigger alerts or actions.\n\nClue:\nLook for the exact scenario words and match them to the safest, most specific answer.\n\nExample:\nA door sensor alerts when opened.\n\nContrast:\nCompare it with nearby terms in the same objective to see why this answer fits best.",trick:"Exam map: Physical security > Sensors"},
{cat:0,catName:"D1 General Concepts",acr:"Infrared",full:"1.2 Summarize fundamental security concepts.",def:"Definition:\nSensor type that detects heat or infrared energy, often used for motion detection.\n\nClue:\nLook for the exact scenario words and match them to the safest, most specific answer.\n\nExample:\nDetect motion by body heat.\n\nContrast:\nCompare it with nearby terms in the same objective to see why this answer fits best.",trick:"Exam map: Physical security > Sensors > Infrared"},
{cat:0,catName:"D1 General Concepts",acr:"Pressure",full:"1.2 Summarize fundamental security concepts.",def:"Definition:\nSensor type that detects weight or force, such as a pressure mat or floor sensor.\n\nClue:\nLook for the exact scenario words and match them to the safest, most specific answer.\n\nExample:\nA floor mat detects footsteps.\n\nContrast:\nCompare it with nearby terms in the same objective to see why this answer fits best.",trick:"Exam map: Physical security > Sensors > Pressure"},
{cat:0,catName:"D1 General Concepts",acr:"Microwave",full:"1.2 Summarize fundamental security concepts.",def:"Definition:\nSensor type that uses microwave signals to detect motion or intrusion.\n\nClue:\nLook for the exact scenario words and match them to the safest, most specific answer.\n\nExample:\nMotion sensor in a hallway.\n\nContrast:\nCompare it with nearby terms in the same objective to see why this answer fits best.",trick:"Exam map: Physical security > Sensors > Microwave"},
{cat:0,catName:"D1 General Concepts",acr:"Ultrasonic",full:"1.2 Summarize fundamental security concepts.",def:"Definition:\nSensor type that uses high-frequency sound waves to detect motion.\n\nClue:\nLook for the exact scenario words and match them to the safest, most specific answer.\n\nExample:\nIt detects motion by sound reflection.\n\nContrast:\nCompare it with nearby terms in the same objective to see why this answer fits best.",trick:"Exam map: Physical security > Sensors > Ultrasonic"},
{cat:0,catName:"D1 General Concepts",acr:"Deception and disruption technology",full:"1.2 Summarize fundamental security concepts.",def:"Definition:\nCategory of controls that use fake or decoy assets to attract, detect, and study attackers. Includes honeypots (decoy systems), honeynets (decoy networks), honeyfiles (decoy files), and honeytokens (fake credentials or data).\n\nClue:\nLook for fake or decoy assets designed to lure and catch attackers in the act.\n\nExample:\nA fake server records attacker commands and TTPs without risking real data.\n\nContrast:\nPreventive controls stop attacks; Deception controls detect attackers and gather intelligence on their methods.",trick:"Exam map: Deception and disruption technology"},
{cat:0,catName:"D1 General Concepts",acr:"Honeypot",full:"1.2 Summarize fundamental security concepts.",def:"Definition:\nDecoy system designed to attract attackers and study or detect malicious activity.\n\nClue:\nLook for the exact scenario words and match them to the safest, most specific answer.\n\nExample:\nA decoy server catches scanning attackers.\n\nContrast:\nCompare it with nearby terms in the same objective to see why this answer fits best.",trick:"Exam map: Deception and disruption technology > Honeypot"},
{cat:0,catName:"D1 General Concepts",acr:"Honeynet",full:"1.2 Summarize fundamental security concepts.",def:"Definition:\nNetwork of decoy systems used to observe attacker behavior across multiple fake targets.\n\nClue:\nLook for the exact scenario words and match them to the safest, most specific answer.\n\nExample:\nMultiple decoy machines record attacker moves.\n\nContrast:\nCompare it with nearby terms in the same objective to see why this answer fits best.",trick:"Exam map: Deception and disruption technology > Honeynet"},
{cat:0,catName:"D1 General Concepts",acr:"Honeyfile",full:"1.2 Summarize fundamental security concepts.",def:"Definition:\nDecoy file used to detect unauthorized access or attacker activity.\n\nClue:\nLook for the exact scenario words and match them to the safest, most specific answer.\n\nExample:\n“Payroll.xlsx” alerts if opened.\n\nContrast:\nCompare it with nearby terms in the same objective to see why this answer fits best.",trick:"Exam map: Deception and disruption technology > Honeyfile"},
{cat:0,catName:"D1 General Concepts",acr:"Honeytoken",full:"1.2 Summarize fundamental security concepts.",def:"Definition:\nFake credential, record, or value that alerts defenders if used or accessed.\n\nClue:\nLook for proving identity, assigning access, limiting privileges, or removing access.\n\nExample:\nA fake API key alerts when used.\n\nContrast:\nCompare it with nearby terms in the same objective to see why this answer fits best.",trick:"Exam map: Deception and disruption technology > Honeytoken"},
{cat:0,catName:"D1 General Concepts",acr:"Approval process",full:"1.3 Explain the importance of change management processes and the impact to security.",def:"Definition:\nFormal review and authorization required before a change is implemented. Ensures the right people assess risk, test results, and impact before production changes.\n\nClue:\nLook for authorization steps: who must sign off before a change goes live.\n\nExample:\nFirewall rule change requires manager and security team approval before deployment.\n\nContrast:\nApproval process = authorization gate; Backout plan = what to do if the approved change fails.",trick:"Exam map: Business processes impacting security operation > Approval process"},
{cat:0,catName:"D1 General Concepts",acr:"Ownership",full:"1.3 Explain the importance of change management processes and the impact to security.",def:"Definition:\nClear accountability for a system, data set, risk, process, or change. The owner is responsible for decisions and approvals.\n\nClue:\nLook for accountability — who is responsible for approving changes to or access for a specific system or dataset.\n\nExample:\nThe database owner must approve any change that affects database configuration.\n\nContrast:\nOwner = accountable decision-maker; Custodian = day-to-day handler; Stakeholder = anyone affected.",trick:"Exam map: Business processes impacting security operation > Ownership"},
{cat:0,catName:"D1 General Concepts",acr:"Stakeholders",full:"1.3 Explain the importance of change management processes and the impact to security.",def:"Definition:\nPeople or groups affected by a decision, system, risk, or change. Must be identified and involved in the change process.\n\nClue:\nLook for who needs to be consulted or notified about a change — users, help desk, management, security team.\n\nExample:\nA network change stakeholders include help desk (handles calls), users (experience downtime), and security (reviews impact).\n\nContrast:\nOwner = accountable approver; Stakeholders = broader group of affected or interested parties.",trick:"Exam map: Business processes impacting security operation > Stakeholders"},
{cat:0,catName:"D1 General Concepts",acr:"Impact analysis",full:"1.3 Explain the importance of change management processes and the impact to security.",def:"Definition:\nEvaluation of how a proposed change, outage, risk, or incident will affect systems, users, and business operations. Required before approving a change.\n\nClue:\nLook for assessing what breaks or is affected — which systems depend on this, who loses access, what downtime occurs.\n\nExample:\nRestarting the authentication server will lock out all users until it's back — this is the impact.\n\nContrast:\nImpact analysis = scoping the blast radius; Risk analysis = assessing likelihood and severity.",trick:"Exam map: Business processes impacting security operation > Impact analysis"},
{cat:0,catName:"D1 General Concepts",acr:"Test results",full:"1.3 Explain the importance of change management processes and the impact to security.",def:"Definition:\nDocumented evidence showing whether a change, control, or system behaved as expected during testing. Required before production approval.\n\nClue:\nLook for documented proof that a change was tested and the outcome. Must be reviewed as part of change approval.\n\nExample:\nPatch applied and tested in staging environment — test results show no service disruption.\n\nContrast:\nTest results = evidence a change works; Approval process = uses that evidence to authorize deployment.",trick:"Exam map: Business processes impacting security operation > Test results"},
{cat:0,catName:"D1 General Concepts",acr:"Backout plan",full:"1.3 Explain the importance of change management processes and the impact to security.",def:"Definition:\nDocumented steps for reversing a failed change and returning the system to its previous working state. Must be prepared and approved before any change is deployed.\n\nClue:\nLook for the rollback or undo procedure when a change fails. Every change should have one before deployment.\n\nExample:\nIf the router config update breaks connectivity, restore the previous config from backup.\n\nContrast:\nApproval process = going forward; Backout plan = what happens if we need to go back.",trick:"Exam map: Business processes impacting security operation > Backout plan"},
{cat:0,catName:"D1 General Concepts",acr:"Maintenance window",full:"1.3 Explain the importance of change management processes and the impact to security.",def:"Definition:\nPre-approved time window during which changes can be made to minimize business impact. Chosen when usage is lowest to limit disruption.\n\nClue:\nLook for a scheduled time slot for changes — off-hours, weekends, or low-traffic periods.\n\nExample:\nPatching scheduled Sunday 2 AM–4 AM when fewer users are active.\n\nContrast:\nMaintenance window = when to make changes; Change management = the overall process for approving and executing them.",trick:"Exam map: Business processes impacting security operation > Maintenance window"},
{cat:0,catName:"D1 General Concepts",acr:"Standard operating procedure",full:"1.3 Explain the importance of change management processes and the impact to security.",def:"Definition:\nDocumented, repeatable step-by-step instructions for performing a routine task consistently and correctly every time.\n\nClue:\nLook for a checklist or step-by-step procedure document that guides a repeatable process.\n\nExample:\nThe account reset SOP lists exactly which steps to follow and what verification is required.\n\nContrast:\nPolicy = what must be done; SOP = exactly how to do it step by step.",trick:"Exam map: Business processes impacting security operation > Standard operating procedure"},
{cat:0,catName:"D1 General Concepts",acr:"Allow lists/deny lists",full:"1.3 Explain the importance of change management processes and the impact to security.",def:"Definition:\nAllow lists (whitelists) permit only approved items to run or connect — everything else is blocked. Deny lists (blacklists) block known bad items — everything else is allowed.\n\nClue:\nAllow list = default deny (most restrictive); Deny list = default allow (blocks known bad only).\n\nExample:\nApplication allow list only lets approved executables run; deny list blocks known malware hashes.\n\nContrast:\nAllow list = more secure but more management overhead; Deny list = easier but misses unknown threats.",trick:"Exam map: Technical implications > Allow lists/deny lists"},
{cat:0,catName:"D1 General Concepts",acr:"Restricted activities",full:"1.3 Explain the importance of change management processes and the impact to security.",def:"Definition:\nActions prohibited or limited during or around a change window because they increase risk — e.g., no other changes permitted while a critical system is being updated.\n\nClue:\nLook for things users or admins are NOT allowed to do during a maintenance or change period.\n\nExample:\nDuring OS upgrade, no other configuration changes are permitted on that server.\n\nContrast:\nRestricted activities = what's forbidden during change; Maintenance window = when the change happens.",trick:"Exam map: Technical implications > Restricted activities"},
{cat:0,catName:"D1 General Concepts",acr:"Downtime",full:"1.3 Explain the importance of change management processes and the impact to security.",def:"Definition:\nPeriod when a system or service is unavailable, often planned during a maintenance window or unplanned due to failure. A key technical implication of change management.\n\nClue:\nLook for the availability impact of a change — how long will the system be down and who is affected.\n\nExample:\nWebsite offline for 30 minutes during patching — users cannot place orders during that window.\n\nContrast:\nPlanned downtime = scheduled maintenance; Unplanned downtime = outage from failure or attack (loss of Availability).",trick:"Exam map: Technical implications > Downtime"},
{cat:0,catName:"D1 General Concepts",acr:"Service restart",full:"1.3 Explain the importance of change management processes and the impact to security.",def:"Definition:\nStopping and restarting a running service, often required for configuration or patch changes to take effect. Creates brief downtime for that specific service.\n\nClue:\nLook for a required restart of a service (not the whole OS) as a consequence of a change.\n\nExample:\nApache web service restarted after SSL certificate change — brief connection interruption occurs.\n\nContrast:\nService restart = one service interrupted; System reboot = entire OS restarted, all services affected.",trick:"Exam map: Technical implications > Service restart"},
{cat:0,catName:"D1 General Concepts",acr:"Application restart",full:"1.3 Explain the importance of change management processes and the impact to security.",def:"Definition:\nStopping and relaunching an application so configuration changes or patches take effect. Affects only users of that specific application.\n\nClue:\nLook for the need to restart just the application (not the OS or service) for a change to take effect.\n\nExample:\nDatabase application restarted after connection pool configuration change.\n\nContrast:\nApplication restart = one app interrupted; Service restart = underlying service; System reboot = everything.",trick:"Exam map: Technical implications > Application restart"},
{cat:0,catName:"D1 General Concepts",acr:"Legacy applications",full:"1.3 Explain the importance of change management processes and the impact to security.",def:"Definition:\nOlder applications that are difficult to patch, update, or integrate with modern security controls. Often cannot be changed without breaking dependent processes, creating persistent risk.\n\nClue:\nLook for old software that creates complications in change management — can't be patched or upgraded easily.\n\nExample:\nOld accounting software cannot be patched; compensating controls (network segmentation) must be used instead.\n\nContrast:\nLegacy applications = old and hard to change; End-of-life = vendor no longer provides any updates.",trick:"Exam map: Technical implications > Legacy applications"},
{cat:0,catName:"D1 General Concepts",acr:"Dependencies",full:"1.3 Explain the importance of change management processes and the impact to security.",def:"Definition:\nSystems, services, libraries, or processes that another system relies on to function. A change to one component can break dependent systems — dependencies must be mapped before any change.\n\nClue:\nLook for what other systems or services will be affected when the changed component is restarted or modified.\n\nExample:\nChanging the authentication service affects every app that depends on it for login.\n\nContrast:\nDependencies = what a system relies on; Impact analysis = the process of identifying all those dependencies before a change.",trick:"Exam map: Technical implications > Dependencies"},
{cat:0,catName:"D1 General Concepts",acr:"Updating diagrams",full:"1.3 Explain the importance of change management processes and the impact to security.",def:"Definition:\nRevising network, system, or architecture diagrams to reflect changes made. Accurate documentation is a required output of change management — outdated diagrams create security and operational risk.\n\nClue:\nLook for documentation that must be updated after a change — network maps, topology diagrams, data flow charts.\n\nExample:\nAfter adding a new firewall, update the network diagram to show the new device and rule sets.\n\nContrast:\nUpdating diagrams = visual/graphical documentation; Updating policies/procedures = written guidance.",trick:"Exam map: Documentation > Updating diagrams"},
{cat:0,catName:"D1 General Concepts",acr:"Updating policies/procedures",full:"1.3 Explain the importance of change management processes and the impact to security.",def:"Definition:\nRevising written policies and procedures to reflect changes in systems, processes, or requirements. Ensures staff follow current and accurate guidance after a change is implemented.\n\nClue:\nLook for written documentation that must reflect a change — acceptable use policies, SOPs, incident response procedures.\n\nExample:\nAfter adopting MFA, the access policy is updated to require MFA for all remote logins.\n\nContrast:\nPolicies = what must be done (rules); Procedures = how to do it (steps); Diagrams = visual documentation.",trick:"Exam map: Documentation > Updating policies/procedures"},
{cat:0,catName:"D1 General Concepts",acr:"Version control",full:"1.3 Explain the importance of change management processes and the impact to security.",def:"Definition:\nTracking changes to files, code, or configurations so history, rollback, and accountability are available.\n\nClue:\nLook for whether the control must stop, detect, fix, discourage, substitute, or limit damage.\n\nExample:\nGit shows who changed code and when.\n\nContrast:\nInsecure protocol = avoid when confidentiality is needed; secure protocol = prefer for protected communication.",trick:"Exam map: 1.0 General Security Concepts"},
{cat:0,catName:"D1 General Concepts",acr:"Public key",full:"1.4 Explain the importance of using appropriate cryptographic solutions.",def:"Definition:\nShareable key in asymmetric cryptography used to encrypt data to the owner or verify signatures.\n\nClue:\nLook for the shareable key in asymmetric cryptography.\n\nExample:\nAnyone can use it to send you encrypted data.\n\nContrast:\nPrivate key must stay secret.",trick:"Exam map: Public key infrastructure (PKI) > Public key"},
{cat:0,catName:"D1 General Concepts",acr:"Private key",full:"1.4 Explain the importance of using appropriate cryptographic solutions.",def:"Definition:\nSecret key in asymmetric cryptography used to decrypt data or create digital signatures.\n\nClue:\nLook for the secret key that must be protected.\n\nExample:\nOnly you can decrypt data sent to your public key.\n\nContrast:\nPublic key can be shared.",trick:"Exam map: Public key infrastructure (PKI) > Private key"},
{cat:0,catName:"D1 General Concepts",acr:"Key escrow",full:"1.4 Explain the importance of using appropriate cryptographic solutions.",def:"Definition:\nStoring encryption keys with a trusted party or system so data can be recovered under approved conditions.\n\nClue:\nLook for where the asset lives, what can fail, and how the design protects or restores CIA.\n\nExample:\nCompany recovers encrypted files after employee leaves.\n\nContrast:\nInsecure protocol = avoid when confidentiality is needed; secure protocol = prefer for protected communication.",trick:"Exam map: Public key infrastructure (PKI) > Key escrow"},
{cat:0,catName:"D1 General Concepts",acr:"Encryption",full:"1.4 Explain the importance of using appropriate cryptographic solutions.",def:"Definition:\nConverting readable data into unreadable ciphertext using an algorithm and key.\n\nClue:\nLook for protecting confidentiality by making data unreadable without a key.\n\nExample:\nTLS hides web traffic.\n\nContrast:\nHashing verifies integrity; Encryption protects confidentiality and is reversible with a key.",trick:"Exam map: 1.0 General Security Concepts"},
{cat:0,catName:"D1 General Concepts",acr:"Level",full:"1.4 Explain the importance of using appropriate cryptographic solutions.",def:"Definition:\nThe scope at which encryption is applied. Options: full-disk (entire drive), partition, file, volume, database, record/field, or transport (data in motion). Each level protects a different scope of data.\n\nClue:\nMatch what needs protecting to the right encryption level: whole drive = full-disk; moving data = transport; individual rows = record-level.\n\nExample:\nFull-disk encryption protects a lost laptop; TLS protects data moving between server and browser.\n\nContrast:\nHigher granularity (record-level) = finer control; Full-disk = coarser but simpler and covers all data.",trick:"Exam map: Encryption > Level"},
{cat:0,catName:"D1 General Concepts",acr:"Full-disk",full:"1.4 Explain the importance of using appropriate cryptographic solutions.",def:"Definition:\nEncryption applied to the entire storage device. Protects all data if the device is lost or stolen. Examples: BitLocker (Windows), FileVault (macOS). Does NOT protect data once the OS is booted and unlocked.\n\nClue:\nLook for protecting a lost or stolen laptop/drive — data is unreadable without the decryption key.\n\nExample:\nBitLocker full-disk encryption means a stolen laptop's drive is unreadable without the recovery key.\n\nContrast:\nFull-disk = protects data at rest on the device; TLS = protects data in transit; File-level = only protects specific files.",trick:"Exam map: Encryption > Level > Full-disk"},
{cat:0,catName:"D1 General Concepts",acr:"Partition",full:"1.4 Explain the importance of using appropriate cryptographic solutions.",def:"Definition:\nEncryption applied to a specific logical partition of a disk, leaving other partitions unencrypted. Allows selective protection of sensitive data sections.\n\nClue:\nLook for protecting just a portion of a disk rather than the whole drive.\n\nExample:\nEncrypt only the D: work partition that holds sensitive files, leaving the OS partition unencrypted.\n\nContrast:\nFull-disk = encrypts everything; Partition = selective encryption of a disk section.",trick:"Exam map: Encryption > Level > Partition"},
{cat:0,catName:"D1 General Concepts",acr:"File",full:"1.4 Explain the importance of using appropriate cryptographic solutions.",def:"Definition:\nEncryption applied to individual files. Offers fine-grained control — each file can have its own encryption status and key. Useful for sharing specific protected files.\n\nClue:\nLook for protecting specific files rather than whole drives or partitions.\n\nExample:\nEncrypt a tax return PDF before emailing it; only the recipient with the key can open it.\n\nContrast:\nFile-level = most granular; Full-disk = coarsest; Volume/partition = intermediate.",trick:"Exam map: Encryption > Level > File"},
{cat:0,catName:"D1 General Concepts",acr:"Volume",full:"1.4 Explain the importance of using appropriate cryptographic solutions.",def:"Definition:\nEncryption applied to a logical volume — a virtual container that can span multiple physical drives. Often used for encrypted vaults or portable encrypted storage containers.\n\nClue:\nLook for an encrypted logical storage container that can be mounted and unmounted.\n\nExample:\nVeraCrypt encrypted volume mounts as a drive letter; data is protected when unmounted.\n\nContrast:\nVolume = logical container spanning drives; Partition = physical section of a single disk.",trick:"Exam map: Encryption > Level > Volume"},
{cat:0,catName:"D1 General Concepts",acr:"Database",full:"1.4 Explain the importance of using appropriate cryptographic solutions.",def:"Definition:\nEncryption applied at the database level — protecting the entire database, specific tables, or individual columns/records. Transparent Data Encryption (TDE) is a common implementation.\n\nClue:\nLook for protecting data stored in a database from unauthorized access even by DBAs or via direct file access.\n\nExample:\nTDE encrypts the database files so even someone who copies them cannot read the data without the key.\n\nContrast:\nDatabase-level = protects all DB data; Record-level = finer control protecting individual rows or fields.",trick:"Exam map: Encryption > Level > Database"},
{cat:0,catName:"D1 General Concepts",acr:"Record",full:"1.4 Explain the importance of using appropriate cryptographic solutions.",def:"Definition:\nThe most granular encryption level — applied to individual database records, rows, or fields. Allows different users to decrypt only the records they're authorized to see.\n\nClue:\nLook for protecting individual rows or fields within a database, each encrypted separately.\n\nExample:\nEach patient's SSN is encrypted with a unique key — a nurse can only decrypt records for their assigned patients.\n\nContrast:\nRecord-level = finest granularity; Database-level = whole database; File-level = whole files.",trick:"Exam map: Encryption > Level > Record"},
{cat:0,catName:"D1 General Concepts",acr:"Transport/communication",full:"1.4 Explain the importance of using appropriate cryptographic solutions.",def:"Definition:\nProtection for data moving between systems, usually with protocols such as TLS or VPNs.\n\nClue:\nLook for what service is being connected, whether it is encrypted, and the safer protocol choice.\n\nExample:\nHTTPS protects browser traffic.\n\nContrast:\nInsecure protocol = avoid when confidentiality is needed; secure protocol = prefer for protected communication.",trick:"Exam map: Encryption > Transport/communication"},
{cat:0,catName:"D1 General Concepts",acr:"Asymmetric",full:"1.4 Explain the importance of using appropriate cryptographic solutions.",def:"Definition:\nCryptography using a public/private key pair.\n\nClue:\nLook for public/private key pairs.\n\nExample:\nPublic key encrypts, private key decrypts.\n\nContrast:\nSymmetric = one shared key.",trick:"Exam map: Encryption > Asymmetric"},
{cat:0,catName:"D1 General Concepts",acr:"Symmetric",full:"1.4 Explain the importance of using appropriate cryptographic solutions.",def:"Definition:\nCryptography using the same shared key for encryption and decryption.\n\nClue:\nLook for one shared key used by both sides.\n\nExample:\nAES encrypts a file.\n\nContrast:\nAsymmetric = public/private key pair.",trick:"Exam map: Encryption > Symmetric"},
{cat:0,catName:"D1 General Concepts",acr:"Key exchange",full:"1.4 Explain the importance of using appropriate cryptographic solutions.",def:"Definition:\nSecurely establishing a shared cryptographic key between two parties over an insecure channel. Diffie-Hellman (DH) is the classic method. Used to create symmetric session keys for bulk encryption.\n\nClue:\nLook for how two parties agree on a shared key without transmitting it — the answer is Diffie-Hellman or ECDH.\n\nExample:\nTLS handshake uses DHE or ECDHE to establish a session key even if traffic is intercepted.\n\nContrast:\nKey exchange = how to share a key securely; Asymmetric encryption = an alternative but slower method to protect keys.",trick:"Exam map: Encryption > Key exchange"},
{cat:0,catName:"D1 General Concepts",acr:"Algorithms",full:"1.4 Explain the importance of using appropriate cryptographic solutions.",def:"Definition:\nMathematical methods that perform cryptographic operations. Key ones: AES (symmetric encryption), RSA/ECC (asymmetric), SHA-256/SHA-3 (hashing), PBKDF2/bcrypt (key stretching), DH/ECDH (key exchange).\n\nClue:\nKnow which algorithm does what: AES = encrypt data; RSA = encrypt/sign with keys; SHA = hash/integrity; DH = key exchange.\n\nExample:\nAES-256 encrypts files; RSA-2048 encrypts the AES key; SHA-256 verifies the file integrity.\n\nContrast:\nAlgorithm = the math recipe; Key = the secret input to the algorithm. Weak algorithm = vulnerable even with good key.",trick:"Exam map: Encryption > Algorithms"},
{cat:0,catName:"D1 General Concepts",acr:"Key length",full:"1.4 Explain the importance of using appropriate cryptographic solutions.",def:"Definition:\nThe size of a cryptographic key in bits. Longer keys exponentially increase brute force difficulty. Current minimums: AES-128 (acceptable), AES-256 (recommended); RSA-2048 (minimum); ECC-256 (equivalent to RSA-3072).\n\nClue:\nLonger key = stronger encryption against brute force. Match the algorithm: AES uses 128/256-bit; RSA uses 2048/4096-bit.\n\nExample:\nAES-256 is stronger than AES-128 because it has 2^256 possible keys vs. 2^128.\n\nContrast:\nAlgorithm choice matters too — AES-128 is stronger than RSA-512 even though the key is shorter.",trick:"Exam map: Encryption > Key length"},
{cat:0,catName:"D1 General Concepts",acr:"Key management system",full:"1.4 Explain the importance of using appropriate cryptographic solutions.",def:"Definition:\nSystem used to generate, store, distribute, rotate, and revoke cryptographic keys. Centralizes key lifecycle management to prevent key loss, unauthorized access, or reuse of compromised keys.\n\nClue:\nLook for centralized control of cryptographic key lifecycle: creation, storage, distribution, rotation, and revocation.\n\nExample:\nCloud KMS rotates encryption keys annually and logs all key usage for audit.\n\nContrast:\nKey escrow = storing keys with a third party for recovery; KMS = active management of key lifecycle.",trick:"Exam map: Tools > Key management system"},
{cat:0,catName:"D1 General Concepts",acr:"Secure enclave",full:"1.4 Explain the importance of using appropriate cryptographic solutions.",def:"Definition:\nHardware-isolated area within a processor that protects secrets and performs cryptographic operations. Even the OS cannot access data inside the enclave. Examples: Apple T2 chip, Intel SGX, ARM TrustZone.\n\nClue:\nLook for hardware-level isolation of cryptographic operations that the OS and apps cannot reach.\n\nExample:\nApple iPhone stores biometric data in the Secure Enclave — even a compromised iOS cannot extract it.\n\nContrast:\nTPM = stores keys and performs attestation; Secure Enclave = broader isolated execution environment for secrets.",trick:"Exam map: Tools > Secure enclave"},
{cat:0,catName:"D1 General Concepts",acr:"Obfuscation",full:"1.4 Explain the importance of using appropriate cryptographic solutions.",def:"Definition:\nMaking data, code, or communications harder to understand without using reversible encryption. Techniques include steganography, tokenization, data masking, and code obfuscation. Not a substitute for encryption.\n\nClue:\nLook for hiding or obscuring data/code meaning without fully encrypting it.\n\nExample:\nCode obfuscation makes malware analysis harder; steganography hides data inside images.\n\nContrast:\nEncryption = mathematically reversible with a key; Obfuscation = harder to read but not truly cryptographically secure.",trick:"Exam map: Obfuscation"},
{cat:0,catName:"D1 General Concepts",acr:"Steganography",full:"1.4 Explain the importance of using appropriate cryptographic solutions.",def:"Definition:\nHiding secret data inside ordinary-looking files (images, audio, video, documents) so its existence isn't obvious. The carrier file looks normal to observers.\n\nClue:\nLook for hiding the existence of data rather than just scrambling it. The medium looks innocent.\n\nExample:\nSecret message embedded in the least-significant bits of an image file — image looks normal but carries hidden data.\n\nContrast:\nEncryption = data is obviously encrypted but unreadable; Steganography = data existence is hidden inside normal-looking content.",trick:"Exam map: Obfuscation > Steganography"},
{cat:0,catName:"D1 General Concepts",acr:"Tokenization",full:"1.4 Explain the importance of using appropriate cryptographic solutions.",def:"Definition:\nReplacing sensitive data with a random, non-sensitive placeholder (token). The mapping between token and real data is stored in a secure token vault. Common in PCI DSS for credit card data.\n\nClue:\nLook for replacing real sensitive values with random substitutes — the token has no mathematical relationship to the original.\n\nExample:\nPOS system stores payment token '8fA9x2' instead of the real credit card number; vault maps it back.\n\nContrast:\nEncryption = reversible with a key using math; Tokenization = replacement with no mathematical relationship, requires vault lookup.",trick:"Exam map: Obfuscation > Tokenization"},
{cat:0,catName:"D1 General Concepts",acr:"Data masking",full:"1.4 Explain the importance of using appropriate cryptographic solutions.",def:"Definition:\nObscuring part of sensitive data so users can work with it without seeing the full value. The masked portion is replaced with asterisks or dummy characters.\n\nClue:\nLook for partial display of sensitive data: only some characters shown, rest replaced with * or X.\n\nExample:\nSSN displayed as ***-**-1234 on screen; credit card shown as ****-****-****-5678.\n\nContrast:\nTokenization = full replacement with a token; Masking = partial concealment for display purposes.",trick:"Exam map: Obfuscation > Data masking"},
{cat:0,catName:"D1 General Concepts",acr:"Hashing",full:"1.4 Explain the importance of using appropriate cryptographic solutions.",def:"Definition:\nOne-way function that creates a fixed-length digest used to verify integrity.\n\nClue:\nLook for integrity checking, fingerprints, or verifying data did not change.\n\nExample:\nCompare file hash to prove it did not change.\n\nContrast:\nEncryption is reversible with a key; Hashing is one-way.",trick:"Exam map: 1.0 General Security Concepts"},
{cat:0,catName:"D1 General Concepts",acr:"Salting",full:"1.4 Explain the importance of using appropriate cryptographic solutions.",def:"Definition:\nAdding random data before hashing a password to make identical passwords produce different hashes.\n\nClue:\nLook for protecting password hashes from matching and precomputed attacks.\n\nExample:\nSame password gets different hashes.\n\nContrast:\nHashing fingerprints data; Salting adds uniqueness before hashing passwords.",trick:"Exam map: 1.0 General Security Concepts"},
{cat:0,catName:"D1 General Concepts",acr:"Digital signatures",full:"1.4 Explain the importance of using appropriate cryptographic solutions.",def:"Definition:\nCryptographic proof that verifies integrity, authenticates the signer, and supports non-repudiation.\n\nClue:\nLook for integrity, signer identity, and non-repudiation.\n\nExample:\nVerify a software update came from the vendor.\n\nContrast:\nEncryption hides data; Digital signatures prove integrity and origin.",trick:"Exam map: 1.0 General Security Concepts"},
{cat:0,catName:"D1 General Concepts",acr:"Key stretching",full:"1.4 Explain the importance of using appropriate cryptographic solutions.",def:"Definition:\nMaking a weak password-derived key computationally expensive to brute force by applying a slow derivation function many times. Key algorithms: PBKDF2, bcrypt, scrypt, Argon2.\n\nClue:\nLook for making password hashing intentionally slow and expensive to defeat brute force and dictionary attacks.\n\nExample:\nbcrypt applies 2^12 iterations — cracking one password hash takes 0.3s, making bulk cracking impractical.\n\nContrast:\nSalting = adds uniqueness to prevent rainbow tables; Key stretching = slows down brute-force attempts.",trick:"Exam map: 1.0 General Security Concepts"},
{cat:0,catName:"D1 General Concepts",acr:"Blockchain",full:"1.4 Explain the importance of using appropriate cryptographic solutions.",def:"Definition:\nDistributed, append-only ledger where each block contains a cryptographic hash of the previous block. Tampering with any block breaks all subsequent hashes, making alteration detectable.\n\nClue:\nLook for tamper-evident, distributed record-keeping using chained cryptographic hashes.\n\nExample:\nAltering a transaction in block 50 changes its hash, which breaks block 51's hash, cascading forward — the tampering is evident.\n\nContrast:\nTraditional database = centralized, mutable; Blockchain = decentralized, append-only, tamper-evident.",trick:"Exam map: 1.0 General Security Concepts"},
{cat:0,catName:"D1 General Concepts",acr:"Open public ledger",full:"1.4 Explain the importance of using appropriate cryptographic solutions.",def:"Definition:\nA blockchain where all transactions are visible to anyone, and any participant can verify the record independently without trusting a central authority.\n\nClue:\nLook for transparency and decentralization as the key properties — anyone can read and verify the history.\n\nExample:\nBitcoin's blockchain is publicly viewable — anyone can see all transactions and verify them independently.\n\nContrast:\nPrivate/permissioned blockchain = access restricted; Open public ledger = fully transparent and decentralized.",trick:"Exam map: 1.0 General Security Concepts"},
{cat:0,catName:"D1 General Concepts",acr:"Certificates",full:"1.4 Explain the importance of using appropriate cryptographic solutions.",def:"Definition:\nDigitally signed documents that bind an identity to a public key.\n\nClue:\nLook for binding an identity to a public key.\n\nExample:\nWebsite certificate proves the site identity.\n\nContrast:\nKeys perform crypto; Certificates bind keys to identities.",trick:"Exam map: 1.0 General Security Concepts"},
{cat:0,catName:"D1 General Concepts",acr:"Certificate authorities",full:"1.4 Explain the importance of using appropriate cryptographic solutions.",def:"Definition:\nTrusted entities that issue and sign digital certificates.\n\nClue:\nLook for what service is being connected, whether it is encrypted, and the safer protocol choice.\n\nExample:\nDigiCert signs a website certificate.\n\nContrast:\nInsecure protocol = avoid when confidentiality is needed; secure protocol = prefer for protected communication.",trick:"Exam map: Certificates > Certificate authorities"},
{cat:0,catName:"D1 General Concepts",acr:"Certificate revocation lists (CRLs)",full:"1.4 Explain the importance of using appropriate cryptographic solutions.",def:"Definition:\nPublished lists maintained by CAs that contain serial numbers of revoked certificates that should no longer be trusted, even if not yet expired. Alternative: OCSP (Online Certificate Status Protocol) for real-time checks.\n\nClue:\nLook for how systems check if a certificate has been revoked before expiry. CRL = periodic list; OCSP = real-time query.\n\nExample:\nBrowser downloads CRL to check if the website's certificate was revoked before trusting it.\n\nContrast:\nCRL = downloaded list (periodic, can be stale); OCSP = real-time status query per certificate.",trick:"Exam map: Certificates > Certificate revocation lists (CRLs)"},
{cat:0,catName:"D1 General Concepts",acr:"Self-signed",full:"1.4 Explain the importance of using appropriate cryptographic solutions.",def:"Definition:\nA certificate signed by its own private key rather than a trusted CA. Provides encryption but no third-party identity verification. Browsers and clients will show a trust warning.\n\nClue:\nLook for certificates not signed by a trusted CA — appropriate for internal/lab use, not public-facing services.\n\nExample:\nInternal test server uses self-signed certificate — engineers manually trust it in their browsers.\n\nContrast:\nCA-signed = trusted by browsers and clients by default; Self-signed = no chain of trust, generates warnings.",trick:"Exam map: Certificates > Self-signed"},
{cat:0,catName:"D1 General Concepts",acr:"Third-party",full:"1.4 Explain the importance of using appropriate cryptographic solutions.",def:"Definition:\nExternal, independent CA (like DigiCert, Let's Encrypt, Comodo) that signs certificates for public trust. Trusted by default in browsers and operating systems because they are in the trusted root store.\n\nClue:\nLook for public-facing certificates that need to be trusted by anyone without manual configuration.\n\nExample:\nE-commerce site uses DigiCert certificate — all browsers trust it automatically without any setup.\n\nContrast:\nInternal/private CA = trusted only within your org; Third-party CA = trusted globally by all browsers.",trick:"Exam map: Certificates > Third-party"},
{cat:0,catName:"D1 General Concepts",acr:"Root of trust",full:"1.4 Explain the importance of using appropriate cryptographic solutions.",def:"Definition:\nThe foundational trusted entity (root CA or hardware component like TPM) from which all trust in a system is derived. Everything else in the chain is trusted because it traces back to this root.\n\nClue:\nLook for the top of the certificate/trust hierarchy — the root CA that signs everything below it.\n\nExample:\nA root CA in the browser's trust store is the root of trust for all certificates it issues or subordinate CAs it signs.\n\nContrast:\nRoot CA = at the top (self-signed, inherently trusted); Intermediate CA = signed by root; End-entity cert = at the bottom.",trick:"Exam map: Certificates > Root of trust"},
{cat:1,catName:"D2 Threats & Mitigations",acr:"Threat actors",full:"2.0 Objective topic from Threats, Vulnerabilities, and Mitigations",def:"Definition:\nEntities that carry out or attempt cyberattacks. Types: Nation-state (government-backed), Hacktivist (ideological), Organized crime (financial), Insider threat (employee/contractor), Unskilled attacker (script kiddie), Shadow IT (accidental insider).\n\nClue:\nMatch the actor to their motivation and resources: financial = organized crime; political = hacktivist; government targets = nation-state; internal = insider threat.\n\nExample:\nRansomware group demanding payment = organized crime; site defaced for political message = hacktivist.\n\nContrast:\nThreat actor = WHO attacks; Threat vector = HOW they attack; Motivation = WHY they attack.",trick:"Exam map: Threat actors"},
{cat:1,catName:"D2 Threats & Mitigations",acr:"Nation-state",full:"2.0 Objective topic from Threats, Vulnerabilities, and Mitigations",def:"Definition:\nGovernment-backed attacker with significant resources, patience, and strategic goals.\n\nClue:\nLook for how the attack or weakness behaves, what it targets, and what reduces the damage.\n\nExample:\nLong-term spying on government systems.\n\nContrast:\nMitigation/control = defense; this term describes the problem or weakness.",trick:"Exam map: Threat actors > Nation-state"},
{cat:1,catName:"D2 Threats & Mitigations",acr:"Unskilled attacker",full:"2.0 Objective topic from Threats, Vulnerabilities, and Mitigations",def:"Definition:\nLow-skill attacker who relies on existing tools, scripts, and public instructions.\n\nClue:\nLook for how the attack or weakness behaves, what it targets, and what reduces the damage.\n\nExample:\nRuns public scripts from the internet.\n\nContrast:\nMitigation/control = defense; this term describes the problem or weakness.",trick:"Exam map: Threat actors > Unskilled attacker"},
{cat:1,catName:"D2 Threats & Mitigations",acr:"Hacktivist",full:"2.0 Objective topic from Threats, Vulnerabilities, and Mitigations",def:"Definition:\nAttacker motivated by political, social, or ideological goals.\n\nClue:\nLook for how the attack or weakness behaves, what it targets, and what reduces the damage.\n\nExample:\nDefaces a site for a political message.\n\nContrast:\nMitigation/control = defense; this term describes the problem or weakness.",trick:"Exam map: Threat actors > Hacktivist"},
{cat:1,catName:"D2 Threats & Mitigations",acr:"Insider threat",full:"2.0 Objective topic from Threats, Vulnerabilities, and Mitigations",def:"Definition:\nRisk from someone inside the organization, such as an employee, contractor, or partner.\n\nClue:\nLook for how the attack or weakness behaves, what it targets, and what reduces the damage.\n\nExample:\nEmployee steals customer records.\n\nContrast:\nMitigation/control = defense; this term describes the problem or weakness.",trick:"Exam map: Threat actors > Insider threat"},
{cat:1,catName:"D2 Threats & Mitigations",acr:"Organized crime",full:"2.0 Objective topic from Threats, Vulnerabilities, and Mitigations",def:"Definition:\nFinancially motivated criminal group using cyberattacks for profit.\n\nClue:\nLook for how the attack or weakness behaves, what it targets, and what reduces the damage.\n\nExample:\nRansomware group demands payment.\n\nContrast:\nMitigation/control = defense; this term describes the problem or weakness.",trick:"Exam map: Threat actors > Organized crime"},
{cat:1,catName:"D2 Threats & Mitigations",acr:"Shadow IT",full:"2.0 Objective topic from Threats, Vulnerabilities, and Mitigations",def:"Definition:\nTechnology used without formal approval or oversight from IT or security teams.\n\nClue:\nLook for how the attack or weakness behaves, what it targets, and what reduces the damage.\n\nExample:\nTeam stores files in an unapproved cloud app.\n\nContrast:\nMitigation/control = defense; this term describes the problem or weakness.",trick:"Exam map: Threat actors > Shadow IT"},
{cat:1,catName:"D2 Threats & Mitigations",acr:"Attributes of actors",full:"2.0 Objective topic from Threats, Vulnerabilities, and Mitigations",def:"Definition:\nCharacteristics used to describe and profile threat actors: Internal vs. External (position relative to the org), Resources/funding (tools and money available), Level of sophistication/capability (technical skill).\n\nClue:\nLook for actor characteristics: Where are they (inside/outside)? How resourced are they? How skilled are they?\n\nExample:\nNation-state = external, highly funded, very sophisticated. Script kiddie = external, low funding, low sophistication.\n\nContrast:\nMotivation = WHY they attack; Attributes = WHO they are and HOW capable they are.",trick:"Exam map: Attributes of actors"},
{cat:1,catName:"D2 Threats & Mitigations",acr:"Internal/external",full:"2.0 Objective topic from Threats, Vulnerabilities, and Mitigations",def:"Definition:\nThreat actor attribute: Internal = insider threat (employee, contractor, trusted partner with existing access — dangerous because they bypass perimeter controls and know where data lives). External = outside attacker (no prior access, must penetrate defenses first). Internal threats are harder to detect because their activity looks like normal work.\n\nClue:\nLook for whether the attacker already has legitimate access (internal) or is trying to get in from outside (external). Internal threats = access + knowledge + trust. External = skilled but must bypass perimeter first.\n\nExample:\nDisgruntled employee exfiltrates customer data before resignation = internal threat. Nation-state attacker probing the corporate firewall = external threat. Both need different detection approaches.\n\nContrast:\nExternal attacker must break through perimeter; Internal attacker already inside — monitoring user behavior (UEBA) is critical for internal threats that perimeter controls miss.",trick:"Exam map: Attributes of actors > Internal/external"},
{cat:1,catName:"D2 Threats & Mitigations",acr:"Resources/funding",full:"2.0 Objective topic from Threats, Vulnerabilities, and Mitigations",def:"Definition:\nThe financial backing, tools, personnel, and infrastructure available to a threat actor. More resources = more dangerous: custom malware, sustained campaigns, multiple simultaneous attack vectors.\n\nClue:\nLook for indicators of a well-resourced attacker: zero-day exploits, custom tools, long-term persistence, large infrastructure.\n\nExample:\nNation-state uses zero-days and custom implants (high resources); script kiddie uses free Metasploit modules (low resources).\n\nContrast:\nHigh resources = more dangerous and harder to detect; Low resources = relies on public tools and known exploits.",trick:"Exam map: Attributes of actors > Resources/funding"},
{cat:1,catName:"D2 Threats & Mitigations",acr:"Level of sophistication/capability",full:"2.0 Objective topic from Threats, Vulnerabilities, and Mitigations",def:"Definition:\nHow technically advanced a threat actor is. High sophistication = custom exploits, novel techniques, evasion of detection tools. Low sophistication = uses existing public scripts and tools (script kiddie).\n\nClue:\nLook for complexity of the attack technique: custom malware/zero-days = high; running public scripts = low.\n\nExample:\nAPT using a custom implant with encrypted C2 traffic = high sophistication. Teen using free hacking tool = low.\n\nContrast:\nHigh sophistication = harder to detect, mitigate, and attribute; Low = detectable with basic controls.",trick:"Exam map: Attributes of actors > Level of sophistication/capability"},
{cat:1,catName:"D2 Threats & Mitigations",acr:"Motivations",full:"2.0 Objective topic from Threats, Vulnerabilities, and Mitigations",def:"Definition:\nThe driving reason behind an attack. Key motivations: Data exfiltration, Financial gain, Espionage, Service disruption, Blackmail, Revenge, Philosophical/political beliefs, Disruption/chaos, War. Match motivation to likely actor type.\n\nClue:\nAsk WHY the attacker is doing this: money = financial/organized crime; ideology = hacktivist; intelligence = nation-state; revenge = disgruntled insider.\n\nExample:\nRansomware = financial gain; Website defacement = political/philosophical; Stealing IP = espionage.\n\nContrast:\nMotivation = why; Actor type = who; Threat vector = how they carry it out.",trick:"Exam map: Motivations"},
{cat:1,catName:"D2 Threats & Mitigations",acr:"Data exfiltration",full:"2.0 Objective topic from Threats, Vulnerabilities, and Mitigations",def:"Definition:\nUnauthorized removal or transfer of data from an environment.\n\nClue:\nLook for where the asset lives, what can fail, and how the design protects or restores CIA.\n\nExample:\nAttacker uploads files to an external server.\n\nContrast:\nMitigation/control = defense; this term describes the problem or weakness.",trick:"Exam map: Motivations > Data exfiltration"},
{cat:1,catName:"D2 Threats & Mitigations",acr:"Espionage",full:"2.0 Objective topic from Threats, Vulnerabilities, and Mitigations",def:"Definition:\nSpying to steal sensitive information, often for political, military, or business advantage.\n\nClue:\nLook for the exact scenario words and match them to the safest, most specific answer.\n\nExample:\nSteal product plans from a competitor.\n\nContrast:\nMitigation/control = defense; this term describes the problem or weakness.",trick:"Exam map: Motivations > Espionage"},
{cat:1,catName:"D2 Threats & Mitigations",acr:"Service disruption",full:"2.0 Objective topic from Threats, Vulnerabilities, and Mitigations",def:"Definition:\nAttack or failure that prevents normal service availability.\n\nClue:\nLook for the exact scenario words and match them to the safest, most specific answer.\n\nExample:\nAttack knocks the website offline.\n\nContrast:\nMitigation/control = defense; this term describes the problem or weakness.",trick:"Exam map: Motivations > Service disruption"},
{cat:1,catName:"D2 Threats & Mitigations",acr:"Blackmail",full:"2.0 Objective topic from Threats, Vulnerabilities, and Mitigations",def:"Definition:\nThreatening to reveal, damage, or withhold something unless demands are met.\n\nClue:\nLook for the exact scenario words and match them to the safest, most specific answer.\n\nExample:\nAttacker threatens to leak emails.\n\nContrast:\nMitigation/control = defense; this term describes the problem or weakness.",trick:"Exam map: Motivations > Blackmail"},
{cat:1,catName:"D2 Threats & Mitigations",acr:"Financial gain",full:"2.0 Objective topic from Threats, Vulnerabilities, and Mitigations",def:"Definition:\nMotivation focused on stealing money, selling data, fraud, or extortion.\n\nClue:\nLook for the exact scenario words and match them to the safest, most specific answer.\n\nExample:\nSteal credit card data.\n\nContrast:\nMitigation/control = defense; this term describes the problem or weakness.",trick:"Exam map: Motivations > Financial gain"},
{cat:1,catName:"D2 Threats & Mitigations",acr:"Philosophical/political beliefs",full:"2.0 Objective topic from Threats, Vulnerabilities, and Mitigations",def:"Definition:\nMotivation based on ideology, activism, or political cause.\n\nClue:\nLook for the exact scenario words and match them to the safest, most specific answer.\n\nExample:\nHacktivist targets a company policy.\n\nContrast:\nMitigation/control = defense; this term describes the problem or weakness.",trick:"Exam map: Motivations > Philosophical/political beliefs"},
{cat:1,catName:"D2 Threats & Mitigations",acr:"Ethical",full:"2.0 Objective topic from Threats, Vulnerabilities, and Mitigations",def:"Definition:\nA motivation where the actor believes their actions are morally justified — e.g., a whistleblower exposing wrongdoing, a vigilante attacking criminal infrastructure, or an insider leaking to the press. Intent is moral, but actions still create risk.\n\nClue:\nLook for actors who justify unauthorized access or data disclosure by claiming a moral or public interest cause.\n\nExample:\nEmployee copies confidential data and sends it to a journalist, believing it exposes corporate fraud.\n\nContrast:\nFinancial = profit motive; Ethical = moral justification; Hacktivist = political/social cause.",trick:"Exam map: Motivations > Ethical"},
{cat:1,catName:"D2 Threats & Mitigations",acr:"Revenge",full:"2.0 Objective topic from Threats, Vulnerabilities, and Mitigations",def:"Definition:\nMotivation based on retaliation for a perceived wrong.\n\nClue:\nLook for the exact scenario words and match them to the safest, most specific answer.\n\nExample:\nFired employee deletes files.\n\nContrast:\nMitigation/control = defense; this term describes the problem or weakness.",trick:"Exam map: Motivations > Revenge"},
{cat:1,catName:"D2 Threats & Mitigations",acr:"Disruption/chaos",full:"2.0 Objective topic from Threats, Vulnerabilities, and Mitigations",def:"Definition:\nMotivation to create disorder, damage operations, or cause confusion.\n\nClue:\nLook for the exact scenario words and match them to the safest, most specific answer.\n\nExample:\nWipe systems to cause panic.\n\nContrast:\nMitigation/control = defense; this term describes the problem or weakness.",trick:"Exam map: Motivations > Disruption/chaos"},
{cat:1,catName:"D2 Threats & Mitigations",acr:"War",full:"2.0 Objective topic from Threats, Vulnerabilities, and Mitigations",def:"Definition:\nCyber operations conducted as part of armed conflict or geopolitical warfare. Goals include disabling critical infrastructure, disrupting military communications, spreading propaganda, and causing physical damage via cyber means.\n\nClue:\nLook for nation-state cyber operations targeting critical infrastructure or military systems in the context of open conflict.\n\nExample:\nCyberattack disables a power grid and communications during a military invasion.\n\nContrast:\nEspionage = intelligence gathering (covert, ongoing); War = active disruption or destruction in a conflict context.",trick:"Exam map: Motivations > War"},
{cat:1,catName:"D2 Threats & Mitigations",acr:"Message-based",full:"2.2 Explain common threat vectors and attack surfaces.",def:"Definition:\nThreat vector delivered through messages such as email, SMS, or instant messaging.\n\nClue:\nLook for how the attack or weakness behaves, what it targets, and what reduces the damage.\n\nExample:\nMalicious email link.\n\nContrast:\nMitigation/control = defense; this term describes the problem or weakness.",trick:"Exam map: 2.0 Threats, Vulnerabilities, and Mitigations"},
{cat:1,catName:"D2 Threats & Mitigations",acr:"Email",full:"2.2 Explain common threat vectors and attack surfaces.",def:"Definition:\nThe most common threat vector. Used to deliver phishing, spear phishing, malware attachments, malicious links, and business email compromise (BEC). Exploits trust in sender and urgency.\n\nClue:\nLook for attacks delivered via email message: suspicious links, urgent requests, attachments from unknown senders, impersonation of trusted parties.\n\nExample:\nPhishing email with malicious link to fake login page harvests credentials.\n\nContrast:\nVishing = voice; Smishing = SMS/text; Email/phishing = email message vector.",trick:"Exam map: Message-based > Email"},
{cat:1,catName:"D2 Threats & Mitigations",acr:"Image-based",full:"2.2 Explain common threat vectors and attack surfaces.",def:"Definition:\nThreat vector that uses images to hide malicious content, links, or social engineering.\n\nClue:\nLook for how the attack or weakness behaves, what it targets, and what reduces the damage.\n\nExample:\nQR image sends user to fake login.\n\nContrast:\nMitigation/control = defense; this term describes the problem or weakness.",trick:"Exam map: 2.0 Threats, Vulnerabilities, and Mitigations"},
{cat:1,catName:"D2 Threats & Mitigations",acr:"File-based",full:"2.2 Explain common threat vectors and attack surfaces.",def:"Definition:\nThreat vector that uses attachments or files to deliver malware or exploit code.\n\nClue:\nLook for how the attack or weakness behaves, what it targets, and what reduces the damage.\n\nExample:\nMalicious attachment.\n\nContrast:\nMitigation/control = defense; this term describes the problem or weakness.",trick:"Exam map: 2.0 Threats, Vulnerabilities, and Mitigations"},
{cat:1,catName:"D2 Threats & Mitigations",acr:"Voice call",full:"2.2 Explain common threat vectors and attack surfaces.",def:"Definition:\nThreat vector using phone calls for fraud, impersonation, or social engineering.\n\nClue:\nLook for how the attack or weakness behaves, what it targets, and what reduces the damage.\n\nExample:\nFake help desk asks for password.\n\nContrast:\nMitigation/control = defense; this term describes the problem or weakness.",trick:"Exam map: 2.0 Threats, Vulnerabilities, and Mitigations"},
{cat:1,catName:"D2 Threats & Mitigations",acr:"Removable device",full:"2.2 Explain common threat vectors and attack surfaces.",def:"Definition:\nPortable media such as USB drives that can introduce malware or remove data.\n\nClue:\nLook for how the attack or weakness behaves, what it targets, and what reduces the damage.\n\nExample:\nUnknown USB drive installs malware.\n\nContrast:\nMitigation/control = defense; this term describes the problem or weakness.",trick:"Exam map: 2.0 Threats, Vulnerabilities, and Mitigations"},
{cat:1,catName:"D2 Threats & Mitigations",acr:"Vulnerable software",full:"2.2 Explain common threat vectors and attack surfaces.",def:"Definition:\nSoftware with weaknesses that attackers can exploit.\n\nClue:\nLook for how the attack or weakness behaves, what it targets, and what reduces the damage.\n\nExample:\nUnpatched app gets exploited.\n\nContrast:\nMitigation/control = defense; this term describes the problem or weakness.",trick:"Exam map: 2.0 Threats, Vulnerabilities, and Mitigations"},
{cat:1,catName:"D2 Threats & Mitigations",acr:"Client-based vs. agentless",full:"2.2 Explain common threat vectors and attack surfaces.",def:"Definition:\nClient-based (agent-based) security requires software installed on each endpoint — more visibility and control. Agentless works without endpoint software using network-based or API-based methods — easier to deploy but less visibility.\n\nClue:\nLook for whether a software agent must be installed: EDR agent = client-based; network scan = agentless.\n\nExample:\nEDR requires an agent on each laptop (client-based); vulnerability scan probes from the network (agentless).\n\nContrast:\nClient-based = more visibility, needs management at scale; Agentless = easier deployment, less endpoint visibility.",trick:"Exam map: Vulnerable software > Client-based vs. agentless"},
{cat:1,catName:"D2 Threats & Mitigations",acr:"Unsupported systems and applications",full:"2.2 Explain common threat vectors and attack surfaces.",def:"Definition:\nSystems or apps no longer receiving vendor updates or security patches.\n\nClue:\nLook for how the attack or weakness behaves, what it targets, and what reduces the damage.\n\nExample:\nOld OS stops receiving patches.\n\nContrast:\nMitigation/control = defense; this term describes the problem or weakness.",trick:"Exam map: 2.0 Threats, Vulnerabilities, and Mitigations"},
{cat:1,catName:"D2 Threats & Mitigations",acr:"Unsecure networks",full:"2.2 Explain common threat vectors and attack surfaces.",def:"Definition:\nNetworks lacking adequate encryption, authentication, segmentation, or monitoring.\n\nClue:\nLook for how the attack or weakness behaves, what it targets, and what reduces the damage.\n\nExample:\nOpen Wi-Fi exposes traffic.\n\nContrast:\nMitigation/control = defense; this term describes the problem or weakness.",trick:"Exam map: 2.0 Threats, Vulnerabilities, and Mitigations"},
{cat:1,catName:"D2 Threats & Mitigations",acr:"Wireless",full:"2.2 Explain common threat vectors and attack surfaces.",def:"Definition:\nWireless networks as an attack surface: open/unencrypted Wi-Fi, rogue access points, evil twin APs (spoofing legitimate SSIDs), deauthentication attacks, and eavesdropping on unencrypted traffic.\n\nClue:\nLook for attacks targeting Wi-Fi or wireless radio communications: rogue AP, evil twin, eavesdropping.\n\nExample:\nAttacker creates evil twin AP with same SSID as coffee shop — users connect and their traffic is intercepted.\n\nContrast:\nBluetooth = short-range device pairing; Wi-Fi wireless = broader network access vector; Wired = physical cable access.",trick:"Exam map: Unsecure networks > Wireless"},
{cat:1,catName:"D2 Threats & Mitigations",acr:"Wired",full:"2.2 Explain common threat vectors and attack surfaces.",def:"Definition:\nWired networks as an attack surface: attackers with physical access can plug into unprotected ports, sniff unencrypted traffic, introduce rogue devices, or tap cables. Mitigated by 802.1X port authentication and physical security.\n\nClue:\nLook for attacks requiring physical access to network ports or cables — rogue device, packet sniffer on wire.\n\nExample:\nAttacker plugs a laptop into an unprotected wall port in a lobby to gain internal network access.\n\nContrast:\nWireless attacks use radio signals without physical access; Wired attacks require physical network connectivity.",trick:"Exam map: Unsecure networks > Wired"},
{cat:1,catName:"D2 Threats & Mitigations",acr:"Bluetooth",full:"2.2 Explain common threat vectors and attack surfaces.",def:"Definition:\nShort-range wireless technology used for peripherals and device connections.\n\nClue:\nLook for how the attack or weakness behaves, what it targets, and what reduces the damage.\n\nExample:\nWireless keyboard connects to laptop.\n\nContrast:\nMitigation/control = defense; this term describes the problem or weakness.",trick:"Exam map: Unsecure networks > Bluetooth"},
{cat:1,catName:"D2 Threats & Mitigations",acr:"Open service ports",full:"2.2 Explain common threat vectors and attack surfaces.",def:"Definition:\nListening network ports that expose services and may increase attack surface.\n\nClue:\nLook for how the attack or weakness behaves, what it targets, and what reduces the damage.\n\nExample:\nExposed RDP invites attacks.\n\nContrast:\nMitigation/control = defense; this term describes the problem or weakness.",trick:"Exam map: 2.0 Threats, Vulnerabilities, and Mitigations"},
{cat:1,catName:"D2 Threats & Mitigations",acr:"Default credentials",full:"2.2 Explain common threat vectors and attack surfaces.",def:"Definition:\nVendor-provided usernames and passwords that must be changed before use.\n\nClue:\nLook for how the attack or weakness behaves, what it targets, and what reduces the damage.\n\nExample:\nAdmin/admin on a router.\n\nContrast:\nMitigation/control = defense; this term describes the problem or weakness.",trick:"Exam map: 2.0 Threats, Vulnerabilities, and Mitigations"},
{cat:1,catName:"D2 Threats & Mitigations",acr:"Supply chain",full:"2.2 Explain common threat vectors and attack surfaces.",def:"Definition:\nThird-party ecosystem of vendors, software, hardware, and services that can introduce risk.\n\nClue:\nLook for how the attack or weakness behaves, what it targets, and what reduces the damage.\n\nExample:\nCompromised update infects customers.\n\nContrast:\nMitigation/control = defense; this term describes the problem or weakness.",trick:"Exam map: 2.0 Threats, Vulnerabilities, and Mitigations"},
{cat:1,catName:"D2 Threats & Mitigations",acr:"Managed service providers (MSPs)",full:"2.2 Explain common threat vectors and attack surfaces.",def:"Definition:\nThird-party companies that manage IT services for organizations. MSPs have privileged, ongoing remote access to many clients — compromising one MSP can cascade to all their customers (supply chain multiplier effect).\n\nClue:\nLook for third parties with privileged remote access to client systems — compromise one to reach many.\n\nExample:\nAttacker compromises an MSP's RMM tool to push malware to all clients simultaneously.\n\nContrast:\nVendors supply products; MSPs have ongoing privileged remote access making them higher-impact targets.",trick:"Exam map: Supply chain > Managed service providers (MSPs)"},
{cat:1,catName:"D2 Threats & Mitigations",acr:"Vendors",full:"2.2 Explain common threat vectors and attack surfaces.",def:"Definition:\nCompanies that supply software, hardware, or services. Vendors are supply chain risks when their products contain vulnerabilities, backdoors, or are compromised before delivery (e.g., trojanized software updates).\n\nClue:\nLook for third-party product suppliers whose compromised software or hardware could affect your organization.\n\nExample:\nSolarWinds Orion update was trojanized — vendor's compromised update infected thousands of customers.\n\nContrast:\nMSPs = ongoing privileged access; Vendors = primarily deliver products that may be compromised.",trick:"Exam map: Supply chain > Vendors"},
{cat:1,catName:"D2 Threats & Mitigations",acr:"Suppliers",full:"2.2 Explain common threat vectors and attack surfaces.",def:"Definition:\nEntities that provide raw materials, components, or sub-assemblies used in the final product. A compromised upstream supplier can introduce vulnerabilities or malicious code before the product reaches the organization.\n\nClue:\nLook for organizations further upstream in the supply chain — they provide components that become part of the final product.\n\nExample:\nCompromised chip supplier embeds backdoored firmware into network hardware before it ships.\n\nContrast:\nVendors = direct product providers; Suppliers = upstream component/raw material providers in the chain.",trick:"Exam map: Supply chain > Suppliers"},
{cat:1,catName:"D2 Threats & Mitigations",acr:"Human vectors/social engineering",full:"2.2 Explain common threat vectors and attack surfaces.",def:"Definition:\nAttacks that exploit human psychology rather than technical vulnerabilities. Techniques: phishing, vishing, smishing, pretexting, impersonation, watering hole, brand impersonation, typosquatting, BEC, misinformation.\n\nClue:\nLook for attacks that manipulate people's trust, fear, urgency, or authority rather than exploiting software.\n\nExample:\nFake IT help desk call asks employee for their MFA code — exploits trust in authority, not a software flaw.\n\nContrast:\nTechnical attacks exploit code; Social engineering exploits human behavior and trust.",trick:"Exam map: Human vectors/social engineering"},
{cat:1,catName:"D2 Threats & Mitigations",acr:"Phishing",full:"2.2 Explain common threat vectors and attack surfaces.",def:"Definition:\nSocial engineering attack that uses deceptive messages to trick users into revealing information or taking unsafe actions.\n\nClue:\nLook for deceptive messages, suspicious links, urgency, or credential requests.\n\nExample:\nEmail says “reset password now” and links to a fake site.\n\nContrast:\nVishing = voice; Smishing = SMS/text.",trick:"Exam map: Human vectors/social engineering > Phishing"},
{cat:1,catName:"D2 Threats & Mitigations",acr:"Vishing",full:"2.2 Explain common threat vectors and attack surfaces.",def:"Definition:\nVoice phishing conducted over phone calls or voice messages.\n\nClue:\nLook for phone-call social engineering.\n\nExample:\nFake bank call asks for account code.\n\nContrast:\nPhishing = general message/email; Smishing = text message.",trick:"Exam map: Human vectors/social engineering > Vishing"},
{cat:1,catName:"D2 Threats & Mitigations",acr:"Smishing",full:"2.2 Explain common threat vectors and attack surfaces.",def:"Definition:\nSMS phishing conducted through text messages.\n\nClue:\nLook for text-message social engineering.\n\nExample:\nText says your package is delayed with a bad link.\n\nContrast:\nPhishing = general message/email; Vishing = voice call.",trick:"Exam map: Human vectors/social engineering > Smishing"},
{cat:1,catName:"D2 Threats & Mitigations",acr:"Misinformation/disinformation",full:"2.2 Explain common threat vectors and attack surfaces.",def:"Definition:\nFalse information spread accidentally or intentionally to influence decisions or behavior.\n\nClue:\nLook for how the attack or weakness behaves, what it targets, and what reduces the damage.\n\nExample:\nFake incident rumor causes panic.\n\nContrast:\nMitigation/control = defense; this term describes the problem or weakness.",trick:"Exam map: Human vectors/social engineering > Misinformation/disinformation"},
{cat:1,catName:"D2 Threats & Mitigations",acr:"Impersonation",full:"2.2 Explain common threat vectors and attack surfaces.",def:"Definition:\nPretending to be another person, role, or organization to gain trust or access.\n\nClue:\nLook for how the attack or weakness behaves, what it targets, and what reduces the damage.\n\nExample:\nAttacker dresses as delivery staff.\n\nContrast:\nMitigation/control = defense; this term describes the problem or weakness.",trick:"Exam map: Human vectors/social engineering > Impersonation"},
{cat:1,catName:"D2 Threats & Mitigations",acr:"Business email compromise",full:"2.2 Explain common threat vectors and attack surfaces.",def:"Definition:\nAttack where email is used to impersonate trusted business parties and steal money or data.\n\nClue:\nLook for how the attack or weakness behaves, what it targets, and what reduces the damage.\n\nExample:\nEmail asks finance to wire funds.\n\nContrast:\nMitigation/control = defense; this term describes the problem or weakness.",trick:"Exam map: Human vectors/social engineering > Business email compromise"},
{cat:1,catName:"D2 Threats & Mitigations",acr:"Pretexting",full:"2.2 Explain common threat vectors and attack surfaces.",def:"Definition:\nUsing a fabricated story or scenario to manipulate someone into sharing information or taking action.\n\nClue:\nLook for a fake story used to build trust before asking for information.\n\nExample:\n“I’m from IT, I need your code.”\n\nContrast:\nImpersonation = pretending to be someone; Pretexting = using a fake story.",trick:"Exam map: Human vectors/social engineering > Pretexting"},
{cat:1,catName:"D2 Threats & Mitigations",acr:"Watering hole",full:"2.2 Explain common threat vectors and attack surfaces.",def:"Definition:\nCompromising a site likely to be visited by a target group.\n\nClue:\nLook for a trusted website compromised because targets commonly visit it.\n\nExample:\nInfect an industry website.\n\nContrast:\nPhishing sends bait to users; Watering hole poisons a site users already visit.",trick:"Exam map: Human vectors/social engineering > Watering hole"},
{cat:1,catName:"D2 Threats & Mitigations",acr:"Brand impersonation",full:"2.2 Explain common threat vectors and attack surfaces.",def:"Definition:\nPretending to be a trusted brand to trick users into clicking, logging in, or paying.\n\nClue:\nLook for how the attack or weakness behaves, what it targets, and what reduces the damage.\n\nExample:\nLookalike Microsoft login page.\n\nContrast:\nMitigation/control = defense; this term describes the problem or weakness.",trick:"Exam map: Human vectors/social engineering > Brand impersonation"},
{cat:1,catName:"D2 Threats & Mitigations",acr:"Typosquatting",full:"2.2 Explain common threat vectors and attack surfaces.",def:"Definition:\nRegistering misspelled domain names to catch users who mistype legitimate URLs.\n\nClue:\nLook for misspelled or look-alike domain names.\n\nExample:\ngooogle.com catches mistypes.\n\nContrast:\nBrand impersonation copies identity; Typosquatting relies on misspelled domains.",trick:"Exam map: Human vectors/social engineering > Typosquatting"},
{cat:1,catName:"D2 Threats & Mitigations",acr:"Application",full:"2.3 Explain various types of vulnerabilities.",def:"Definition:\nCategory of vulnerabilities in software applications arising from insecure coding: memory injection, buffer overflow, race conditions, and malicious updates. Each exploits flaws in how the application handles data or processes.\n\nClue:\nLook for flaws in software code or logic: too much input = buffer overflow; timing flaw = race condition; hidden code = memory injection.\n\nExample:\nBuffer overflow in a web app allows an attacker to overwrite return addresses and execute arbitrary code.\n\nContrast:\nHardware vulnerabilities = physical devices; Application vulnerabilities = software code and logic flaws.",trick:"Exam map: Application vulnerabilities"},
{cat:1,catName:"D2 Threats & Mitigations",acr:"Memory injection",full:"2.3 Explain various types of vulnerabilities.",def:"Definition:\nPlacing malicious code into a running process memory space.\n\nClue:\nLook for how the attack or weakness behaves, what it targets, and what reduces the damage.\n\nExample:\nMalware hides inside a browser process.\n\nContrast:\nMitigation/control = defense; this term describes the problem or weakness.",trick:"Exam map: Application > Memory injection"},
{cat:1,catName:"D2 Threats & Mitigations",acr:"Buffer overflow",full:"2.3 Explain various types of vulnerabilities.",def:"Definition:\nWriting more data to memory than a buffer can hold, possibly overwriting control data.\n\nClue:\nLook for too much input overwriting memory.\n\nExample:\nLong input overwrites memory.\n\nContrast:\nMitigation/control = defense; this term describes the problem or weakness.",trick:"Exam map: Application > Buffer overflow"},
{cat:1,catName:"D2 Threats & Mitigations",acr:"Race conditions",full:"2.3 Explain various types of vulnerabilities.",def:"Definition:\nVulnerability where timing between operations changes the result in an unsafe way.\n\nClue:\nLook for timing between check and use being exploited.\n\nExample:\nChange a file between check and use.\n\nContrast:\nMitigation/control = defense; this term describes the problem or weakness.",trick:"Exam map: Application > Race conditions"},
{cat:1,catName:"D2 Threats & Mitigations",acr:"Malicious update",full:"2.3 Explain various types of vulnerabilities.",def:"Definition:\nUpdate that has been tampered with or intentionally delivers harmful code.\n\nClue:\nLook for the exact scenario words and match them to the safest, most specific answer.\n\nExample:\nFake patch installs malware.\n\nContrast:\nMitigation/control = defense; this term describes the problem or weakness.",trick:"Exam map: Application > Race conditions > Malicious update"},
{cat:1,catName:"D2 Threats & Mitigations",acr:"Web-based",full:"2.3 Explain various types of vulnerabilities.",def:"Definition:\nCategory of vulnerabilities in web applications. Key examples: SQL injection (malicious DB queries), XSS-cross-site scripting (injected scripts), CSRF-cross-site request forgery (forged requests), directory traversal (path manipulation).\n\nClue:\nLook for attacks using HTTP requests and web application input: SQL = database; XSS = scripts in browser; CSRF = forged requests; traversal = ../ paths.\n\nExample:\nSQL injection in login form: ' OR '1'='1 bypasses authentication by manipulating the SQL query.\n\nContrast:\nNetwork attacks target infrastructure; Web-based vulnerabilities exploit application input handling and HTTP logic.",trick:"Exam map: Web-based vulnerabilities"},
{cat:1,catName:"D2 Threats & Mitigations",acr:"Hardware •",full:"2.3 Explain various types of vulnerabilities.",def:"Definition:\nCategory of vulnerabilities in physical hardware: firmware weaknesses (persistent, survive OS reinstall), end-of-life hardware (no patches), sideloading (apps from untrusted sources), and jailbreaking (bypassing OS restrictions).\n\nClue:\nLook for vulnerabilities in the physical device or its low-level firmware, not in OS software.\n\nExample:\nVulnerable router firmware allows remote code execution that persists even after factory reset.\n\nContrast:\nSoftware vulnerabilities = OS/app code; Hardware vulnerabilities = physical devices, chips, and firmware.",trick:"Exam map: Hardware vulnerabilities"},
{cat:1,catName:"D2 Threats & Mitigations",acr:"Side loading",full:"2.3 Explain various types of vulnerabilities.",def:"Definition:\nInstalling apps from unofficial or untrusted sources.\n\nClue:\nLook for the exact scenario words and match them to the safest, most specific answer.\n\nExample:\nInstall APK outside app store.\n\nContrast:\nMitigation/control = defense; this term describes the problem or weakness.",trick:"Exam map: Hardware • > Side loading"},
{cat:1,catName:"D2 Threats & Mitigations",acr:"Jailbreaking Zero-day",full:"2.3 Explain various types of vulnerabilities.",def:"Definition:\nJailbreaking removes vendor-imposed restrictions on a device (e.g., iOS/Android), enabling sideloading and disabling security controls. Zero-day is a vulnerability unknown to the vendor with no patch — most dangerous window of exposure.\n\nClue:\nJailbreaking = bypasses OS security model; Zero-day = no patch exists yet. Both dramatically increase risk.\n\nExample:\nJailbroken iPhone can sideload any app, bypassing App Store vetting; Zero-day exploit used before vendor awareness.\n\nContrast:\nSideloading = installing from untrusted source; Jailbreaking = removing controls that prevent sideloading.",trick:"Exam map: Hardware vulnerabilities > Jailbreaking / Zero-day"},
{cat:1,catName:"D2 Threats & Mitigations",acr:"Firmware",full:"2.3 Explain various types of vulnerabilities.",def:"Definition:\nLow-level software embedded in hardware (BIOS, UEFI, router firmware, IoT firmware). Firmware vulnerabilities are critical because they are difficult to patch, persist through OS reinstalls, and give deep persistent access.\n\nClue:\nLook for attacks or vulnerabilities at the hardware firmware level — below the OS, persisting through reimaging.\n\nExample:\nAttacker compromises router firmware — the implant survives factory reset and continues operating.\n\nContrast:\nOS malware = removed by reinstall; Firmware implant = survives OS reinstall; requires firmware reflash or hardware replacement.",trick:"Exam map: Hardware vulnerabilities > Firmware"},
{cat:1,catName:"D2 Threats & Mitigations",acr:"End-of-life",full:"2.3 Explain various types of vulnerabilities.",def:"Definition:\nHardware or software that the vendor no longer supports with security patches. Every new CVE discovered after EOL will never be fixed — a permanent and growing vulnerability window.\n\nClue:\nLook for systems past their vendor support date — no more patches, permanently vulnerable to new exploits.\n\nExample:\nWindows Server 2008 reached EOL in 2020 — any vulnerability discovered after that date has no patch available.\n\nContrast:\nLegacy = old but possibly still supported; End-of-life = vendor support officially ended, zero patches coming.",trick:"Exam map: Hardware vulnerabilities > End-of-life"},
{cat:1,catName:"D2 Threats & Mitigations",acr:"Legacy",full:"2.3 Explain various types of vulnerabilities.",def:"Definition:\nOlder hardware or systems that remain in use due to cost, compatibility, or operational necessity. Hard to patch, integrate with modern security tools, or replace without disrupting operations. Requires compensating controls.\n\nClue:\nLook for old systems still running that create security challenges — can't easily patch or replace them.\n\nExample:\nOld industrial control system running Windows XP can't be patched — compensating control: network segmentation.\n\nContrast:\nEnd-of-life = vendor support ended; Legacy = old system still in use, may or may not still receive some support.",trick:"Exam map: Hardware vulnerabilities > Legacy"},
{cat:1,catName:"D2 Threats & Mitigations",acr:"Malware attacks",full:"2.4 Given a scenario, analyze indicators of malicious activity.",def:"Definition:\nCategory of malicious software designed to harm systems, steal data, or gain unauthorized access. Key types: Ransomware (encrypts data for ransom), Trojan (disguised malware), Worm (self-spreading), Virus (attaches to files), Spyware (monitors activity), Keylogger (records keystrokes), Logic bomb (triggered by condition), Rootkit (hides access), Bloatware (unwanted preinstalled software).\n\nClue:\nMatch the attack behavior to the type: spreading itself = worm; disguised as useful = trojan; triggered on date = logic bomb; hides from tools = rootkit; pays ransom = ransomware.\n\nExample:\nEmployee opens fake invoice attachment → trojan installs ransomware → files encrypted, ransom demanded.\n\nContrast:\nWorm spreads itself; Virus needs a host file/user action; Trojan hides inside something useful; Ransomware demands payment; Rootkit hides presence.",trick:"Exam map: Malware attacks"},
{cat:1,catName:"D2 Threats & Mitigations",acr:"Ransomware",full:"2.4 Given a scenario, analyze indicators of malicious activity.",def:"Definition:\nMalware that encrypts or blocks access to data and demands payment.\n\nClue:\nLook for encrypted files, ransom notes, or blocked access to data.\n\nExample:\nFiles encrypted with ransom note.\n\nContrast:\nWiper destroys data; Ransomware demands payment to restore access.",trick:"Exam map: Malware attacks > Ransomware"},
{cat:1,catName:"D2 Threats & Mitigations",acr:"Trojan",full:"2.4 Given a scenario, analyze indicators of malicious activity.",def:"Definition:\nMalware disguised as legitimate or useful software.\n\nClue:\nLook for malware disguised as useful or legitimate software.\n\nExample:\nFake game installs backdoor.\n\nContrast:\nVirus attaches to files; Trojan hides inside something that appears useful.",trick:"Exam map: Malware attacks > Trojan"},
{cat:1,catName:"D2 Threats & Mitigations",acr:"Worm",full:"2.4 Given a scenario, analyze indicators of malicious activity.",def:"Definition:\nSelf-replicating malware that spreads without needing user action.\n\nClue:\nLook for malware that spreads by itself across systems.\n\nExample:\nMalware spreads across network shares.\n\nContrast:\nVirus needs a host file or user action; Worm spreads itself.",trick:"Exam map: Malware attacks > Worm"},
{cat:1,catName:"D2 Threats & Mitigations",acr:"Spyware",full:"2.4 Given a scenario, analyze indicators of malicious activity.",def:"Definition:\nSoftware that secretly monitors activity or collects information.\n\nClue:\nLook for how the attack or weakness behaves, what it targets, and what reduces the damage.\n\nExample:\nRecords browsing and sends it out.\n\nContrast:\nMitigation/control = defense; this term describes the problem or weakness.",trick:"Exam map: Malware attacks > Spyware"},
{cat:1,catName:"D2 Threats & Mitigations",acr:"Bloatware",full:"2.4 Given a scenario, analyze indicators of malicious activity.",def:"Definition:\nUnwanted preinstalled or bundled software that can waste resources or increase risk.\n\nClue:\nLook for how the attack or weakness behaves, what it targets, and what reduces the damage.\n\nExample:\nPreinstalled trial app has vulnerabilities.\n\nContrast:\nMitigation/control = defense; this term describes the problem or weakness.",trick:"Exam map: Malware attacks > Bloatware"},
{cat:1,catName:"D2 Threats & Mitigations",acr:"Virus",full:"2.4 Given a scenario, analyze indicators of malicious activity.",def:"Definition:\nMalware that attaches to files or programs and spreads when they run.\n\nClue:\nLook for malware attached to a file or program that spreads when executed.\n\nExample:\nInfected document macro.\n\nContrast:\nWorm spreads itself; Virus attaches to a file or program.",trick:"Exam map: Malware attacks > Virus"},
{cat:1,catName:"D2 Threats & Mitigations",acr:"Keylogger",full:"2.4 Given a scenario, analyze indicators of malicious activity.",def:"Definition:\nTool or malware that records keystrokes to capture passwords or sensitive data.\n\nClue:\nLook for captured keystrokes, passwords, or typed secrets.\n\nExample:\nCaptures bank password as you type.\n\nContrast:\nMitigation/control = defense; this term describes the problem or weakness.",trick:"Exam map: Malware attacks > Keylogger"},
{cat:1,catName:"D2 Threats & Mitigations",acr:"Logic bomb",full:"2.4 Given a scenario, analyze indicators of malicious activity.",def:"Definition:\nMalicious code triggered by a specific condition or event.\n\nClue:\nLook for how the attack or weakness behaves, what it targets, and what reduces the damage.\n\nExample:\nDeletes files on a specific date.\n\nContrast:\nMitigation/control = defense; this term describes the problem or weakness.",trick:"Exam map: Malware attacks > Logic bomb"},
{cat:1,catName:"D2 Threats & Mitigations",acr:"Rootkit",full:"2.4 Given a scenario, analyze indicators of malicious activity.",def:"Definition:\nMalware designed to hide itself and maintain privileged access.\n\nClue:\nLook for hidden malware, stealth, and deep privileged persistence.\n\nExample:\nMalware hides processes from tools.\n\nContrast:\nBackdoor provides access; Rootkit hides access and activity.",trick:"Exam map: Malware attacks > Rootkit"},
{cat:1,catName:"D2 Threats & Mitigations",acr:"Physical attacks",full:"2.4 Given a scenario, analyze indicators of malicious activity.",def:"Definition:\nAttacks that require physical presence or physical access to systems, facilities, or people. Includes: brute force (physical door forcing), RFID/card cloning, tailgating/piggybacking, shoulder surfing, dumpster diving, and environmental attacks (power, temperature). Physical access often bypasses all logical controls.\n\nClue:\nLook for physical presence, touching hardware, or exploiting physical access controls — no network connection needed.\n\nExample:\nAttacker follows employee through badge-controlled door (tailgating), then plugs in malicious USB at unattended workstation.\n\nContrast:\nNetwork attacks require network access; Physical attacks require physical presence or proximity.",trick:"Exam map: Physical attacks"},
{cat:1,catName:"D2 Threats & Mitigations",acr:"Brute force",full:"2.4 Given a scenario, analyze indicators of malicious activity.",def:"Definition:\nTrying many possible passwords, keys, or combinations until one works.\n\nClue:\nLook for how the attack or weakness behaves, what it targets, and what reduces the damage.\n\nExample:\nGuess passwords until one works.\n\nContrast:\nPassword spraying = one/few passwords across many accounts.",trick:"Exam map: Physical attacks > Brute force"},
{cat:1,catName:"D2 Threats & Mitigations",acr:"Environmental",full:"2.4 Given a scenario, analyze indicators of malicious activity.",def:"Definition:\nPhysical condition such as heat, humidity, fire, or water that can damage systems.\n\nClue:\nLook for how the attack or weakness behaves, what it targets, and what reduces the damage.\n\nExample:\nHeat damages servers.\n\nContrast:\nMitigation/control = defense; this term describes the problem or weakness.",trick:"Exam map: Physical attacks > Environmental"},
{cat:1,catName:"D2 Threats & Mitigations",acr:"Network attacks",full:"2.4 Given a scenario, analyze indicators of malicious activity.",def:"Definition:\nCategory of attacks conducted over networks. Includes: DDoS (amplified/reflected), on-path (intercept traffic), credential replay (reuse captured tokens), password spraying (few passwords across many accounts), brute force, account lockout manipulation, injection, privilege escalation, forgery (CSRF), downgrade, birthday/collision attacks.\n\nClue:\nLook for the attack mechanism: volumetric = DDoS; intercepting = on-path; capturing and resending = replay; few passwords + many accounts = spraying.\n\nExample:\nAttacker spoofs victim's IP in DNS requests → amplified responses overwhelm victim's bandwidth (DDoS amplification).\n\nContrast:\nNetwork attacks use network access; Physical attacks require physical presence; Application attacks target software logic.",trick:"Exam map: Network attacks"},
{cat:1,catName:"D2 Threats & Mitigations",acr:"Amplified",full:"2.4 Given a scenario, analyze indicators of malicious activity.",def:"Definition:\nDDoS method that uses third-party systems to multiply attack traffic.\n\nClue:\nLook for how the attack or weakness behaves, what it targets, and what reduces the damage.\n\nExample:\nDNS amplification DDoS.\n\nContrast:\nMitigation/control = defense; this term describes the problem or weakness.",trick:"Exam map: Network attacks > Distributed denial-of-service (DDoS) > Amplified"},
{cat:1,catName:"D2 Threats & Mitigations",acr:"Reflected",full:"2.4 Given a scenario, analyze indicators of malicious activity.",def:"Definition:\nAttack where traffic is bounced off third-party systems toward a victim.\n\nClue:\nLook for how the attack or weakness behaves, what it targets, and what reduces the damage.\n\nExample:\nSpoof victim IP so replies hit victim.\n\nContrast:\nMitigation/control = defense; this term describes the problem or weakness.",trick:"Exam map: Network attacks > Distributed denial-of-service (DDoS) > Reflected"},
{cat:1,catName:"D2 Threats & Mitigations",acr:"Birthday",full:"2.4 Given a scenario, analyze indicators of malicious activity.",def:"Definition:\nCryptographic attack based on the probability of hash collisions.\n\nClue:\nLook for how the attack or weakness behaves, what it targets, and what reduces the damage.\n\nExample:\nCollision attack.\n\nContrast:\nMitigation/control = defense; this term describes the problem or weakness.",trick:"Exam map: Network attacks > Birthday"},
{cat:1,catName:"D2 Threats & Mitigations",acr:"Spraying",full:"2.4 Given a scenario, analyze indicators of malicious activity.",def:"Definition:\nPassword attack that tries a few common passwords across many accounts.\n\nClue:\nLook for how the attack or weakness behaves, what it targets, and what reduces the damage.\n\nExample:\nTry Spring2026 against every account.\n\nContrast:\nBrute force = many guesses against one account.",trick:"Exam map: Network attacks > Spraying"},
{cat:1,catName:"D2 Threats & Mitigations",acr:"Account lockout",full:"2.4 Given a scenario, analyze indicators of malicious activity.",def:"Definition:\nSecurity event where an account is disabled after too many failed login attempts.\n\nClue:\nLook for how the attack or weakness behaves, what it targets, and what reduces the damage.\n\nExample:\nAccount locks after 5 failures.\n\nContrast:\nMitigation/control = defense; this term describes the problem or weakness.",trick:"Exam map: Network attacks > Account lockout"},
{cat:1,catName:"D2 Threats & Mitigations",acr:"Concurrent session usage",full:"2.4 Given a scenario, analyze indicators of malicious activity.",def:"Definition:\nIndicator of compromise where the same account is active in multiple sessions simultaneously, often from different locations. Suggests credential theft — attacker is using stolen credentials while the legitimate user is also logged in.\n\nClue:\nLook for the same account logged in from two different places at the same time — one session may be an attacker.\n\nExample:\nHR account shows active session from Chicago and Berlin at the same time — employee is in Chicago.\n\nContrast:\nImpossible travel = login locations are geographically impossible; Concurrent sessions = same account active in two sessions simultaneously.",trick:"Exam map: Network attacks > Concurrent session usage"},
{cat:1,catName:"D2 Threats & Mitigations",acr:"Blocked content",full:"2.4 Given a scenario, analyze indicators of malicious activity.",def:"Definition:\nIndicator of malicious activity where security filters (proxy, firewall, content filter) are recording blocked access attempts to known malicious sites, C2 infrastructure, or prohibited content. High volume of blocked outbound connections can indicate malware attempting to call home.\n\nClue:\nLook for security tools repeatedly blocking outbound connections to suspicious destinations — the malware is installed but can't reach its C2 server.\n\nExample:\nProxy logs show a workstation attempting hundreds of connections to known malware C2 domains, all blocked by the web filter.\n\nContrast:\nBlocked content logs show attempted malicious activity; Missing logs suggest an attacker may have deleted evidence of successful activity.",trick:"Exam map: Network attacks > Blocked content"},
{cat:1,catName:"D2 Threats & Mitigations",acr:"Impossible travel",full:"2.4 Given a scenario, analyze indicators of malicious activity.",def:"Definition:\nIndicator where logins occur from distant locations too quickly to be realistic.\n\nClue:\nLook for how the attack or weakness behaves, what it targets, and what reduces the damage.\n\nExample:\nLogin from NY then Tokyo five minutes later.\n\nContrast:\nMitigation/control = defense; this term describes the problem or weakness.",trick:"Exam map: Network attacks > Impossible travel"},
{cat:1,catName:"D2 Threats & Mitigations",acr:"Resource consumption",full:"2.4 Given a scenario, analyze indicators of malicious activity.",def:"Definition:\nIndicator of compromise: abnormally high CPU, memory, network bandwidth, or disk usage on a system. Can indicate DoS attack overwhelming the system, cryptomining malware stealing CPU cycles, data exfiltration consuming bandwidth, or malicious processes running in background.\n\nClue:\nLook for sudden unexplained spikes in CPU, memory, or network — normal load replaced or supplemented by malicious processing.\n\nExample:\nServer CPU at 100% with no scheduled jobs — investigation reveals cryptomining malware installed through unpatched vulnerability.\n\nContrast:\nResource inaccessibility = users can't reach the resource; Resource consumption = the resource is being used up by malicious activity.",trick:"Exam map: Network attacks > Resource consumption"},
{cat:1,catName:"D2 Threats & Mitigations",acr:"Resource inaccessibility",full:"2.4 Given a scenario, analyze indicators of malicious activity.",def:"Definition:\nIndicator of compromise: legitimate users cannot access systems, files, or services they should be able to reach. Typical indicator of DoS/DDoS attacks flooding a service, ransomware encrypting files, or an attacker locking out accounts or disabling services.\n\nClue:\nLook for users who normally have access suddenly being unable to reach a resource — something is blocking or destroying availability.\n\nExample:\nEmployees can't open shared drive files — ransomware has encrypted them and placed ransom notes in each directory.\n\nContrast:\nResource consumption = resource is being used up; Resource inaccessibility = users are denied access to the resource entirely.",trick:"Exam map: Network attacks > Resource inaccessibility"},
{cat:1,catName:"D2 Threats & Mitigations",acr:"Out-of-cycle logging",full:"2.4 Given a scenario, analyze indicators of malicious activity.",def:"Definition:\nIndicator of compromise: log entries appearing at unexpected times outside of normal operations — for example, logs generated at 3 AM when no users or scheduled jobs should be active. Suggests unauthorized access, scheduled malicious tasks, or automated attacker activity happening when defenders aren't watching.\n\nClue:\nLook for log activity at unusual times — 2 AM admin logins, off-hours file access, or scheduled tasks that weren't approved.\n\nExample:\nAudit logs show privileged account accessing database at 2 AM daily — no maintenance window was scheduled, indicating a malicious scheduled task.\n\nContrast:\nMissing logs = logs deleted or suppressed; Out-of-cycle logging = logs present but at unexpected, suspicious times.",trick:"Exam map: Network attacks > Out-of-cycle logging"},
{cat:1,catName:"D2 Threats & Mitigations",acr:"Published/documented",full:"2.4 Given a scenario, analyze indicators of malicious activity.",def:"Definition:\nVulnerability indicator: once a vulnerability is publicly disclosed (CVE assigned, proof-of-concept published), attackers immediately know the details and exploitation often begins within hours. Publicly documented attacks create urgency — the window between disclosure and mass exploitation can be very short.\n\nClue:\nLook for scenarios where a vendor announces a patch or a CVE is published — the clock starts immediately, systems need patching before attackers exploit the known vulnerability.\n\nExample:\nMicrosoft releases a critical patch on Patch Tuesday — within 48 hours, threat actors are scanning the internet for unpatched systems.\n\nContrast:\nZero-day = no patch exists yet; Published/documented = vulnerability is known publicly and a patch may or may not exist — attackers know the details.",trick:"Exam map: Network attacks > Published/documented"},
{cat:1,catName:"D2 Threats & Mitigations",acr:"Missing logs",full:"2.4 Given a scenario, analyze indicators of malicious activity.",def:"Definition:\nIndicator of compromise: expected log entries are absent — attackers often delete or disable logging to hide their tracks. Missing logs can indicate log tampering, cleared Windows event logs, disabled audit logging, or a misconfigured system that was never logging. Absence of evidence is itself suspicious evidence.\n\nClue:\nLook for gaps in logs where activity should have been recorded — especially during incident timeframes. Cleared logs after a breach is a major red flag.\n\nExample:\nSecurity team investigates a breach but finds the Windows Security event log was cleared at the exact time attacker activity is suspected.\n\nContrast:\nOut-of-cycle logging = logs present at unexpected times; Missing logs = expected logs absent, possibly because attacker deleted them.",trick:"Exam map: Network attacks > Missing logs"},
{cat:1,catName:"D2 Threats & Mitigations",acr:"On-path",full:"2.4 Given a scenario, analyze indicators of malicious activity.",def:"Definition:\nAttack where the attacker secretly intercepts or alters communication between parties.\n\nClue:\nLook for how the attack or weakness behaves, what it targets, and what reduces the damage.\n\nExample:\nReads traffic on rogue Wi-Fi.\n\nContrast:\nReplay reuses captured traffic; On-path intercepts traffic between parties.",trick:"Exam map: Network attacks > On-path"},
{cat:1,catName:"D2 Threats & Mitigations",acr:"Credential replay",full:"2.4 Given a scenario, analyze indicators of malicious activity.",def:"Definition:\nUsing captured credentials or tokens again to gain unauthorized access.\n\nClue:\nLook for how the attack or weakness behaves, what it targets, and what reduces the damage.\n\nExample:\nCaptured token used again.\n\nContrast:\nMitigation/control = defense; this term describes the problem or weakness.",trick:"Exam map: Network attacks > Credential replay"},
{cat:1,catName:"D2 Threats & Mitigations",acr:"Malicious code Application attacks",full:"2.4 Given a scenario, analyze indicators of malicious activity.",def:"Definition:\nTwo linked topics: Malicious code = intentional harmful code inserted into systems (scripts, macros, executables that damage or compromise). Application attacks = exploiting software vulnerabilities through crafted input (injection, XSS, CSRF, directory traversal, forgery, replay). Both target software as the attack vector.\n\nClue:\nMalicious code = harmful code itself (what was installed); Application attack = exploiting app logic (how it was exploited). A web shell is malicious code delivered via an application attack.\n\nExample:\nAttacker uses SQL injection (application attack) to run OS commands and drop a web shell (malicious code) for persistent access.\n\nContrast:\nNetwork attacks target infrastructure; Application attacks target software logic and input handling.",trick:"Exam map: Network attacks > Malicious code / Application attacks"},
{cat:1,catName:"D2 Threats & Mitigations",acr:"Injection",full:"2.4 Given a scenario, analyze indicators of malicious activity.",def:"Definition:\nAttack that inserts malicious input into an application command, query, or interpreter.\n\nClue:\nLook for untrusted input becoming a command or query.\n\nExample:\nSQL code in a login form.\n\nContrast:\nMitigation/control = defense; this term describes the problem or weakness.",trick:"Exam map: Network attacks > Injection"},
{cat:1,catName:"D2 Threats & Mitigations",acr:"Replay",full:"2.4 Given a scenario, analyze indicators of malicious activity.",def:"Definition:\nAttack that captures valid communication and resends it to repeat an action or gain access.\n\nClue:\nLook for how the attack or weakness behaves, what it targets, and what reduces the damage.\n\nExample:\nResend captured login request.\n\nContrast:\nMitigation/control = defense; this term describes the problem or weakness.",trick:"Exam map: Network attacks > Replay"},
{cat:1,catName:"D2 Threats & Mitigations",acr:"Privilege escalation",full:"2.4 Given a scenario, analyze indicators of malicious activity.",def:"Definition:\nGaining higher permissions than originally authorized.\n\nClue:\nLook for how the attack or weakness behaves, what it targets, and what reduces the damage.\n\nExample:\nExploit gives root access.\n\nContrast:\nMitigation/control = defense; this term describes the problem or weakness.",trick:"Exam map: Network attacks > Privilege escalation"},
{cat:1,catName:"D2 Threats & Mitigations",acr:"Forgery",full:"2.4 Given a scenario, analyze indicators of malicious activity.",def:"Definition:\nCreating or modifying requests, messages, or data to appear legitimate.\n\nClue:\nLook for how the attack or weakness behaves, what it targets, and what reduces the damage.\n\nExample:\nCSRF submits a form as the victim.\n\nContrast:\nMitigation/control = defense; this term describes the problem or weakness.",trick:"Exam map: Network attacks > Forgery"},
{cat:1,catName:"D2 Threats & Mitigations",acr:"Directory traversal Cryptographic attacks",full:"2.4 Given a scenario, analyze indicators of malicious activity.",def:"Definition:\nTwo linked topics: Directory traversal = path manipulation attack using ../ sequences to escape the intended directory and access unauthorized files (e.g., ../../etc/passwd). Cryptographic attacks = exploiting weaknesses in cryptographic algorithms or implementations — includes downgrade (force old TLS), collision (two inputs, same hash), birthday (probability of hash collision), and padding oracle attacks.\n\nClue:\nDirectory traversal: look for ../ in a URL or file path. Cryptographic: look for forcing weaker algorithms, hash collisions, or timing attacks.\n\nExample:\nDirectory traversal: URL contains /images/../../etc/passwd. Downgrade attack: attacker forces TLS 1.0 negotiation to exploit POODLE.\n\nContrast:\nDirectory traversal attacks file system access; Cryptographic attacks break encryption/hashing mathematical assumptions.",trick:"Exam map: Application attacks > Directory traversal / Cryptographic attacks"},
{cat:1,catName:"D2 Threats & Mitigations",acr:"Downgrade",full:"2.4 Given a scenario, analyze indicators of malicious activity.",def:"Definition:\nForcing a system to use weaker security settings or older protocols.\n\nClue:\nLook for forcing weaker protocols or older security settings.\n\nExample:\nForce old TLS version.\n\nContrast:\nMitigation/control = defense; this term describes the problem or weakness.",trick:"Exam map: Network attacks > Downgrade"},
{cat:1,catName:"D2 Threats & Mitigations",acr:"Collision",full:"2.4 Given a scenario, analyze indicators of malicious activity.",def:"Definition:\nWhen two different inputs produce the same hash value.\n\nClue:\nLook for two different inputs producing the same hash.\n\nExample:\nHash collision breaks trust.\n\nContrast:\nHashing verifies integrity; Collision breaks trust in hash uniqueness.",trick:"Exam map: Network attacks > Collision"},
{cat:1,catName:"D2 Threats & Mitigations",acr:"Segmentation",full:"2.5 Explain the purpose of mitigation techniques used to secure the enterprise.",def:"Definition:\nDividing networks or systems into smaller areas to limit access and contain attacks.\n\nClue:\nLook for separating networks or systems to limit spread.\n\nExample:\nGuest Wi-Fi cannot reach servers.\n\nContrast:\nIsolation separates more strongly; Segmentation limits movement between zones.",trick:"Exam map: 2.0 Threats, Vulnerabilities, and Mitigations"},
{cat:1,catName:"D2 Threats & Mitigations",acr:"Access control",full:"2.5 Explain the purpose of mitigation techniques used to secure the enterprise.",def:"Definition:\nLimiting who or what can access resources and what actions they can perform.\n\nClue:\nLook for proving identity, assigning access, limiting privileges, or removing access.\n\nExample:\nACL allows HR only.\n\nContrast:\nMitigation/control = defense; this term describes the problem or weakness.",trick:"Exam map: 2.0 Threats, Vulnerabilities, and Mitigations"},
{cat:1,catName:"D2 Threats & Mitigations",acr:"Permissions",full:"2.5 Explain the purpose of mitigation techniques used to secure the enterprise.",def:"Definition:\nSpecific allowed or denied actions for a user, group, process, or system.\n\nClue:\nLook for proving identity, assigning access, limiting privileges, or removing access.\n\nExample:\nRead but not delete.\n\nContrast:\nMitigation/control = defense; this term describes the problem or weakness.",trick:"Exam map: Access control > Permissions"},
{cat:1,catName:"D2 Threats & Mitigations",acr:"Application allow list",full:"2.5 Explain the purpose of mitigation techniques used to secure the enterprise.",def:"Definition:\nControl that allows only approved applications to run.\n\nClue:\nLook for whether the control must stop, detect, fix, discourage, substitute, or limit damage.\n\nExample:\nBlock all software except approved tools.\n\nContrast:\nMitigation/control = defense; this term describes the problem or weakness.",trick:"Exam map: 2.0 Threats, Vulnerabilities, and Mitigations"},
{cat:1,catName:"D2 Threats & Mitigations",acr:"Isolation",full:"2.5 Explain the purpose of mitigation techniques used to secure the enterprise.",def:"Definition:\nSeparating systems, processes, or networks to prevent interaction or spread of compromise.\n\nClue:\nLook for separating risky or compromised systems from others.\n\nExample:\nRun malware sample in a lab VM.\n\nContrast:\nMitigation/control = defense; this term describes the problem or weakness.",trick:"Exam map: 2.0 Threats, Vulnerabilities, and Mitigations"},
{cat:1,catName:"D2 Threats & Mitigations",acr:"Patching",full:"2.5 Explain the purpose of mitigation techniques used to secure the enterprise.",def:"Definition:\nApplying software updates to fix vulnerabilities or stability issues.\n\nClue:\nLook for fixing known vulnerabilities with vendor updates.\n\nExample:\nInstall vendor security update.\n\nContrast:\nHardening reduces attack surface; Patching fixes known flaws.",trick:"Exam map: 2.0 Threats, Vulnerabilities, and Mitigations"},
{cat:1,catName:"D2 Threats & Mitigations",acr:"Monitoring",full:"2.5 Explain the purpose of mitigation techniques used to secure the enterprise.",def:"Definition:\nContinuously observing systems, logs, traffic, or behavior for security and operational issues.\n\nClue:\nLook for watching systems, logs, behavior, or traffic over time.\n\nExample:\nSIEM alerts on suspicious logins.\n\nContrast:\nAlerting notifies; Monitoring watches and collects data.",trick:"Exam map: 2.0 Threats, Vulnerabilities, and Mitigations"},
{cat:1,catName:"D2 Threats & Mitigations",acr:"Least privilege",full:"2.5 Explain the purpose of mitigation techniques used to secure the enterprise.",def:"Definition:\nGranting only the minimum access needed to perform a task.\n\nClue:\nLook for only the minimum access needed to do the job.\n\nExample:\nUser can read reports but cannot change payroll.\n\nContrast:\nPrivilege escalation = gaining more access than allowed.",trick:"Exam map: 2.0 Threats, Vulnerabilities, and Mitigations"},
{cat:1,catName:"D2 Threats & Mitigations",acr:"Configuration enforcement",full:"2.5 Explain the purpose of mitigation techniques used to secure the enterprise.",def:"Definition:\nEnsuring systems keep required secure settings and correcting drift.\n\nClue:\nLook for the exact scenario words and match them to the safest, most specific answer.\n\nExample:\nTool resets insecure config.\n\nContrast:\nMitigation/control = defense; this term describes the problem or weakness.",trick:"Exam map: 2.0 Threats, Vulnerabilities, and Mitigations"},
{cat:1,catName:"D2 Threats & Mitigations",acr:"Decommissioning",full:"2.5 Explain the purpose of mitigation techniques used to secure the enterprise.",def:"Definition:\nSecurely retiring a system, service, or asset from use.\n\nClue:\nLook for the exact scenario words and match them to the safest, most specific answer.\n\nExample:\nWipe server before disposal.\n\nContrast:\nMitigation/control = defense; this term describes the problem or weakness.",trick:"Exam map: 2.0 Threats, Vulnerabilities, and Mitigations"},
{cat:1,catName:"D2 Threats & Mitigations",acr:"Hardening techniques",full:"2.5 Explain the purpose of mitigation techniques used to secure the enterprise.",def:"Definition:\nCategory of security practices that reduce attack surface and strengthen systems before they are compromised. Includes: installing endpoint protection, host-based firewalls, HIPS, disabling unused ports/protocols, changing default passwords, removing unnecessary software/services, and applying secure configurations.\n\nClue:\nLook for actions taken to make a system more resistant to attack before an incident occurs — reducing what an attacker could target.\n\nExample:\nNew server build: remove unused services, change default credentials, enable host firewall, install EDR agent, apply CIS benchmark.\n\nContrast:\nPatching fixes known vulnerabilities; Hardening reduces unnecessary exposure and enforces secure defaults — both are needed.",trick:"Exam map: Hardening techniques"},
{cat:1,catName:"D2 Threats & Mitigations",acr:"Installation of endpoint",full:"2.5 Explain the purpose of mitigation techniques used to secure the enterprise.",def:"Definition:\nInstalling security software on individual endpoints (workstations, servers, mobile devices) as a hardening step. Endpoint security agents include: antivirus/anti-malware, EDR (Endpoint Detection and Response), DLP agents, and host-based IDS/IPS. Provides local defense independent of network controls.\n\nClue:\nLook for security software deployed directly on the device — not at the network perimeter. Even if attacker bypasses the firewall, endpoint protection is still running.\n\nExample:\nCorporate laptops receive EDR agent during imaging — agent monitors process execution, file changes, and network connections on each device.\n\nContrast:\nNetwork-based controls (firewall, NIPS) protect at the perimeter; Endpoint security protects the individual device regardless of where it connects.",trick:"Exam map: Hardening techniques > Installation of endpoint protection"},
{cat:1,catName:"D2 Threats & Mitigations",acr:"Host-based firewall",full:"2.5 Explain the purpose of mitigation techniques used to secure the enterprise.",def:"Definition:\nFirewall running on an individual endpoint or server.\n\nClue:\nLook for whether the control must stop, detect, fix, discourage, substitute, or limit damage.\n\nExample:\nLaptop blocks inbound connections.\n\nContrast:\nMitigation/control = defense; this term describes the problem or weakness.",trick:"Exam map: Hardening techniques > Host-based firewall"},
{cat:1,catName:"D2 Threats & Mitigations",acr:"Host-based intrusion prevention",full:"2.5 Explain the purpose of mitigation techniques used to secure the enterprise.",def:"Definition:\nHIPS (Host-based Intrusion Prevention System) — software installed on a single endpoint that monitors OS calls, file activity, network connections, and process behavior, and actively blocks suspicious activity in real-time. Unlike IDS (which only alerts), IPS blocks. Unlike NIPS (network-based), HIPS protects a specific host.\n\nClue:\nLook for real-time blocking of malicious behavior on a specific device — HIPS can stop an attack even after the attacker is already inside the network.\n\nExample:\nHIPS on a server detects a process attempting to modify registry run keys and blocks it, then alerts the SOC.\n\nContrast:\nHIDS = detects and alerts but does not block; HIPS = detects and actively blocks. NIPS operates at the network level; HIPS operates at the host level.",trick:"Exam map: Hardening techniques > Host-based intrusion prevention (HIPS)"},
{cat:1,catName:"D2 Threats & Mitigations",acr:"Disabling ports/protocols",full:"2.5 Explain the purpose of mitigation techniques used to secure the enterprise.",def:"Definition:\nReducing attack surface by turning off unused network ports and protocols.\n\nClue:\nLook for whether the control must stop, detect, fix, discourage, substitute, or limit damage.\n\nExample:\nDisable Telnet.\n\nContrast:\nMitigation/control = defense; this term describes the problem or weakness.",trick:"Exam map: Hardening techniques > Disabling ports/protocols"},
{cat:1,catName:"D2 Threats & Mitigations",acr:"Default password changes",full:"2.5 Explain the purpose of mitigation techniques used to secure the enterprise.",def:"Definition:\nReplacing vendor default passwords before systems are used.\n\nClue:\nLook for proving identity, assigning access, limiting privileges, or removing access.\n\nExample:\nChange admin/admin.\n\nContrast:\nMitigation/control = defense; this term describes the problem or weakness.",trick:"Exam map: Hardening techniques > Default password changes"},
{cat:1,catName:"D2 Threats & Mitigations",acr:"Removal of unnecessary",full:"2.5 Explain the purpose of mitigation techniques used to secure the enterprise.",def:"Definition:\nHardening technique: removing software, services, accounts, protocols, or features that are not needed for a system's intended purpose. Every unnecessary component is a potential attack vector. Remove: default demo apps, guest accounts, sample databases, unused network services, bloatware, unnecessary open ports.\n\nClue:\nLook for trimming a system down to only what it needs — the smaller the attack surface, the fewer ways in.\n\nExample:\nNew web server: uninstall FTP, Telnet, and unused scripting engines; disable SMB and RDP; remove sample web pages and default admin accounts.\n\nContrast:\nPatching fixes known flaws in necessary software; Removal of unnecessary eliminates software that doesn't need to exist at all.",trick:"Exam map: Hardening techniques > Removal of unnecessary software/services"},
{cat:1,catName:"D2 Threats & Mitigations",acr:"Virtualization •",full:"2.5 Explain the purpose of mitigation techniques used to secure the enterprise.",def:"Definition:\nRunning virtual systems on shared physical hardware.\n\nClue:\nLook for virtual machines or multiple virtual systems on shared hardware.\n\nExample:\nRun Linux VM on Windows host.\n\nContrast:\nContainerization packages apps; Virtualization runs full virtual machines.",trick:"Exam map: 2.0 Threats, Vulnerabilities, and Mitigations"},
{cat:1,catName:"D2 Threats & Mitigations",acr:"Resource reuse",full:"2.5 Explain the purpose of mitigation techniques used to secure the enterprise.",def:"Definition:\nVirtualization security risk: when a VM is destroyed or reallocated, its memory, disk, and resources may be assigned to a new VM without proper sanitization. The new VM could potentially read residual data from the previous tenant — a confidentiality risk in shared/cloud environments. Mitigation: hypervisor must zero memory before allocation.\n\nClue:\nLook for multi-tenant or cloud environments where VMs share physical hardware — data left in memory or storage from one tenant could leak to another.\n\nExample:\nCloud VM is terminated and its memory block reused for another customer's VM — if not zeroed, the new VM could read previous customer's encryption keys from memory.\n\nContrast:\nVM escape = attacker breaks out of guest to hypervisor; Resource reuse = data leaks between VMs through improperly cleared shared resources.",trick:"Exam map: Virtualization > Resource reuse"},
{cat:1,catName:"D2 Threats & Mitigations",acr:"Cloud-specific",full:"2.5 Explain the purpose of mitigation techniques used to secure the enterprise.",def:"Definition:\nVulnerabilities and risks unique to cloud environments: misconfigured storage buckets (S3 public access), overly permissive IAM roles, insecure APIs, insufficient logging, shared tenancy risks, account hijacking via stolen cloud credentials, cloud hopping (using compromised cloud account to pivot), and serverless function vulnerabilities.\n\nClue:\nLook for cloud-specific scenarios: public S3 bucket, overly permissive IAM, missing CloudTrail logs, or stolen cloud console credentials — these are cloud-specific attack surfaces.\n\nExample:\nDevOper forgets to restrict an S3 bucket — it becomes publicly accessible, exposing customer PII to anyone on the internet.\n\nContrast:\nOn-premises vulnerabilities involve physical hardware and OS; Cloud-specific vulnerabilities involve misconfigurations of cloud services and identity controls.",trick:"Exam map: Cloud-specific vulnerabilities"},
{cat:1,catName:"D2 Threats & Mitigations",acr:"Service provider",full:"2.5 Explain the purpose of mitigation techniques used to secure the enterprise.",def:"Definition:\nSupply chain risk: a managed service provider (MSP), cloud provider, or outsourced IT service that has access to your systems or data. Compromise of the provider propagates to all of its customers simultaneously. Example: SolarWinds breach — MSP tools were trojanized, reaching thousands of customer networks.\n\nClue:\nLook for third-party companies that manage IT services on your behalf — their compromise = your compromise.\n\nExample:\nMSP manages patching for 200 companies. Attacker compromises MSP's RMM tool — suddenly 200 client networks are accessible.\n\nContrast:\nHardware provider = physical device vendor; Software provider = software vendor; Service provider = ongoing managed services with network access.",trick:"Exam map: Supply chain > Service provider"},
{cat:1,catName:"D2 Threats & Mitigations",acr:"Hardware provider",full:"2.5 Explain the purpose of mitigation techniques used to secure the enterprise.",def:"Definition:\nSupply chain risk: vendor supplying physical hardware components (servers, routers, chips). Risks: counterfeit components with reduced reliability, hardware backdoors or implants installed at manufacturing, firmware pre-loaded with malware. Physical hardware is trusted at a deep level — a compromised chip is nearly impossible to detect after the fact.\n\nClue:\nLook for hardware purchased from untrusted or unvetted vendors, counterfeit components, or nation-state hardware supply chain attacks.\n\nExample:\nMalicious chips secretly added to server motherboards during manufacturing — when activated, they create a hidden backdoor bypassing all software controls.\n\nContrast:\nSoftware provider risk = malicious code in updates; Hardware provider risk = malicious components in physical devices.",trick:"Exam map: Supply chain > Hardware provider"},
{cat:1,catName:"D2 Threats & Mitigations",acr:"Software provider",full:"2.5 Explain the purpose of mitigation techniques used to secure the enterprise.",def:"Definition:\nSupply chain risk: vendor who supplies software or software updates. Risks: malicious code inserted into legitimate software updates (SolarWinds SUNBURST malware in Orion update), compromised build pipelines (CI/CD poisoning), typosquatting malicious packages in package registries (npm, PyPI). Trusted software signed by the vendor can still carry malware.\n\nClue:\nLook for attacks where legitimate, signed software updates deliver malware — you trusted the software, but the vendor's build process was compromised.\n\nExample:\nSolarWinds Orion update signed by vendor — but build server was compromised, so the signed update contained SUNBURST backdoor.\n\nContrast:\nHardware provider risk = physical; Software provider risk = malicious code in trusted software updates or dependencies.",trick:"Exam map: Supply chain > Software provider"},
{cat:1,catName:"D2 Threats & Mitigations",acr:"Cryptographic",full:"2.5 Explain the purpose of mitigation techniques used to secure the enterprise.",def:"Definition:\nCryptographic mitigations: using strong algorithms and proper implementation to protect data. Key practices: use AES-256 for symmetric encryption, RSA-2048+ or ECC for asymmetric, SHA-256+ for hashing, bcrypt/PBKDF2/Argon2 for password hashing (never MD5/SHA-1 for passwords), TLS 1.2+ for transport. Avoid: MD5, SHA-1, DES, 3DES, RC4, and export-grade ciphers.\n\nClue:\nLook for choosing between strong and weak cryptographic algorithms — the exam will ask you to identify the insecure one (MD5, DES, RC4, SHA-1) or pick the secure one (AES, SHA-256, TLS 1.3, bcrypt).\n\nExample:\nQuestion: which hashing algorithm is appropriate for password storage? Answer: bcrypt (slow, designed for passwords) NOT SHA-256 (fast, designed for data integrity).\n\nContrast:\nCryptographic attacks exploit weaknesses; Cryptographic mitigations prevent those attacks by using proper algorithms and key management.",trick:"Exam map: Cryptographic mitigations"},
{cat:2,catName:"D3 Architecture",acr:"Cloud",full:"3.0 Objective topic from Security Architecture",def:"Definition:\nCategory of cloud architecture concepts. Service models: IaaS (customer manages OS/apps, provider manages hardware/hypervisor), PaaS (customer manages app/data, provider manages runtime/OS), SaaS (provider manages almost everything, customer manages access/data). Deployment: Public (shared infrastructure, multi-tenant), Private (dedicated), Community (shared between specific orgs), Hybrid (mix of on-prem and cloud).\n\nClue:\nMatch service model to responsibility: IaaS = most customer control; SaaS = least customer control. Shared responsibility matrix maps who secures what. Cloud security exam questions often involve identifying the correct responsibility split.\n\nExample:\nCompany uses AWS EC2 (IaaS) — AWS secures the data center and hypervisor. Customer must patch the OS, configure security groups, and encrypt data. If using Salesforce (SaaS), Salesforce manages all that — customer manages user access and data.\n\nContrast:\nIaaS = infrastructure flexibility, more customer responsibility; SaaS = easy deployment, least control; PaaS = middle ground for developers. On-premises = full control and responsibility.",trick:"Exam map: Architecture and infrastructure concepts > Cloud"},
{cat:2,catName:"D3 Architecture",acr:"Responsibility matrix",full:"3.0 Objective topic from Security Architecture",def:"Definition:\nShared responsibility model document that defines what security controls the cloud provider manages vs. what the customer must manage. IaaS: provider owns physical/hypervisor, customer owns OS+apps+data. PaaS: customer owns app+data. SaaS: provider owns almost everything, customer manages access/data.\n\nClue:\nLook for who is responsible for what in a cloud model — on the exam, identify the service model (IaaS/PaaS/SaaS) then determine whether the security gap is the provider's or customer's responsibility.\n\nExample:\nCompany uses IaaS (AWS EC2) — AWS secures the hypervisor, but the customer is responsible for OS patching, firewalls, and app security.\n\nContrast:\nOn-premises = customer owns everything; SaaS = provider owns almost everything; IaaS/PaaS = split responsibility.",trick:"Exam map: Cloud > Responsibility matrix"},
{cat:2,catName:"D3 Architecture",acr:"Hybrid considerations",full:"3.0 Objective topic from Security Architecture",def:"Definition:\nSecurity challenges in environments mixing on-premises and cloud resources. Key concerns: consistent security policy enforcement across both environments, identity management spanning both (federated identity), network segmentation and connectivity (VPN/Direct Connect), data residency requirements, inconsistent logging/monitoring, and differing patch cycles.\n\nClue:\nLook for scenarios where some systems are on-prem and some are in the cloud — the challenge is applying consistent controls across both.\n\nExample:\nCompany runs AD on-premises but uses Microsoft 365 in cloud — must synchronize identity, enforce MFA across both, and ensure logs from both reach the SIEM.\n\nContrast:\nFull cloud = provider manages infrastructure; On-premises only = full internal control; Hybrid = both, requiring bridged policies and identity.",trick:"Exam map: Cloud > Hybrid considerations"},
{cat:2,catName:"D3 Architecture",acr:"Third-party vendors",full:"3.0 Objective topic from Security Architecture",def:"Definition:\nCloud providers and external service vendors introduce risk through the shared responsibility model, data exposure, and loss of direct control. Security requirements: due diligence before selection, contractual security obligations, right-to-audit clauses, vendor risk assessments, data handling agreements (DPA), and regular review of vendor security posture.\n\nClue:\nLook for cloud architecture questions about trusting external providers with data or systems — what controls must you require from them?\n\nExample:\nCompany stores customer data in a cloud SaaS app — must ensure vendor encrypts data at rest, maintains compliance, allows audit, and notifies of breaches.\n\nContrast:\nInternal IT = direct control; Third-party vendor = contractual control and shared responsibility.",trick:"Exam map: Cloud > Third-party vendors"},
{cat:2,catName:"D3 Architecture",acr:"Serverless",full:"3.0 Objective topic from Security Architecture",def:"Definition:\nCloud model where the provider manages servers and scaling while customers deploy functions or application logic.\n\nClue:\nLook for cloud functions where the provider manages servers.\n\nExample:\nFunction runs when a file is uploaded.\n\nContrast:\nIaaS/VMs = you manage servers; Serverless = provider manages servers.",trick:"Exam map: Architecture and infrastructure concepts > Serverless"},
{cat:2,catName:"D3 Architecture",acr:"Microservices",full:"3.0 Objective topic from Security Architecture",def:"Definition:\nArchitecture that breaks an application into small independent services.\n\nClue:\nLook for where the asset lives, what can fail, and how the design protects or restores CIA.\n\nExample:\nLogin, billing, and search run separately.\n\nContrast:\nSecurity operation = daily action; architecture term = design choice that affects protection or recovery.",trick:"Exam map: Architecture and infrastructure concepts > Microservices"},
{cat:2,catName:"D3 Architecture",acr:"Network infrastructure",full:"3.0 Objective topic from Security Architecture",def:"Definition:\nThe physical and logical components enabling network communication: routers, switches, firewalls, load balancers, wireless APs, cables, and the network design (VLANs, DMZ, subnets). Securing network infrastructure includes: hardening devices, segmentation, secure protocols, physical protection, monitoring, and redundancy.\n\nClue:\nLook for questions about network design security — placement of firewalls, segmentation, DMZ setup, or securing the network devices themselves.\n\nExample:\nNetwork infrastructure security: place web servers in DMZ, segment internal VLAN from guest VLAN, use 802.1X on switch ports, disable management via internet-facing interfaces.\n\nContrast:\nEndpoint security = individual devices; Network infrastructure security = the network itself and the devices that make it run.",trick:"Exam map: Architecture > Network infrastructure"},
{cat:2,catName:"D3 Architecture",acr:"Physical isolation ° Air-gapped",full:"3.0 Objective topic from Security Architecture",def:"Definition:\nAir-gapped = completely physically isolated from untrusted networks — no wired or wireless network connections whatsoever. Used for the most sensitive systems: classified government systems, ICS/SCADA controlling critical infrastructure, nuclear facility controls. Data transfers only via physically controlled removable media under strict procedures. Stuxnet famously crossed an air gap via USB.\n\nClue:\nLook for the most secure isolation option — air gap is the extreme: totally disconnected. Any network connection (even a single cable) breaks the air gap.\n\nExample:\nNuclear power plant control systems are air-gapped — no internet, no corporate LAN connection. Updates delivered via write-once media under dual-person control.\n\nContrast:\nLogical segmentation (VLANs) = software separation; Physical isolation = no shared physical media; Air gap = complete physical disconnection from all external networks.",trick:"Exam map: Network infrastructure > Physical isolation / Air-gapped"},
{cat:2,catName:"D3 Architecture",acr:"Logical segmentation",full:"3.0 Objective topic from Security Architecture",def:"Definition:\nSeparating networks or systems through configuration, such as VLANs, ACLs, or security groups.\n\nClue:\nLook for where the asset lives, what can fail, and how the design protects or restores CIA.\n\nExample:\nVLANs split departments.\n\nContrast:\nThreat/vulnerability = problem; control/mitigation = defense.",trick:"Exam map: Architecture and infrastructure concepts > Network infrastructure > Logical segmentation"},
{cat:2,catName:"D3 Architecture",acr:"On-premises",full:"3.0 Objective topic from Security Architecture",def:"Definition:\nTechnology hosted and managed inside the organization’s own facilities.\n\nClue:\nLook for where the asset lives, what can fail, and how the design protects or restores CIA.\n\nExample:\nServers in company data center.\n\nContrast:\nSecurity operation = daily action; architecture term = design choice that affects protection or recovery.",trick:"Exam map: Architecture and infrastructure concepts > On-premises"},
{cat:2,catName:"D3 Architecture",acr:"Centralized vs. decentralized",full:"3.0 Objective topic from Security Architecture",def:"Definition:\nDesign choice between one central control point and distributed control across multiple locations or teams.\n\nClue:\nLook for where the asset lives, what can fail, and how the design protects or restores CIA.\n\nExample:\nHQ-managed security vs branch-managed security.\n\nContrast:\nSecurity operation = daily action; architecture term = design choice that affects protection or recovery.",trick:"Exam map: Architecture and infrastructure concepts > Centralized vs. decentralized"},
{cat:2,catName:"D3 Architecture",acr:"Containerization",full:"3.0 Objective topic from Security Architecture",def:"Definition:\nPackaging applications with dependencies into isolated containers.\n\nClue:\nLook for packaged apps running in isolated containers.\n\nExample:\nDocker container holds app dependencies.\n\nContrast:\nVirtualization virtualizes whole machines; Containers isolate applications.",trick:"Exam map: Architecture and infrastructure concepts > Containerization"},
{cat:2,catName:"D3 Architecture",acr:"Embedded systems",full:"3.0 Objective topic from Security Architecture",def:"Definition:\nSpecial-purpose computing systems built into devices.\n\nClue:\nLook for where the asset lives, what can fail, and how the design protects or restores CIA.\n\nExample:\nSmart thermostat controller.\n\nContrast:\nSecurity operation = daily action; architecture term = design choice that affects protection or recovery.",trick:"Exam map: Architecture and infrastructure concepts > Embedded systems"},
{cat:2,catName:"D3 Architecture",acr:"Availability",full:"3.0 Objective topic from Security Architecture",def:"Definition:\nEnsuring authorized users can access systems and data when needed.\n\nClue:\nLook for where the asset lives, what can fail, and how the design protects or restores CIA.\n\nExample:\nWebsite stays online.\n\nContrast:\nSecurity operation = daily action; architecture term = design choice that affects protection or recovery.",trick:"Exam map: Considerations > Availability"},
{cat:2,catName:"D3 Architecture",acr:"Resilience",full:"3.0 Objective topic from Security Architecture",def:"Definition:\nAbility to keep operating or recover quickly during failures or attacks.\n\nClue:\nLook for where the asset lives, what can fail, and how the design protects or restores CIA.\n\nExample:\nService keeps running after one server fails.\n\nContrast:\nSecurity operation = daily action; architecture term = design choice that affects protection or recovery.",trick:"Exam map: Considerations > Resilience"},
{cat:2,catName:"D3 Architecture",acr:"Cost",full:"3.0 Objective topic from Security Architecture",def:"Definition:\nThe money, time, staff, and resources required to build, operate, secure, or recover a system.\n\nClue:\nLook for where the asset lives, what can fail, and how the design protects or restores CIA.\n\nExample:\nAsk where it lives, what can fail, and how to protect it.\n\nContrast:\nSecurity operation = daily action; architecture term = design choice that affects protection or recovery.",trick:"Exam map: Considerations > Cost"},
{cat:2,catName:"D3 Architecture",acr:"Responsiveness",full:"3.0 Objective topic from Security Architecture",def:"Definition:\nHow quickly a system, team, or process reacts to demand, incidents, failures, or user needs.\n\nClue:\nLook for where the asset lives, what can fail, and how the design protects or restores CIA.\n\nExample:\nAsk where it lives, what can fail, and how to protect it.\n\nContrast:\nSecurity operation = daily action; architecture term = design choice that affects protection or recovery.",trick:"Exam map: Considerations > Responsiveness"},
{cat:2,catName:"D3 Architecture",acr:"Scalability",full:"3.0 Objective topic from Security Architecture",def:"Definition:\nAbility to grow capacity as demand increases.\n\nClue:\nLook for where the asset lives, what can fail, and how the design protects or restores CIA.\n\nExample:\nAdd more servers during traffic spike.\n\nContrast:\nSecurity operation = daily action; architecture term = design choice that affects protection or recovery.",trick:"Exam map: Considerations > Scalability"},
{cat:2,catName:"D3 Architecture",acr:"Ease of deployment",full:"3.0 Objective topic from Security Architecture",def:"Definition:\nHow simple and reliable it is to roll out a system, control, patch, or configuration.\n\nClue:\nLook for where the asset lives, what can fail, and how the design protects or restores CIA.\n\nExample:\nAsk where it lives, what can fail, and how to protect it.\n\nContrast:\nSecurity operation = daily action; architecture term = design choice that affects protection or recovery.",trick:"Exam map: Considerations > Ease of deployment"},
{cat:2,catName:"D3 Architecture",acr:"Risk transference",full:"3.0 Objective topic from Security Architecture",def:"Definition:\nMoving risk impact to another party, often through insurance or outsourcing.\n\nClue:\nLook for where the asset lives, what can fail, and how the design protects or restores CIA.\n\nExample:\nCyber insurance pays after breach.\n\nContrast:\nTechnical control = system defense; governance term = decision, evidence, responsibility, or requirement.",trick:"Exam map: Considerations > Risk transference"},
{cat:2,catName:"D3 Architecture",acr:"Ease of recovery",full:"3.0 Objective topic from Security Architecture",def:"Definition:\nHow quickly and cleanly a system or service can be restored after failure or incident.\n\nClue:\nLook for where the asset lives, what can fail, and how the design protects or restores CIA.\n\nExample:\nAsk where it lives, what can fail, and how to protect it.\n\nContrast:\nSecurity operation = daily action; architecture term = design choice that affects protection or recovery.",trick:"Exam map: Considerations > Ease of recovery"},
{cat:2,catName:"D3 Architecture",acr:"Patch availability",full:"3.0 Objective topic from Security Architecture",def:"Definition:\nWhether updates exist to fix known vulnerabilities.\n\nClue:\nLook for where the asset lives, what can fail, and how the design protects or restores CIA.\n\nExample:\nVendor releases security patch.\n\nContrast:\nThreat/vulnerability = problem; control/mitigation = defense.",trick:"Exam map: Considerations > Patch availability"},
{cat:2,catName:"D3 Architecture",acr:"Inability to patch",full:"3.0 Objective topic from Security Architecture",def:"Definition:\nCondition where systems cannot be updated, often due to legacy, vendor, or operational constraints.\n\nClue:\nLook for where the asset lives, what can fail, and how the design protects or restores CIA.\n\nExample:\nIsolate old medical device.\n\nContrast:\nThreat/vulnerability = problem; control/mitigation = defense.",trick:"Exam map: Considerations > Inability to patch"},
{cat:2,catName:"D3 Architecture",acr:"Compute",full:"3.0 Objective topic from Security Architecture",def:"Definition:\nProcessing resources such as CPU, memory, and server capacity needed to run workloads securely and reliably.\n\nClue:\nLook for where the asset lives, what can fail, and how the design protects or restores CIA.\n\nExample:\nAsk where it lives, what can fail, and how to protect it.\n\nContrast:\nSecurity operation = daily action; architecture term = design choice that affects protection or recovery.",trick:"Exam map: Considerations > Compute"},
{cat:2,catName:"D3 Architecture",acr:"Device placement",full:"3.2 Given a scenario, apply security principles to secure enterprise infrastructure.",def:"Definition:\nChoosing where security devices sit in the network so they can see or control the right traffic.\n\nClue:\nLook for where the asset lives, what can fail, and how the design protects or restores CIA.\n\nExample:\nIPS inline before servers.\n\nContrast:\nSecurity operation = daily action; architecture term = design choice that affects protection or recovery.",trick:"Exam map: Infrastructure considerations > Device placement"},
{cat:2,catName:"D3 Architecture",acr:"Security zones",full:"3.2 Given a scenario, apply security principles to secure enterprise infrastructure.",def:"Definition:\nNetwork or system areas grouped by trust level or function.\n\nClue:\nLook for where the asset lives, what can fail, and how the design protects or restores CIA.\n\nExample:\nPublic DMZ separate from internal LAN.\n\nContrast:\nSecurity operation = daily action; architecture term = design choice that affects protection or recovery.",trick:"Exam map: Infrastructure considerations > Security zones"},
{cat:2,catName:"D3 Architecture",acr:"Attack surface",full:"3.2 Given a scenario, apply security principles to secure enterprise infrastructure.",def:"Definition:\nAll points where an attacker could try to enter, exploit, or interact with a system.\n\nClue:\nLook for how the attack or weakness behaves, what it targets, and what reduces the damage.\n\nExample:\nOpen ports and login pages.\n\nContrast:\nMitigation/control = defense; this term describes the problem or weakness.",trick:"Exam map: Infrastructure considerations > Attack surface"},
{cat:2,catName:"D3 Architecture",acr:"Connectivity",full:"3.2 Given a scenario, apply security principles to secure enterprise infrastructure.",def:"Definition:\nHow systems connect to networks, services, users, or each other.\n\nClue:\nLook for where the asset lives, what can fail, and how the design protects or restores CIA.\n\nExample:\nVPN links remote users to internal apps.\n\nContrast:\nSecurity operation = daily action; architecture term = design choice that affects protection or recovery.",trick:"Exam map: Infrastructure considerations > Connectivity"},
{cat:2,catName:"D3 Architecture",acr:"Failure modes",full:"3.2 Given a scenario, apply security principles to secure enterprise infrastructure.",def:"Definition:\nHow a security control behaves when it fails — a critical design decision. Two modes: Fail-open (allows traffic/access when control fails — prioritizes availability but sacrifices security). Fail-closed/Fail-secure (blocks traffic/access when control fails — prioritizes security but may impact availability). Choose based on what's worse: a breach or an outage.\n\nClue:\nLook for what happens when the security device stops working — does traffic get through (fail-open) or get blocked (fail-closed)? Security-critical systems should fail-closed.\n\nExample:\nIf an IPS fails: Fail-open = traffic flows normally (availability maintained, security lost). Fail-closed = all traffic blocked (security maintained, outage occurs).\n\nContrast:\nFail-open prioritizes availability; Fail-closed prioritizes security. Match to the CIA triad priority for the protected asset.",trick:"Exam map: Infrastructure considerations > Failure modes"},
{cat:2,catName:"D3 Architecture",acr:"Fail-open",full:"3.2 Given a scenario, apply security principles to secure enterprise infrastructure.",def:"Definition:\nFailure mode where access or traffic is allowed if a control fails.\n\nClue:\nLook for where the asset lives, what can fail, and how the design protects or restores CIA.\n\nExample:\nDoor unlocks during failure.\n\nContrast:\nSecurity operation = daily action; architecture term = design choice that affects protection or recovery.",trick:"Exam map: Infrastructure considerations > Fail-open"},
{cat:2,catName:"D3 Architecture",acr:"Fail-closed",full:"3.2 Given a scenario, apply security principles to secure enterprise infrastructure.",def:"Definition:\nFailure mode where access or traffic is blocked if a control fails.\n\nClue:\nLook for where the asset lives, what can fail, and how the design protects or restores CIA.\n\nExample:\nFirewall blocks traffic if it fails.\n\nContrast:\nSecurity operation = daily action; architecture term = design choice that affects protection or recovery.",trick:"Exam map: Infrastructure considerations > Fail-open > Fail-closed"},
{cat:2,catName:"D3 Architecture",acr:"Device attribute",full:"3.2 Given a scenario, apply security principles to secure enterprise infrastructure.",def:"Definition:\nCharacteristics that determine how a security device interacts with network traffic. Key attributes: Active (processes/modifies traffic, can block) vs. Passive (observes copies of traffic, cannot block); Inline (sits in the traffic path) vs. Out-of-band/Tap (receives mirrored traffic). Active+Inline = can prevent attacks. Passive+Tap = detection only.\n\nClue:\nLook for whether the device can block or only detect — Active/Inline = can block; Passive/Tap = detection only. An IPS must be inline and active to block.\n\nExample:\nIDS in tap mode: passive, out-of-band, can only alert. IPS inline: active, in-path, can block malicious traffic before it reaches the target.\n\nContrast:\nIDS = passive detection; IPS = active prevention. Passive/tap = no impact on traffic flow; Active/inline = can block but creates single point of failure.",trick:"Exam map: Infrastructure considerations > Device attribute"},
{cat:2,catName:"D3 Architecture",acr:"Active vs. passive",full:"3.2 Given a scenario, apply security principles to secure enterprise infrastructure.",def:"Definition:\nActive devices interact with traffic; passive devices observe without changing traffic.\n\nClue:\nLook for where the asset lives, what can fail, and how the design protects or restores CIA.\n\nExample:\nIPS blocks, IDS alerts.\n\nContrast:\nSecurity operation = daily action; architecture term = design choice that affects protection or recovery.",trick:"Exam map: Infrastructure considerations > Device attribute > Active vs. passive"},
{cat:2,catName:"D3 Architecture",acr:"Inline vs. tap/monitor",full:"3.2 Given a scenario, apply security principles to secure enterprise infrastructure.",def:"Definition:\nInline devices sit in the traffic path; tap or monitor devices receive copies of traffic.\n\nClue:\nLook for where the asset lives, what can fail, and how the design protects or restores CIA.\n\nExample:\nInline IPS can block.\n\nContrast:\nThreat/vulnerability = problem; control/mitigation = defense.",trick:"Exam map: Infrastructure considerations > Device attribute > Inline vs. tap/monitor"},
{cat:2,catName:"D3 Architecture",acr:"Jump server",full:"3.2 Given a scenario, apply security principles to secure enterprise infrastructure.",def:"Definition:\nControlled host used as an administrative entry point into protected systems.\n\nClue:\nLook for where the asset lives, what can fail, and how the design protects or restores CIA.\n\nExample:\nSSH first to jump box, then to servers.\n\nContrast:\nSecurity operation = daily action; architecture term = design choice that affects protection or recovery.",trick:"Exam map: Infrastructure considerations > Network appliances > Jump server"},
{cat:2,catName:"D3 Architecture",acr:"Proxy server",full:"3.2 Given a scenario, apply security principles to secure enterprise infrastructure.",def:"Definition:\nIntermediary server that forwards requests and can filter, log, or hide client connections.\n\nClue:\nLook for where the asset lives, what can fail, and how the design protects or restores CIA.\n\nExample:\nWeb proxy filters user browsing.\n\nContrast:\nSecurity operation = daily action; architecture term = design choice that affects protection or recovery.",trick:"Exam map: Infrastructure considerations > Network appliances > Proxy server"},
{cat:2,catName:"D3 Architecture",acr:"Load balancer",full:"3.2 Given a scenario, apply security principles to secure enterprise infrastructure.",def:"Definition:\nDevice or service that distributes traffic across multiple servers.\n\nClue:\nLook for where the asset lives, what can fail, and how the design protects or restores CIA.\n\nExample:\nSends users to healthy web servers.\n\nContrast:\nSecurity operation = daily action; architecture term = design choice that affects protection or recovery.",trick:"Exam map: Infrastructure considerations > Network appliances > Load balancer"},
{cat:2,catName:"D3 Architecture",acr:"Sensors Port security",full:"3.2 Given a scenario, apply security principles to secure enterprise infrastructure.",def:"Definition:\nTwo linked topics: Sensors = network collection points (SPAN ports, network taps, flow sensors, packet brokers) that feed data to security tools like IDS/SIEM. Port security = switch-level control limiting which devices can connect to a switch port — limit by MAC address count, specific MACs, or require 802.1X authentication to prevent rogue device connection.\n\nClue:\nSensors = how security tools see network traffic (passive copies). Port security = how switches control what can plug in (access restriction). Both are infrastructure security controls.\n\nExample:\nSPAN port mirrors traffic to IDS (sensor). Port security on switch limits each port to one MAC address — plugging in a hub triggers violation response (shutdown/restrict).\n\nContrast:\n802.1X = full authentication before port access; Port security (MAC limit) = simpler, limits MAC count but doesn't verify identity.",trick:"Exam map: Network appliances > Sensors / Port security"},
{cat:2,catName:"D3 Architecture",acr:"802.1X",full:"3.2 Given a scenario, apply security principles to secure enterprise infrastructure.",def:"Definition:\nIEEE standard for port-based Network Access Control (NAC). Requires authentication before granting network access — on both wired Ethernet and Wi-Fi. Three-party model: Supplicant (device) → Authenticator (switch/AP) → Authentication Server (RADIUS). Uses EAP for credentials. Prevents rogue devices from joining the network just by plugging in.\n\nClue:\nLook for corporate Wi-Fi or wired LAN requiring authentication before access. 802.1X = the standard; RADIUS = the server; EAP = the auth method. Guest networks often skip 802.1X.\n\nExample:\nEmployee laptop connects to office Wi-Fi — 802.1X forces authentication to RADIUS server using machine certificate before DHCP is issued. Unknown device gets no network access.\n\nContrast:\nPre-shared key Wi-Fi (WPA2-Personal) = no per-user auth; 802.1X (WPA2/3-Enterprise) = per-user/device authentication against RADIUS.",trick:"Exam map: Network appliances > 802.1X"},
{cat:2,catName:"D3 Architecture",acr:"Layer 4/Layer 7",full:"3.2 Given a scenario, apply security principles to secure enterprise infrastructure.",def:"Definition:\nLayer 4 controls use transport data like ports; Layer 7 controls inspect application data.\n\nClue:\nLook for where the asset lives, what can fail, and how the design protects or restores CIA.\n\nExample:\nBlock TCP 443 vs block Facebook.\n\nContrast:\nThreat/vulnerability = problem; control/mitigation = defense.",trick:"Exam map: Selection of effective controls > Layer 4/Layer 7"},
{cat:2,catName:"D3 Architecture",acr:"Remote access",full:"3.2 Given a scenario, apply security principles to secure enterprise infrastructure.",def:"Definition:\nConnecting to systems or networks from outside their local environment.\n\nClue:\nLook for proving identity, assigning access, limiting privileges, or removing access.\n\nExample:\nVPN into company network.\n\nContrast:\nInsecure protocol = avoid when confidentiality is needed; secure protocol = prefer for protected communication.",trick:"Exam map: Secure communication/access > Remote access"},
{cat:2,catName:"D3 Architecture",acr:"Tunneling",full:"3.2 Given a scenario, apply security principles to secure enterprise infrastructure.",def:"Definition:\nEncapsulating one type of traffic inside another protocol, often for secure remote access.\n\nClue:\nLook for proving identity, assigning access, limiting privileges, or removing access.\n\nExample:\nSSH tunnel carries another service.\n\nContrast:\nInsecure protocol = avoid when confidentiality is needed; secure protocol = prefer for protected communication.",trick:"Exam map: Secure communication/access > Tunneling"},
{cat:2,catName:"D3 Architecture",acr:"Regulated",full:"3.3 Compare and contrast concepts and strategies to protect data.",def:"Definition:\nData protected by law, regulation, or industry rule.\n\nClue:\nLook for where the asset lives, what can fail, and how the design protects or restores CIA.\n\nExample:\nHealth or payment data.\n\nContrast:\nSecurity operation = daily action; architecture term = design choice that affects protection or recovery.",trick:"Exam map: Data types > Regulated"},
{cat:2,catName:"D3 Architecture",acr:"Trade secret",full:"3.3 Compare and contrast concepts and strategies to protect data.",def:"Definition:\nConfidential business information that provides competitive advantage.\n\nClue:\nLook for where the asset lives, what can fail, and how the design protects or restores CIA.\n\nExample:\nRecipe or algorithm.\n\nContrast:\nSecurity operation = daily action; architecture term = design choice that affects protection or recovery.",trick:"Exam map: Data types > Trade secret"},
{cat:2,catName:"D3 Architecture",acr:"Intellectual property",full:"3.3 Compare and contrast concepts and strategies to protect data.",def:"Definition:\nCreations such as designs, code, inventions, and content owned by an individual or organization.\n\nClue:\nLook for where the asset lives, what can fail, and how the design protects or restores CIA.\n\nExample:\nSource code or design plans.\n\nContrast:\nSecurity operation = daily action; architecture term = design choice that affects protection or recovery.",trick:"Exam map: Data types > Intellectual property"},
{cat:2,catName:"D3 Architecture",acr:"Legal information",full:"3.3 Compare and contrast concepts and strategies to protect data.",def:"Definition:\nData related to contracts, litigation, legal advice, or regulatory obligations.\n\nClue:\nLook for where the asset lives, what can fail, and how the design protects or restores CIA.\n\nExample:\nContract drafts.\n\nContrast:\nSecurity operation = daily action; architecture term = design choice that affects protection or recovery.",trick:"Exam map: Data types > Legal information"},
{cat:2,catName:"D3 Architecture",acr:"Financial information",full:"3.3 Compare and contrast concepts and strategies to protect data.",def:"Definition:\nData about money, payments, accounts, revenue, or financial transactions.\n\nClue:\nLook for where the asset lives, what can fail, and how the design protects or restores CIA.\n\nExample:\nBank account records.\n\nContrast:\nSecurity operation = daily action; architecture term = design choice that affects protection or recovery.",trick:"Exam map: Data types > Financial information"},
{cat:2,catName:"D3 Architecture",acr:"Human- and non-human-",full:"3.3 Compare and contrast concepts and strategies to protect data.",def:"Definition:\nData subject types that shape privacy and access policies. Human-readable data = data about individual people (PII, PHI, financial records) — subject to privacy regulations, individual rights (right to be forgotten, access requests). Non-human-generated data = machine logs, IoT sensor data, automated system output — may not trigger individual privacy rights but still needs classification and protection.\n\nClue:\nLook for whether data concerns individual people (human) or automated systems/machines (non-human) — different compliance and handling obligations apply.\n\nExample:\nEmployee keycard swipe logs = non-human generated (machine records system events). Employee performance review = human-readable PII data with privacy protection requirements.\n\nContrast:\nHuman data → privacy regulations, individual rights, consent. Non-human data → operational security, integrity, classification — but not personal privacy rights.",trick:"Exam map: Data types > Human- and non-human-readable"},
{cat:2,catName:"D3 Architecture",acr:"Sensitive",full:"3.3 Compare and contrast concepts and strategies to protect data.",def:"Definition:\nData that requires protection because disclosure or misuse could cause harm.\n\nClue:\nLook for where the asset lives, what can fail, and how the design protects or restores CIA.\n\nExample:\nInternal salary spreadsheet.\n\nContrast:\nSecurity operation = daily action; architecture term = design choice that affects protection or recovery.",trick:"Exam map: Data classifications > Sensitive"},
{cat:2,catName:"D3 Architecture",acr:"Confidential",full:"3.3 Compare and contrast concepts and strategies to protect data.",def:"Definition:\nData restricted to authorized parties and protected from unauthorized disclosure.\n\nClue:\nLook for where the asset lives, what can fail, and how the design protects or restores CIA.\n\nExample:\nMerger documents.\n\nContrast:\nSecurity operation = daily action; architecture term = design choice that affects protection or recovery.",trick:"Exam map: Data classifications > Confidential"},
{cat:2,catName:"D3 Architecture",acr:"Public",full:"3.3 Compare and contrast concepts and strategies to protect data.",def:"Definition:\nData approved for anyone to access.\n\nClue:\nLook for where the asset lives, what can fail, and how the design protects or restores CIA.\n\nExample:\nPublished press release.\n\nContrast:\nSecurity operation = daily action; architecture term = design choice that affects protection or recovery.",trick:"Exam map: Data classifications > Public"},
{cat:2,catName:"D3 Architecture",acr:"Restricted",full:"3.3 Compare and contrast concepts and strategies to protect data.",def:"Definition:\nData limited to specific users or groups due to sensitivity or policy.\n\nClue:\nLook for where the asset lives, what can fail, and how the design protects or restores CIA.\n\nExample:\nAdmin-only system plans.\n\nContrast:\nSecurity operation = daily action; architecture term = design choice that affects protection or recovery.",trick:"Exam map: Data classifications > Restricted"},
{cat:2,catName:"D3 Architecture",acr:"Private",full:"3.3 Compare and contrast concepts and strategies to protect data.",def:"Definition:\nPersonal or internal data that should not be broadly shared.\n\nClue:\nLook for where the asset lives, what can fail, and how the design protects or restores CIA.\n\nExample:\nEmployee home address.\n\nContrast:\nSecurity operation = daily action; architecture term = design choice that affects protection or recovery.",trick:"Exam map: Data classifications > Private"},
{cat:2,catName:"D3 Architecture",acr:"Critical",full:"3.3 Compare and contrast concepts and strategies to protect data.",def:"Definition:\nData or systems essential to business or mission operations.\n\nClue:\nLook for where the asset lives, what can fail, and how the design protects or restores CIA.\n\nExample:\nPayment processing database.\n\nContrast:\nSecurity operation = daily action; architecture term = design choice that affects protection or recovery.",trick:"Exam map: Data classifications > Critical"},
{cat:2,catName:"D3 Architecture",acr:"Data states",full:"3.3 Compare and contrast concepts and strategies to protect data.",def:"Definition:\nThe three states data can be in, each requiring different protections: Data at rest (stored on disk/media/database → encrypt with AES-256, FDE, TDE). Data in transit (moving over network → encrypt with TLS 1.2+). Data in use (actively processed in memory/CPU → access controls, trusted execution environments, memory encryption).\n\nClue:\nMatch the data state to the protection: stored = encrypt at rest; moving = TLS; in memory/being processed = in use. Exam will describe a scenario and ask which state or which control.\n\nExample:\nEncrypting hard drive with BitLocker = protecting data at rest. HTTPS between browser and server = protecting data in transit. Screen lock when leaving desk = protecting data in use.\n\nContrast:\nData at rest = static, needs encryption; Data in transit = moving, needs TLS; Data in use = active, needs access controls and process isolation.",trick:"Exam map: General data considerations > Data states"},
{cat:2,catName:"D3 Architecture",acr:"Data at rest",full:"3.3 Compare and contrast concepts and strategies to protect data.",def:"Definition:\nData stored on media, disks, databases, backups, or devices.\n\nClue:\nLook for stored data on disks, databases, backups, or devices.\n\nExample:\nFiles stored on a hard drive.\n\nContrast:\nData in transit = moving; Data in use = actively processed.",trick:"Exam map: General data considerations > Data states > Data at rest"},
{cat:2,catName:"D3 Architecture",acr:"Data in transit",full:"3.3 Compare and contrast concepts and strategies to protect data.",def:"Definition:\nData moving across a network or between systems.\n\nClue:\nLook for data moving across a network.\n\nExample:\nEmail moving across the internet.\n\nContrast:\nData at rest = stored; Data in use = actively processed.",trick:"Exam map: General data considerations > Data states > Data in transit"},
{cat:2,catName:"D3 Architecture",acr:"Data in use",full:"3.3 Compare and contrast concepts and strategies to protect data.",def:"Definition:\nData actively being processed in memory or by an application.\n\nClue:\nLook for data actively processed in memory or by an application.\n\nExample:\nRecord open in memory.\n\nContrast:\nData at rest = stored; Data in transit = moving.",trick:"Exam map: General data considerations > Data states > Data in use"},
{cat:2,catName:"D3 Architecture",acr:"Data sovereignty",full:"3.3 Compare and contrast concepts and strategies to protect data.",def:"Definition:\nRequirement that data is subject to the laws of the country or region where it is stored or processed.\n\nClue:\nLook for where the asset lives, what can fail, and how the design protects or restores CIA.\n\nExample:\nEU data stored under EU rules.\n\nContrast:\nSecurity operation = daily action; architecture term = design choice that affects protection or recovery.",trick:"Exam map: General data considerations > Data sovereignty"},
{cat:2,catName:"D3 Architecture",acr:"Geolocation",full:"3.3 Compare and contrast concepts and strategies to protect data.",def:"Definition:\nIdentifying or controlling activity based on physical or network location.\n\nClue:\nLook for where the asset lives, what can fail, and how the design protects or restores CIA.\n\nExample:\nBlock login from unexpected country.\n\nContrast:\nSecurity operation = daily action; architecture term = design choice that affects protection or recovery.",trick:"Exam map: General data considerations > Geolocation"},
{cat:2,catName:"D3 Architecture",acr:"Geographic restrictions",full:"3.3 Compare and contrast concepts and strategies to protect data.",def:"Definition:\nLimiting access or data placement based on region or country.\n\nClue:\nLook for where the asset lives, what can fail, and how the design protects or restores CIA.\n\nExample:\nBlock access outside the United States.\n\nContrast:\nSecurity operation = daily action; architecture term = design choice that affects protection or recovery.",trick:"Exam map: Methods to secure data > Geographic restrictions"},
{cat:2,catName:"D3 Architecture",acr:"Masking",full:"3.3 Compare and contrast concepts and strategies to protect data.",def:"Definition:\nReplacing sensitive data with non-sensitive substitute values that look realistic but are not real. Unlike encryption, masking cannot be reversed — the original data is gone in the masked dataset. Used to protect sensitive data in test/development environments, reports, or display. Example: SSN 123-45-6789 → XXX-XX-6789 (last 4 visible).\n\nClue:\nLook for test environments using fake-but-realistic data, or displayed data partially hidden (credit card showing only last 4 digits). If it can't be reversed, it's masking.\n\nExample:\nDevelopment team receives customer database with all SSNs replaced by fake numbers — they can build with realistic data structures without exposing real PII.\n\nContrast:\nEncryption = reversible with key; Masking = irreversible, real data replaced; Tokenization = real data stored securely, token used in its place.",trick:"Exam map: Methods to secure data > Masking"},
{cat:2,catName:"D3 Architecture",acr:"Permission restrictions",full:"3.3 Compare and contrast concepts and strategies to protect data.",def:"Definition:\nData protection method that controls who can read, write, modify, delete, or execute data. Implement via ACLs, file permissions (owner/group/other), database roles, and object-level permissions. Principle of least privilege: grant only minimum access needed. Reduces blast radius — if credentials are stolen, attacker only gets that user's permissions.\n\nClue:\nLook for controlling data access through permissions — not encryption, but access control. Who can read vs. write vs. delete?\n\nExample:\nFinancial data: CFO has read/write, auditors have read-only, developers have no access. Even if a developer account is compromised, financial data is protected.\n\nContrast:\nEncryption = protects if data is stolen; Permission restrictions = prevents unauthorized access in the first place.",trick:"Exam map: Methods to secure data > Permission restrictions"},
{cat:2,catName:"D3 Architecture",acr:"Load balancing vs. clustering",full:"3.4 Explain the importance of resilience and recovery in security architecture.",def:"Definition:\nHigh availability techniques. Load balancing = distributes incoming traffic across multiple servers to prevent overload, improve performance, and provide redundancy (if one server fails, traffic routes to others). Clustering = groups servers to act as one logical unit, sharing processing or providing automatic failover — active-active (all nodes process) or active-passive (standby takes over on failure).\n\nClue:\nLoad balancing = spreads traffic for performance and availability. Clustering = shared processing or automatic failover. Both increase availability; clustering is more about failover.\n\nExample:\nLoad balancer routes web requests across 5 web servers — if one goes down, the other 4 continue. Database cluster: primary fails → secondary automatically takes over.\n\nContrast:\nLoad balancing = distributes traffic; Clustering = failover and shared processing. Load balancers can become a single point of failure without redundancy themselves.",trick:"Exam map: High availability > Load balancing vs. clustering"},
{cat:2,catName:"D3 Architecture",acr:"Hot",full:"3.4 Explain the importance of resilience and recovery in security architecture.",def:"Definition:\nRecovery site that is fully equipped and ready to take over quickly.\n\nClue:\nLook for fastest recovery and a site that is already equipped and ready.\n\nExample:\nFully running backup site.\n\nContrast:\nWarm = partly ready; Cold = space only and slowest recovery.",trick:"Exam map: Site considerations > Hot"},
{cat:2,catName:"D3 Architecture",acr:"Cold",full:"3.4 Explain the importance of resilience and recovery in security architecture.",def:"Definition:\nRecovery site with space and basic infrastructure but little or no ready equipment.\n\nClue:\nLook for lowest cost and slowest recovery: space exists, but systems are not ready.\n\nExample:\nBuilding with power but no servers.\n\nContrast:\nHot = fastest and most expensive; Warm = partially ready.",trick:"Exam map: Site considerations > Cold"},
{cat:2,catName:"D3 Architecture",acr:"Warm",full:"3.4 Explain the importance of resilience and recovery in security architecture.",def:"Definition:\nRecovery site partially prepared with some equipment or data, between hot and cold.\n\nClue:\nLook for partial readiness: some equipment or data exists, but more setup is needed.\n\nExample:\nServers exist but data must sync.\n\nContrast:\nHot = fully ready; Cold = mostly empty and slower.",trick:"Exam map: Site considerations > Warm"},
{cat:2,catName:"D3 Architecture",acr:"Geographic dispersion",full:"3.4 Explain the importance of resilience and recovery in security architecture.",def:"Definition:\nPlacing systems or sites in different locations to reduce shared disaster risk.\n\nClue:\nLook for where the asset lives, what can fail, and how the design protects or restores CIA.\n\nExample:\nData centers in different states.\n\nContrast:\nInsecure protocol = avoid when confidentiality is needed; secure protocol = prefer for protected communication.",trick:"Exam map: Site considerations > Geographic dispersion"},
{cat:2,catName:"D3 Architecture",acr:"Platform diversity",full:"3.4 Explain the importance of resilience and recovery in security architecture.",def:"Definition:\nUsing different platforms or vendors to reduce common failure or attack impact.\n\nClue:\nLook for where the asset lives, what can fail, and how the design protects or restores CIA.\n\nExample:\nBackup on different cloud provider.\n\nContrast:\nInsecure protocol = avoid when confidentiality is needed; secure protocol = prefer for protected communication.",trick:"Exam map: 3.0 Security Architecture"},
{cat:2,catName:"D3 Architecture",acr:"Multi-cloud systems",full:"3.4 Explain the importance of resilience and recovery in security architecture.",def:"Definition:\nUsing more than one cloud provider for resilience, flexibility, or risk reduction.\n\nClue:\nLook for where the asset lives, what can fail, and how the design protects or restores CIA.\n\nExample:\nAWS plus Azure.\n\nContrast:\nInsecure protocol = avoid when confidentiality is needed; secure protocol = prefer for protected communication.",trick:"Exam map: 3.0 Security Architecture"},
{cat:2,catName:"D3 Architecture",acr:"Continuity of operations",full:"3.4 Explain the importance of resilience and recovery in security architecture.",def:"Definition:\nKeeping essential functions running during disruption.\n\nClue:\nLook for where the asset lives, what can fail, and how the design protects or restores CIA.\n\nExample:\nCall center moves to backup site.\n\nContrast:\nInsecure protocol = avoid when confidentiality is needed; secure protocol = prefer for protected communication.",trick:"Exam map: 3.0 Security Architecture"},
{cat:2,catName:"D3 Architecture",acr:"Capacity planning",full:"3.4 Explain the importance of resilience and recovery in security architecture.",def:"Definition:\nEnsuring enough people, technology, and infrastructure are available for current and future needs.\n\nClue:\nLook for where the asset lives, what can fail, and how the design protects or restores CIA.\n\nExample:\nAdd servers before peak season.\n\nContrast:\nInsecure protocol = avoid when confidentiality is needed; secure protocol = prefer for protected communication.",trick:"Exam map: 3.0 Security Architecture"},
{cat:2,catName:"D3 Architecture",acr:"People",full:"3.4 Explain the importance of resilience and recovery in security architecture.",def:"Definition:\nThe staff, skills, roles, and availability needed to support operations, continuity, response, and recovery.\n\nClue:\nLook for where the asset lives, what can fail, and how the design protects or restores CIA.\n\nExample:\nAsk what it connects and whether it is encrypted.\n\nContrast:\nInsecure protocol = avoid when confidentiality is needed; secure protocol = prefer for protected communication.",trick:"Exam map: Capacity planning > People"},
{cat:2,catName:"D3 Architecture",acr:"Technology",full:"3.4 Explain the importance of resilience and recovery in security architecture.",def:"Definition:\nThe systems, tools, platforms, and technical capabilities needed to support security and business operations.\n\nClue:\nLook for where the asset lives, what can fail, and how the design protects or restores CIA.\n\nExample:\nAsk what it connects and whether it is encrypted.\n\nContrast:\nInsecure protocol = avoid when confidentiality is needed; secure protocol = prefer for protected communication.",trick:"Exam map: Capacity planning > Technology"},
{cat:2,catName:"D3 Architecture",acr:"Infrastructure",full:"3.4 Explain the importance of resilience and recovery in security architecture.",def:"Definition:\nThe underlying networks, facilities, cloud services, servers, and platforms that support applications and data.\n\nClue:\nLook for where the asset lives, what can fail, and how the design protects or restores CIA.\n\nExample:\nAsk what it connects and whether it is encrypted.\n\nContrast:\nInsecure protocol = avoid when confidentiality is needed; secure protocol = prefer for protected communication.",trick:"Exam map: Capacity planning > Infrastructure"},
{cat:2,catName:"D3 Architecture",acr:"Tabletop exercises",full:"3.4 Explain the importance of resilience and recovery in security architecture.",def:"Definition:\nDiscussion-based test of plans using a simulated scenario.\n\nClue:\nLook for where the asset lives, what can fail, and how the design protects or restores CIA.\n\nExample:\nWalk through ransomware response.\n\nContrast:\nInsecure protocol = avoid when confidentiality is needed; secure protocol = prefer for protected communication.",trick:"Exam map: Testing > Tabletop exercises"},
{cat:2,catName:"D3 Architecture",acr:"Fail over",full:"3.4 Explain the importance of resilience and recovery in security architecture.",def:"Definition:\nMoving operations from a failed system to a backup system.\n\nClue:\nLook for where the asset lives, what can fail, and how the design protects or restores CIA.\n\nExample:\nDatabase moves to standby server.\n\nContrast:\nInsecure protocol = avoid when confidentiality is needed; secure protocol = prefer for protected communication.",trick:"Exam map: Testing > Fail over"},
{cat:2,catName:"D3 Architecture",acr:"Simulation",full:"3.4 Explain the importance of resilience and recovery in security architecture.",def:"Definition:\nPractice exercise that models a real event or incident.\n\nClue:\nLook for where the asset lives, what can fail, and how the design protects or restores CIA.\n\nExample:\nSimulated phishing campaign.\n\nContrast:\nInsecure protocol = avoid when confidentiality is needed; secure protocol = prefer for protected communication.",trick:"Exam map: Testing > Simulation"},
{cat:2,catName:"D3 Architecture",acr:"Parallel processing",full:"3.4 Explain the importance of resilience and recovery in security architecture.",def:"Definition:\nRunning old and new or primary and backup processes at the same time for testing or resilience.\n\nClue:\nLook for where the asset lives, what can fail, and how the design protects or restores CIA.\n\nExample:\nOld and new payroll systems run together.\n\nContrast:\nInsecure protocol = avoid when confidentiality is needed; secure protocol = prefer for protected communication.",trick:"Exam map: Testing > Parallel processing"},
{cat:2,catName:"D3 Architecture",acr:"Onsite/offsite",full:"3.4 Explain the importance of resilience and recovery in security architecture.",def:"Definition:\nBackup storage either at the same location or a separate location.\n\nClue:\nLook for where the asset lives, what can fail, and how the design protects or restores CIA.\n\nExample:\nLocal backup and cloud backup.\n\nContrast:\nInsecure protocol = avoid when confidentiality is needed; secure protocol = prefer for protected communication.",trick:"Exam map: Backups > Onsite/offsite"},
{cat:2,catName:"D3 Architecture",acr:"Frequency",full:"3.4 Explain the importance of resilience and recovery in security architecture.",def:"Definition:\nHow often a security activity happens, such as backups, scans, reviews, training, or testing.\n\nClue:\nLook for where the asset lives, what can fail, and how the design protects or restores CIA.\n\nExample:\nDaily backups lose less data than weekly.\n\nContrast:\nInsecure protocol = avoid when confidentiality is needed; secure protocol = prefer for protected communication.",trick:"Exam map: Backups > Frequency"},
{cat:2,catName:"D3 Architecture",acr:"Snapshots",full:"3.4 Explain the importance of resilience and recovery in security architecture.",def:"Definition:\nPoint-in-time copies of data or systems.\n\nClue:\nLook for where the asset lives, what can fail, and how the design protects or restores CIA.\n\nExample:\nVM snapshot before patching.\n\nContrast:\nInsecure protocol = avoid when confidentiality is needed; secure protocol = prefer for protected communication.",trick:"Exam map: Backups > Snapshots"},
{cat:2,catName:"D3 Architecture",acr:"Recovery",full:"3.4 Explain the importance of resilience and recovery in security architecture.",def:"Definition:\nThe process of restoring systems, services, data, or business operations after an outage, disaster, or security incident.\n\nClue:\nLook for where the asset lives, what can fail, and how the design protects or restores CIA.\n\nExample:\nRestore files from backup.\n\nContrast:\nInsecure protocol = avoid when confidentiality is needed; secure protocol = prefer for protected communication.",trick:"Exam map: Backups > Recovery"},
{cat:2,catName:"D3 Architecture",acr:"Replication",full:"3.4 Explain the importance of resilience and recovery in security architecture.",def:"Definition:\nCopying data or systems to another location or platform.\n\nClue:\nLook for where the asset lives, what can fail, and how the design protects or restores CIA.\n\nExample:\nDatabase writes to another site.\n\nContrast:\nInsecure protocol = avoid when confidentiality is needed; secure protocol = prefer for protected communication.",trick:"Exam map: Backups > Replication"},
{cat:2,catName:"D3 Architecture",acr:"Journaling",full:"3.4 Explain the importance of resilience and recovery in security architecture.",def:"Definition:\nRecording changes so data can be recovered to a consistent point.\n\nClue:\nLook for where the asset lives, what can fail, and how the design protects or restores CIA.\n\nExample:\nReplay changes after crash.\n\nContrast:\nInsecure protocol = avoid when confidentiality is needed; secure protocol = prefer for protected communication.",trick:"Exam map: Backups > Journaling"},
{cat:2,catName:"D3 Architecture",acr:"Generators",full:"3.4 Explain the importance of resilience and recovery in security architecture.",def:"Definition:\nBackup power source that can run systems during utility power loss.\n\nClue:\nLook for where the asset lives, what can fail, and how the design protects or restores CIA.\n\nExample:\nGenerator runs data center during outage.\n\nContrast:\nInsecure protocol = avoid when confidentiality is needed; secure protocol = prefer for protected communication.",trick:"Exam map: Power > Generators"},
{cat:3,catName:"D4 Operations",acr:"Secure baselines",full:"4.0 Objective topic from Security Operations",def:"Definition:\nApproved secure configuration standards used to build and maintain systems consistently.\n\nClue:\nLook for whether the control must stop, detect, fix, discourage, substitute, or limit damage.\n\nExample:\nHardened Windows image.\n\nContrast:\nThreat/vulnerability = problem; control/mitigation = defense.",trick:"Exam map: 4.0 Security Operations"},
{cat:3,catName:"D4 Operations",acr:"Establish",full:"4.0 Objective topic from Security Operations",def:"Definition:\nCreate and approve a baseline, process, or control.\n\nClue:\nLook for whether the control must stop, detect, fix, discourage, substitute, or limit damage.\n\nExample:\nDefine secure baseline.\n\nContrast:\nThreat/vulnerability = problem; control/mitigation = defense.",trick:"Exam map: Secure baselines > Establish"},
{cat:3,catName:"D4 Operations",acr:"Deploy",full:"4.0 Objective topic from Security Operations",def:"Definition:\nPut a system, baseline, or control into production use.\n\nClue:\nLook for whether the control must stop, detect, fix, discourage, substitute, or limit damage.\n\nExample:\nPush baseline to laptops.\n\nContrast:\nThreat/vulnerability = problem; control/mitigation = defense.",trick:"Exam map: Secure baselines > Deploy"},
{cat:3,catName:"D4 Operations",acr:"Maintain",full:"4.0 Objective topic from Security Operations",def:"Definition:\nKeep systems, baselines, or controls current and effective.\n\nClue:\nLook for whether the control must stop, detect, fix, discourage, substitute, or limit damage.\n\nExample:\nUpdate baseline after new guidance.\n\nContrast:\nThreat/vulnerability = problem; control/mitigation = defense.",trick:"Exam map: Secure baselines > Maintain"},
{cat:3,catName:"D4 Operations",acr:"Mobile devices",full:"4.0 Objective topic from Security Operations",def:"Definition:\nHardening mobile devices (phones, tablets): enforce screen lock with biometric/PIN, enable full-device encryption, deploy MDM for remote wipe and policy enforcement, enable jailbreak/root detection, restrict sideloading (apps from outside official stores), disable unnecessary radios (Bluetooth, NFC when not in use), certificate pinning for apps, enforce app allow lists. BYOD vs. COPE vs. CYOD affects control level.\n\nClue:\nLook for mobile hardening controls: MDM enrollment, remote wipe capability, preventing jailbreak/root, and controlling which apps can be installed.\n\nExample:\nEmployee loses MDM-enrolled phone — administrator remotely wipes all corporate data; jailbreak detection had already flagged the device as non-compliant.\n\nContrast:\nWorkstation hardening uses GPO/SCCM; Mobile hardening uses MDM. Jailbroken/rooted device bypasses OS security controls — must be detected and blocked.",trick:"Exam map: Hardening targets > Mobile devices"},
{cat:3,catName:"D4 Operations",acr:"Workstations",full:"4.0 Objective topic from Security Operations",def:"Definition:\nHardening workstations (user PCs/laptops): OS patching, AV/EDR agent, host-based firewall, full disk encryption (BitLocker/FileVault), application allow listing, disable AutoRun/AutoPlay, remove local administrator rights (standard user accounts), screen lock on idle, enable audit logging, disable unused ports (USB if policy requires), apply Group Policy security baselines.\n\nClue:\nLook for workstation hardening — the key is removing unnecessary privilege (no local admin), encrypting the disk, keeping patches current, and monitoring with an agent.\n\nExample:\nNew employee laptop: BitLocker enabled, EDR agent installed, local admin removed (standard user only), Group Policy applies screen lock and USB restrictions.\n\nContrast:\nServer hardening focuses on services and network exposure; Workstation hardening focuses on user activity, removable media, and application controls.",trick:"Exam map: Hardening targets > Workstations"},
{cat:3,catName:"D4 Operations",acr:"Switches",full:"4.0 Objective topic from Security Operations",def:"Definition:\nHardening network switches: change default credentials, disable unused ports (shutdown), enable 802.1X port authentication, enable port security (limit MAC count or specify allowed MACs), configure VLANs to segment traffic, disable CDP/LLDP on untrusted ports, enable BPDU Guard (STP protection), disable Telnet (use SSH), restrict management access by IP/VLAN, enable logging.\n\nClue:\nLook for switch hardening: unused ports disabled, 802.1X authentication, port security limiting MACs, and VLANs for segmentation. BPDU Guard prevents rogue switches.\n\nExample:\nPhysical access to switch room — hardened switch: unused ports shutdown, remaining ports run 802.1X, port security limits to one MAC per port, management only via out-of-band SSH.\n\nContrast:\nRouter hardening focuses on routing protocols and ACLs; Switch hardening focuses on port-level access control and VLAN segmentation.",trick:"Exam map: Hardening targets > Switches"},
{cat:3,catName:"D4 Operations",acr:"Routers",full:"4.0 Objective topic from Security Operations",def:"Definition:\nHardening routers: change default credentials, disable remote management from internet-facing interfaces, replace Telnet with SSH, disable HTTP management (use HTTPS), disable unnecessary services (finger, SNMP v1/v2c, CDP on untrusted interfaces), use ACLs to restrict management access by IP, enable routing protocol authentication (MD5/SHA for OSPF/BGP), enable logging to SIEM, apply firmware updates.\n\nClue:\nLook for router hardening: disabling unnecessary services, requiring SSH not Telnet, ACLs restricting who can reach management interface, and keeping firmware updated.\n\nExample:\nEdge router hardening: disable HTTP management, enable SSH only from management VLAN, apply ACL blocking external access to management ports, update to latest firmware.\n\nContrast:\nSwitch hardening = port-level access; Router hardening = routing protocol security, ACLs, and management plane protection.",trick:"Exam map: Hardening targets > Routers"},
{cat:3,catName:"D4 Operations",acr:"Cloud infrastructure",full:"4.0 Objective topic from Security Operations",def:"Definition:\nHardening cloud infrastructure: enforce IAM least privilege (no overly permissive roles), enable MFA for console/API access, enable CloudTrail/audit logging, restrict security groups (no 0.0.0.0/0 inbound), encrypt storage at rest and in transit, disable unused services, enable Config/Security Hub for drift detection, require encryption for all S3 buckets, use private subnets for sensitive workloads.\n\nClue:\nLook for cloud hardening: IAM is often the biggest risk. Overly permissive roles, public S3 buckets, and missing audit logging are the top exam scenarios.\n\nExample:\nCloud audit: finds S3 bucket public, EC2 instance has admin IAM role, CloudTrail disabled. Fix: restrict bucket, scope IAM role to minimum needed, enable CloudTrail.\n\nContrast:\nOn-premises server hardening = OS/service focus; Cloud hardening = IAM, API security, and configuration of cloud services.",trick:"Exam map: Hardening targets > Cloud infrastructure"},
{cat:3,catName:"D4 Operations",acr:"Servers",full:"4.0 Objective topic from Security Operations",def:"Definition:\nHardening servers: OS patching, disable unused services and open ports, enable host-based firewall (only allow needed ports), remove guest/default accounts, use strong authentication (MFA for admin access), enable logging (send to SIEM), implement FIM (file integrity monitoring) for critical files, apply CIS benchmark, full disk encryption for data at rest, limit who has admin/root access.\n\nClue:\nLook for server hardening: the key steps are disable unnecessary services, patch, restrict admin access, and monitor with logs and FIM.\n\nExample:\nNew web server: disable FTP and Telnet, enable SSH key-only login, remove sample web content, apply CIS Level 1 benchmark, install EDR agent, configure FIM on /etc and web root.\n\nContrast:\nWorkstation hardening focuses on user activity; Server hardening focuses on services, network exposure, and admin access control.",trick:"Exam map: Hardening targets > Servers"},
{cat:3,catName:"D4 Operations",acr:"ICS/SCADA",full:"4.0 Objective topic from Security Operations",def:"Definition:\nIndustrial Control Systems/Supervisory Control and Data Acquisition — control physical processes (power grids, water treatment, pipelines, manufacturing). Security challenges: legacy protocols without encryption/authentication, cannot tolerate downtime for patching, safety-critical (compromise = physical harm). Hardening: air-gap or strict segmentation from IT network, Purdue model for zone separation, monitor for anomalous commands, patch during planned maintenance windows only.\n\nClue:\nLook for operational technology (OT) environments where safety and availability outweigh security. Cannot patch easily — use compensating controls (network segmentation, monitoring).\n\nExample:\nWater treatment SCADA: segmented from corporate IT by industrial DMZ, all traffic monitored, vendor access via isolated jump server, no direct internet access. Stuxnet attacked similar air-gapped SCADA via USB.\n\nContrast:\nIT systems prioritize CIA in order; ICS/SCADA prioritizes availability and safety first — a patching outage can stop a production line or cause physical harm.",trick:"Exam map: Hardening targets > ICS/SCADA"},
{cat:3,catName:"D4 Operations",acr:"IoT devices",full:"4.0 Objective topic from Security Operations",def:"Definition:\nInternet of Things — network-connected embedded devices (IP cameras, smart TVs, HVAC controls, door locks, medical devices, printers). Security challenges: default passwords rarely changed, limited or no patching mechanism, run legacy OSes, often ignored in inventory. Hardening: always change default credentials, segment on isolated VLAN/network, disable unused services, monitor traffic, update firmware when available, consider network access control.\n\nClue:\nLook for IoT scenarios: smart devices connecting to corporate networks, IP cameras, or any device that isn't a traditional computer but has network access. The risk is default creds + ignored patching.\n\nExample:\nIP cameras on corporate network with default admin/admin passwords — Mirai-like botnet compromises all cameras via default creds, uses them for DDoS. Fix: isolate on IoT VLAN, change all default creds.\n\nContrast:\nTraditional IT devices = managed, patchable, in inventory; IoT = often unmanaged, hard to patch, shadow IT — require network segmentation as primary control.",trick:"Exam map: Hardening targets > IoT devices"},
{cat:3,catName:"D4 Operations",acr:"Installation considerations",full:"4.0 Objective topic from Security Operations",def:"Definition:\nSecurity factors when deploying wireless infrastructure: conduct a site survey before placement (identify coverage needs, interference sources, physical barriers), use heat maps to visualize signal strength and dead zones, select appropriate frequency (2.4 GHz = range, 5/6 GHz = speed, less interference), use WPA3 encryption, disable WPS (known vulnerability), isolate guest SSID from corporate network, position APs away from exterior walls to minimize signal leakage outside the building.\n\nClue:\nLook for wireless deployment security decisions: site survey (before install), heat maps (visualize coverage), WPA3 (secure encryption), disable WPS (insecure), guest isolation (separate VLAN). Site survey → heat map → deploy → verify coverage.\n\nExample:\nNew office wireless: site survey identifies dead zones and interference from neighboring networks, heat map guides AP placement, WPA3 Enterprise with 802.1X deployed, guest SSID isolated on separate VLAN with internet-only access.\n\nContrast:\nSite survey = planning before deployment; Heat maps = verifying coverage after deployment; WPA3 = encryption choice; 802.1X = authentication choice — all are installation considerations.",trick:"Exam map: Wireless devices > Installation considerations"},
{cat:3,catName:"D4 Operations",acr:"Site surveys",full:"4.0 Objective topic from Security Operations",def:"Definition:\nPhysical review of a location to plan wireless coverage, placement, and interference reduction.\n\nClue:\nLook for what service is being connected, whether it is encrypted, and the safer protocol choice.\n\nExample:\nCheck walls and interference.\n\nContrast:\nInsecure protocol = avoid when confidentiality is needed; secure protocol = prefer for protected communication.",trick:"Exam map: Wireless devices > Site surveys"},
{cat:3,catName:"D4 Operations",acr:"Heat maps",full:"4.0 Objective topic from Security Operations",def:"Definition:\nVisual maps showing wireless signal coverage and strength.\n\nClue:\nLook for what service is being connected, whether it is encrypted, and the safer protocol choice.\n\nExample:\nColors show weak signal areas.\n\nContrast:\nInsecure protocol = avoid when confidentiality is needed; secure protocol = prefer for protected communication.",trick:"Exam map: Wireless devices > Site surveys > Heat maps"},
{cat:3,catName:"D4 Operations",acr:"Acquisition/procurement process",full:"4.0 Objective topic from Security Operations",def:"Definition:\nFormal process for selecting and buying technology while considering security requirements.\n\nClue:\nLook for the exact scenario words and match them to the safest, most specific answer.\n\nExample:\nRequire security review before purchase.\n\nContrast:\nCompare it with nearby terms in the same objective to see why this answer fits best.",trick:"Exam map: 4.0 Security Operations"},
{cat:3,catName:"D4 Operations",acr:"Assignment/accounting",full:"4.0 Objective topic from Security Operations",def:"Definition:\nTracking who owns or is responsible for assets.\n\nClue:\nLook for the exact scenario words and match them to the safest, most specific answer.\n\nExample:\nLaptop assigned to employee ID.\n\nContrast:\nCompare it with nearby terms in the same objective to see why this answer fits best.",trick:"Exam map: 4.0 Security Operations"},
{cat:3,catName:"D4 Operations",acr:"Classification",full:"4.0 Objective topic from Security Operations",def:"Definition:\nLabeling data or assets by sensitivity, business importance, or handling requirements so the right protections are applied.\n\nClue:\nLook for the exact scenario words and match them to the safest, most specific answer.\n\nExample:\nPublic vs confidential.\n\nContrast:\nCompare it with nearby terms in the same objective to see why this answer fits best.",trick:"Exam map: Assignment/accounting > Classification"},
{cat:3,catName:"D4 Operations",acr:"Monitoring/asset tracking",full:"4.0 Objective topic from Security Operations",def:"Definition:\nContinuous tracking of organizational assets through their lifecycle. Asset tracking = knowing what exists (inventory), where it is (location/assignment), and who is responsible. Monitoring = watching asset behavior for anomalies. Together: you can't protect what you don't know you have. Techniques: CMDB, RFID, barcode scanning, MDM for mobiles, network discovery scans, and automated agent reporting.\n\nClue:\nLook for asset lifecycle management scenarios: new device intake (add to inventory), device assignment (record user), device behavior (monitoring), and device retirement (decommission tracking).\n\nExample:\nSecurity team discovers unknown server in data center during network scan — not in CMDB. Without asset tracking, shadow IT grows and creates unmanaged attack surface.\n\nContrast:\nInventory = what exists; Enumeration = discovering/listing assets; Monitoring = watching behavior over time — all three work together.",trick:"Exam map: Monitoring/asset tracking"},
{cat:3,catName:"D4 Operations",acr:"Inventory",full:"4.0 Objective topic from Security Operations",def:"Definition:\nList of assets, systems, software, or data that must be managed and protected.\n\nClue:\nLook for whether the control must stop, detect, fix, discourage, substitute, or limit damage.\n\nExample:\nList every server.\n\nContrast:\nThreat/vulnerability = problem; control/mitigation = defense.",trick:"Exam map: Monitoring/asset tracking > Inventory"},
{cat:3,catName:"D4 Operations",acr:"Enumeration",full:"4.0 Objective topic from Security Operations",def:"Definition:\nIdentifying systems, users, services, or resources in an environment.\n\nClue:\nLook for whether the control must stop, detect, fix, discourage, substitute, or limit damage.\n\nExample:\nDiscover users and services.\n\nContrast:\nThreat/vulnerability = problem; control/mitigation = defense.",trick:"Exam map: Monitoring/asset tracking > Enumeration"},
{cat:3,catName:"D4 Operations",acr:"Disposal/decommissioning",full:"4.0 Objective topic from Security Operations",def:"Definition:\nSecurely retiring systems and assets. Key steps: data sanitization (wipe/destroy data), revoke all credentials and certificates, remove from network, remove from asset inventory/CMDB, update documentation, obtain certificate of destruction (for drives), physically dispose of hardware securely. Skipping steps = data breaches from discarded drives.\n\nClue:\nLook for what must happen before disposing of hardware: data must be wiped or destroyed, credentials revoked, and disposal documented. The risk: sensitive data on disposed drives.\n\nExample:\nOld server being replaced: remove from AD domain, revoke SSL cert, securely wipe drives with DoD 5220.22-M or physically shred, get certificate of destruction, remove from inventory.\n\nContrast:\nSanitization = data removal process; Destruction = physical destruction; Certification = formal proof of disposal — all are steps within decommissioning.",trick:"Exam map: Disposal/decommissioning"},
{cat:3,catName:"D4 Operations",acr:"Sanitization",full:"4.0 Objective topic from Security Operations",def:"Definition:\nRemoving data from media so it cannot be recovered by normal methods.\n\nClue:\nLook for the exact scenario words and match them to the safest, most specific answer.\n\nExample:\nSecure erase before reuse.\n\nContrast:\nCompare it with nearby terms in the same objective to see why this answer fits best.",trick:"Exam map: Disposal/decommissioning > Sanitization"},
{cat:3,catName:"D4 Operations",acr:"Destruction",full:"4.0 Objective topic from Security Operations",def:"Definition:\nPhysically or logically destroying media so data cannot be recovered.\n\nClue:\nLook for the exact scenario words and match them to the safest, most specific answer.\n\nExample:\nShred old drives.\n\nContrast:\nCompare it with nearby terms in the same objective to see why this answer fits best.",trick:"Exam map: Disposal/decommissioning > Destruction"},
{cat:3,catName:"D4 Operations",acr:"Certification",full:"4.0 Objective topic from Security Operations",def:"Definition:\nFormal proof or attestation that a process, disposal, or control met requirements.\n\nClue:\nLook for the exact scenario words and match them to the safest, most specific answer.\n\nExample:\nCertificate of destruction.\n\nContrast:\nCompare it with nearby terms in the same objective to see why this answer fits best.",trick:"Exam map: Disposal/decommissioning > Certification"},
{cat:3,catName:"D4 Operations",acr:"Data retention",full:"4.0 Objective topic from Security Operations",def:"Definition:\nRules for how long data must be kept and when it should be deleted.\n\nClue:\nLook for where the asset lives, what can fail, and how the design protects or restores CIA.\n\nExample:\nDelete logs after policy period.\n\nContrast:\nSecurity operation = daily action; architecture term = design choice that affects protection or recovery.",trick:"Exam map: Disposal/decommissioning > Data retention"},
{cat:3,catName:"D4 Operations",acr:"Cellular",full:"4.0 Objective topic from Security Operations",def:"Definition:\nWireless connection through a mobile carrier network.\n\nClue:\nLook for what service is being connected, whether it is encrypted, and the safer protocol choice.\n\nExample:\nPhone uses 5G.\n\nContrast:\nCompare it with nearby terms in the same objective to see why this answer fits best.",trick:"Exam map: Mobile solutions > (MDM) - > Cellular"},
{cat:3,catName:"D4 Operations",acr:"Wi-Fi",full:"4.0 Objective topic from Security Operations",def:"Definition:\nWireless local networking based on IEEE 802.11 standards.\n\nClue:\nLook for what service is being connected, whether it is encrypted, and the safer protocol choice.\n\nExample:\nLaptop joins office SSID.\n\nContrast:\nCompare it with nearby terms in the same objective to see why this answer fits best.",trick:"Exam map: Mobile solutions > (MDM) - > Wi-Fi"},
{cat:3,catName:"D4 Operations",acr:"Input validation",full:"4.2 Explain the security implications of proper hardware, software, and data asset management.",def:"Definition:\nChecking user or system input before processing it to prevent malicious or invalid data.\n\nClue:\nLook for where the asset lives, what can fail, and how the design protects or restores CIA.\n\nExample:\nReject SQL in a name field.\n\nContrast:\nSecurity operation = daily action; architecture term = design choice that affects protection or recovery.",trick:"Exam map: Application security > Input validation"},
{cat:3,catName:"D4 Operations",acr:"Secure cookies",full:"4.2 Explain the security implications of proper hardware, software, and data asset management.",def:"Definition:\nCookies protected with security attributes such as Secure, HttpOnly, and SameSite.\n\nClue:\nLook for where the asset lives, what can fail, and how the design protects or restores CIA.\n\nExample:\nHttpOnly cookie blocks script access.\n\nContrast:\nSecurity operation = daily action; architecture term = design choice that affects protection or recovery.",trick:"Exam map: Application security > Secure cookies"},
{cat:3,catName:"D4 Operations",acr:"Static code analysis",full:"4.2 Explain the security implications of proper hardware, software, and data asset management.",def:"Definition:\nReviewing source code without running it to find vulnerabilities.\n\nClue:\nLook for where the asset lives, what can fail, and how the design protects or restores CIA.\n\nExample:\nScanner finds hardcoded password.\n\nContrast:\nSecurity operation = daily action; architecture term = design choice that affects protection or recovery.",trick:"Exam map: Application security > Static code analysis"},
{cat:3,catName:"D4 Operations",acr:"Code signing",full:"4.2 Explain the security implications of proper hardware, software, and data asset management.",def:"Definition:\nDigitally signing code so systems can verify publisher and integrity.\n\nClue:\nLook for where the asset lives, what can fail, and how the design protects or restores CIA.\n\nExample:\nOS trusts signed driver.\n\nContrast:\nSecurity operation = daily action; architecture term = design choice that affects protection or recovery.",trick:"Exam map: Application security > Code signing"},
{cat:3,catName:"D4 Operations",acr:"Sandboxing",full:"4.2 Explain the security implications of proper hardware, software, and data asset management.",def:"Definition:\nRunning code in an isolated environment to limit damage or observe behavior.\n\nClue:\nLook for where the asset lives, what can fail, and how the design protects or restores CIA.\n\nExample:\nBrowser tab isolated from system.\n\nContrast:\nSecurity operation = daily action; architecture term = design choice that affects protection or recovery.",trick:"Exam map: 4.0 Security Operations"},
{cat:3,catName:"D4 Operations",acr:"Vulnerability scan",full:"4.3 Explain various activities associated with vulnerability management.",def:"Definition:\nAutomated check for known vulnerabilities, missing patches, or insecure configurations.\n\nClue:\nLook for how the attack or weakness behaves, what it targets, and what reduces the damage.\n\nExample:\nNessus finds missing patch.\n\nContrast:\nMitigation/control = defense; this term describes the problem or weakness.",trick:"Exam map: Identification methods > Vulnerability scan"},
{cat:3,catName:"D4 Operations",acr:"Static analysis",full:"4.3 Explain various activities associated with vulnerability management.",def:"Definition:\nAnalyzing code without executing it.\n\nClue:\nLook for how the attack or weakness behaves, what it targets, and what reduces the damage.\n\nExample:\nReview source for unsafe function.\n\nContrast:\nMitigation/control = defense; this term describes the problem or weakness.",trick:"Exam map: Identification methods > Application security > Static analysis"},
{cat:3,catName:"D4 Operations",acr:"Dynamic analysis",full:"4.3 Explain various activities associated with vulnerability management.",def:"Definition:\nAnalyzing software while it is running.\n\nClue:\nLook for how the attack or weakness behaves, what it targets, and what reduces the damage.\n\nExample:\nRun app and test input handling.\n\nContrast:\nMitigation/control = defense; this term describes the problem or weakness.",trick:"Exam map: Identification methods > Application security > Dynamic analysis"},
{cat:3,catName:"D4 Operations",acr:"Package monitoring",full:"4.3 Explain various activities associated with vulnerability management.",def:"Definition:\nTracking third-party packages and dependencies for vulnerabilities or updates.\n\nClue:\nLook for how the attack or weakness behaves, what it targets, and what reduces the damage.\n\nExample:\nAlert when library has CVE.\n\nContrast:\nMitigation/control = defense; this term describes the problem or weakness.",trick:"Exam map: Identification methods > Application security > Package monitoring"},
{cat:3,catName:"D4 Operations",acr:"Threat feed",full:"4.3 Explain various activities associated with vulnerability management.",def:"Definition:\nStream of threat intelligence indicators or reports.\n\nClue:\nLook for how the attack or weakness behaves, what it targets, and what reduces the damage.\n\nExample:\nFeed adds malicious IPs.\n\nContrast:\nMitigation/control = defense; this term describes the problem or weakness.",trick:"Exam map: Identification methods > Threat feed"},
{cat:3,catName:"D4 Operations",acr:"Proprietary/third-party",full:"4.3 Explain various activities associated with vulnerability management.",def:"Definition:\nThreat intelligence or service provided by a commercial or external source.\n\nClue:\nLook for how the attack or weakness behaves, what it targets, and what reduces the damage.\n\nExample:\nVendor threat report.\n\nContrast:\nMitigation/control = defense; this term describes the problem or weakness.",trick:"Exam map: Identification methods > Threat feed > Proprietary/third-party"},
{cat:3,catName:"D4 Operations",acr:"Information-sharing",full:"4.3 Explain various activities associated with vulnerability management.",def:"Definition:\nSharing threat intelligence between organizations to improve collective defense. Mechanisms: ISACs (Information Sharing and Analysis Centers) for sector-specific sharing (FS-ISAC for finance, H-ISAC for healthcare), AIS (Automated Indicator Sharing by CISA), STIX/TAXII standards for structured threat data exchange. Sharing IOCs (indicators of compromise) lets defenders respond to threats seen by others.\n\nClue:\nLook for organizations sharing threat data with sector peers, government, or using automated feeds. STIX = format; TAXII = transport protocol for sharing that data.\n\nExample:\nBank shares malicious IP list with FS-ISAC — other banks automatically add these IPs to their blocklists before being targeted.\n\nContrast:\nProprietary feed = vendor-sold intelligence; ISAC = sector peer sharing; AIS = government-automated sharing. All feed into the same threat intelligence picture.",trick:"Exam map: Threat feed > Information-sharing (ISACs, AIS, STIX/TAXII)"},
{cat:3,catName:"D4 Operations",acr:"Penetration testing",full:"4.3 Explain various activities associated with vulnerability management.",def:"Definition:\nAuthorized security test that actively attempts to exploit weaknesses.\n\nClue:\nLook for how the attack or weakness behaves, what it targets, and what reduces the damage.\n\nExample:\nTester exploits weak password policy.\n\nContrast:\nMitigation/control = defense; this term describes the problem or weakness.",trick:"Exam map: Identification methods > Penetration testing"},
{cat:3,catName:"D4 Operations",acr:"Responsible disclosure program",full:"4.3 Explain various activities associated with vulnerability management.",def:"Definition:\nProcess for receiving and handling vulnerability reports ethically.\n\nClue:\nLook for how the attack or weakness behaves, what it targets, and what reduces the damage.\n\nExample:\nResearcher submits vuln to vendor.\n\nContrast:\nMitigation/control = defense; this term describes the problem or weakness.",trick:"Exam map: Identification methods > Responsible disclosure program"},
{cat:3,catName:"D4 Operations",acr:"Bug bounty program",full:"4.3 Explain various activities associated with vulnerability management.",def:"Definition:\nProgram that rewards researchers for reporting valid vulnerabilities.\n\nClue:\nLook for how the attack or weakness behaves, what it targets, and what reduces the damage.\n\nExample:\nReward for valid XSS finding.\n\nContrast:\nMitigation/control = defense; this term describes the problem or weakness.",trick:"Exam map: Identification methods > Responsible disclosure program > Bug bounty program"},
{cat:3,catName:"D4 Operations",acr:"System/process audit",full:"4.3 Explain various activities associated with vulnerability management.",def:"Definition:\nFormal review of systems or processes against requirements or standards.\n\nClue:\nLook for how the attack or weakness behaves, what it targets, and what reduces the damage.\n\nExample:\nAudit account creation steps.\n\nContrast:\nMitigation/control = defense; this term describes the problem or weakness.",trick:"Exam map: Identification methods > System/process audit"},
{cat:3,catName:"D4 Operations",acr:"Confirmation",full:"4.3 Explain various activities associated with vulnerability management.",def:"Definition:\nVerifying whether a finding is real and relevant.\n\nClue:\nLook for how the attack or weakness behaves, what it targets, and what reduces the damage.\n\nExample:\nVerify scanner alert manually.\n\nContrast:\nMitigation/control = defense; this term describes the problem or weakness.",trick:"Exam map: Analysis > Confirmation"},
{cat:3,catName:"D4 Operations",acr:"False positive",full:"4.3 Explain various activities associated with vulnerability management.",def:"Definition:\nAlert or finding that incorrectly reports a problem.\n\nClue:\nLook for how the attack or weakness behaves, what it targets, and what reduces the damage.\n\nExample:\nScanner flags safe file.\n\nContrast:\nMitigation/control = defense; this term describes the problem or weakness.",trick:"Exam map: Analysis > Confirmation > False positive"},
{cat:3,catName:"D4 Operations",acr:"False negative",full:"4.3 Explain various activities associated with vulnerability management.",def:"Definition:\nMissed problem where a tool or process incorrectly reports no issue.\n\nClue:\nLook for how the attack or weakness behaves, what it targets, and what reduces the damage.\n\nExample:\nMalware missed by antivirus.\n\nContrast:\nMitigation/control = defense; this term describes the problem or weakness.",trick:"Exam map: Analysis > Confirmation > False negative"},
{cat:3,catName:"D4 Operations",acr:"Prioritize",full:"4.3 Explain various activities associated with vulnerability management.",def:"Definition:\nRank issues by severity, exploitability, business impact, and urgency.\n\nClue:\nLook for how the attack or weakness behaves, what it targets, and what reduces the damage.\n\nExample:\nInternet-facing critical CVE before low-risk issue.\n\nContrast:\nMitigation/control = defense; this term describes the problem or weakness.",trick:"Exam map: Analysis > Prioritize"},
{cat:3,catName:"D4 Operations",acr:"Common Vulnerability Scoring",full:"4.3 Explain various activities associated with vulnerability management.",def:"Definition:\nCVSS (Common Vulnerability Scoring System) — standardized numerical system (0.0–10.0) rating vulnerability severity. Base metrics: attack vector (network/adjacent/local/physical), attack complexity, privileges required, user interaction needed, and CIA impact. Severity bands: Critical 9.0–10.0, High 7.0–8.9, Medium 4.0–6.9, Low 0.1–3.9. Used to prioritize remediation order.\n\nClue:\nLook for numerical vulnerability scoring — CVSS = the number (9.8 = critical). Higher score = patch first. A CVSS 10.0 remote code execution needs immediate action; a CVSS 2.0 local info disclosure can wait.\n\nExample:\nNessus scan finds CVE-2021-44228 (Log4Shell) with CVSS 10.0 — maximum severity, internet-exploitable, no auth needed, RCE impact. Patch immediately.\n\nContrast:\nCVE = identifies the vulnerability; CVSS = scores its severity; NVD = database combining both with remediation guidance.",trick:"Exam map: Analysis > Common Vulnerability Scoring System (CVSS)"},
{cat:3,catName:"D4 Operations",acr:"Common Vulnerability",full:"4.3 Explain various activities associated with vulnerability management.",def:"Definition:\nCVE (Common Vulnerabilities and Exposures) — standardized naming system for publicly known vulnerabilities. Format: CVE-YEAR-NUMBER (e.g., CVE-2021-44228 for Log4Shell). Maintained by MITRE. Each CVE gets a unique ID, description, and CVSS score via NVD (National Vulnerability Database). Enables consistent identification across tools and organizations.\n\nClue:\nLook for CVE-YYYY-NNNNN format identifiers in exam questions — this format = a specific documented vulnerability. NVD adds the CVSS score; MITRE maintains the CVE list.\n\nExample:\nVulnerability scanner reports CVE-2021-34527 (PrintNightmare) on a domain controller — look up NVD for CVSS score, affected versions, and Microsoft patch link.\n\nContrast:\nCVE = the identifier (what is this vulnerability?); CVSS = the severity score (how bad is it?); NVD = the database that combines both.",trick:"Exam map: Analysis > Common Vulnerabilities and Exposures (CVE)"},
{cat:3,catName:"D4 Operations",acr:"Vulnerability classification",full:"4.3 Explain various activities associated with vulnerability management.",def:"Definition:\nGrouping vulnerabilities by type, severity, affected asset, or remediation approach.\n\nClue:\nLook for how the attack or weakness behaves, what it targets, and what reduces the damage.\n\nExample:\nInjection vs misconfiguration.\n\nContrast:\nMitigation/control = defense; this term describes the problem or weakness.",trick:"Exam map: Analysis > Vulnerability classification"},
{cat:3,catName:"D4 Operations",acr:"Exposure factor",full:"4.3 Explain various activities associated with vulnerability management.",def:"Definition:\nPercentage of asset value expected to be lost from a single incident.\n\nClue:\nLook for how the attack or weakness behaves, what it targets, and what reduces the damage.\n\nExample:\nFire destroys 40% of asset value.\n\nContrast:\nMitigation/control = defense; this term describes the problem or weakness.",trick:"Exam map: Analysis > Exposure factor"},
{cat:3,catName:"D4 Operations",acr:"Environmental variables",full:"4.3 Explain various activities associated with vulnerability management.",def:"Definition:\nLocal conditions that change vulnerability risk or impact.\n\nClue:\nLook for how the attack or weakness behaves, what it targets, and what reduces the damage.\n\nExample:\nPublic server raises severity.\n\nContrast:\nMitigation/control = defense; this term describes the problem or weakness.",trick:"Exam map: Analysis > Environmental variables"},
{cat:3,catName:"D4 Operations",acr:"Industry/organizational impact",full:"4.3 Explain various activities associated with vulnerability management.",def:"Definition:\nEffect a risk or vulnerability has on the specific business or industry.\n\nClue:\nLook for how the attack or weakness behaves, what it targets, and what reduces the damage.\n\nExample:\nHospital downtime is life safety risk.\n\nContrast:\nMitigation/control = defense; this term describes the problem or weakness.",trick:"Exam map: Analysis > Industry/organizational impact"},
{cat:3,catName:"D4 Operations",acr:"Risk tolerance Vulnerability response and remediation",full:"4.3 Explain various activities associated with vulnerability management.",def:"Definition:\nTwo linked concepts: Risk tolerance = the maximum level of risk an organization will accept without requiring action. Vulnerability response and remediation = the decision of how to address a discovered vulnerability: Patch (fix it), Mitigate (reduce risk with compensating controls), Accept (live with the risk within tolerance), or Transfer (insurance/outsourcing). Response depends on risk tolerance level.\n\nClue:\nLook for vulnerability management decisions: if the risk exceeds tolerance → patch or mitigate immediately. If within tolerance → may accept or defer. Risk tolerance determines which vulnerabilities are 'urgent' vs. 'scheduled'.\n\nExample:\nOrg's risk tolerance: Critical/High CVEs must be patched within 30 days. Low/Medium within 90 days. A CVSS 9.8 vulnerability on internet-facing server exceeds tolerance → emergency patch.\n\nContrast:\nRisk appetite = strategic willingness to take risk; Risk tolerance = operational threshold for a specific risk category; Remediation = the actual fix action.",trick:"Exam map: Analysis > Risk tolerance / Vulnerability response and remediation"},
{cat:3,catName:"D4 Operations",acr:"Compensating controls",full:"4.3 Explain various activities associated with vulnerability management.",def:"Definition:\nAlternative security controls implemented when a primary control cannot be applied — typically due to legacy systems, cost, operational constraints, or vendor limitations. Must provide equivalent risk reduction. Common examples: network segmentation as compensating control for an unpatched legacy system; enhanced monitoring when MFA can't be deployed; application firewall rules to block exploitation of an unpatched vulnerability.\n\nClue:\nLook for scenarios where the proper fix can't be done — 'can't patch, legacy system, can't install agent' — the answer involves compensating controls that reduce risk another way.\n\nExample:\nLegacy medical device runs Windows XP, can't be patched or updated. Compensating control: isolate on dedicated VLAN, allow only specific traffic (medical protocol to one server), monitor all traffic.\n\nContrast:\nPrimary control = the correct fix; Compensating control = an alternative that provides equivalent protection when the primary can't be used.",trick:"Exam map: Vulnerability response > Compensating controls"},
{cat:3,catName:"D4 Operations",acr:"Exceptions and exemptions",full:"4.3 Explain various activities associated with vulnerability management.",def:"Definition:\nApproved deviations from normal policy or control requirements.\n\nClue:\nLook for how the attack or weakness behaves, what it targets, and what reduces the damage.\n\nExample:\nLegacy app gets temporary exception.\n\nContrast:\nMitigation/control = defense; this term describes the problem or weakness.",trick:"Exam map: Analysis > Exceptions and exemptions"},
{cat:3,catName:"D4 Operations",acr:"Validation of remediation",full:"4.3 Explain various activities associated with vulnerability management.",def:"Definition:\nThe process of confirming that a remediation action actually fixed a vulnerability. Critical step in the vulnerability management lifecycle — without validation, you assume the patch worked but don't know. Methods: rescanning (run the same scanner again and confirm the vulnerability is gone), audit (formal review of evidence), and verification (testing that the specific exploit no longer works).\n\nClue:\nLook for the step AFTER patching/fixing — you must confirm it worked. Rescan = scanner confirms CVE is gone. Audit = formal documented confirmation. Don't assume patching succeeded without verification.\n\nExample:\nPatch deployed for Log4Shell (CVE-2021-44228). Run Nessus scan again — if vulnerability still appears, the patch either failed, wasn't applied to all servers, or the wrong version was patched.\n\nContrast:\nRemediation = the fix action; Validation = confirming the fix worked. Both are required for proper vulnerability management closure.",trick:"Exam map: Validation of remediation"},
{cat:3,catName:"D4 Operations",acr:"Rescanning",full:"4.3 Explain various activities associated with vulnerability management.",def:"Definition:\nScanning again to verify whether a vulnerability was fixed.\n\nClue:\nLook for how the attack or weakness behaves, what it targets, and what reduces the damage.\n\nExample:\nConfirm patch removed CVE.\n\nContrast:\nMitigation/control = defense; this term describes the problem or weakness.",trick:"Exam map: Validation of remediation > Rescanning"},
{cat:3,catName:"D4 Operations",acr:"Audit",full:"4.3 Explain various activities associated with vulnerability management.",def:"Definition:\nIn validation of remediation: formal review confirming that a remediation was applied correctly and produces the expected security outcome. Auditor examines change records, patch logs, configuration settings, and may test the system to verify the vulnerability is resolved. Creates documented evidence of closure.\n\nClue:\nLook for formal verification with documentation — not just running a scanner, but reviewing the process and evidence of the fix. Audit = evidence-based confirmation.\n\nExample:\nAfter patching web servers, auditor reviews patch deployment logs, configuration files showing updated version, and scan results — documents all as remediation evidence for compliance record.\n\nContrast:\nRescanning = automated tool confirms CVE absent; Audit = formal human-reviewed evidence of remediation; Verification = testing that the fix is effective.",trick:"Exam map: Validation of remediation > Audit"},
{cat:3,catName:"D4 Operations",acr:"Verification",full:"4.3 Explain various activities associated with vulnerability management.",def:"Definition:\nConfirming that remediation or a control works as expected.\n\nClue:\nLook for how the attack or weakness behaves, what it targets, and what reduces the damage.\n\nExample:\nTest blocked port is closed.\n\nContrast:\nMitigation/control = defense; this term describes the problem or weakness.",trick:"Exam map: Validation of remediation > Verification"},
{cat:3,catName:"D4 Operations",acr:"Systems",full:"4.4 Explain security alerting",def:"Definition:\nMonitoring category: watching operating-system level activity for security indicators. System monitoring covers: process execution (what programs launched), user authentication events (successful/failed logins), privilege use (sudo, UAC elevation), service changes, scheduled task creation, registry modifications, and system call anomalies. OS-level visibility is critical because many attacks operate at this layer.\n\nClue:\nLook for monitoring that watches what the OS itself is doing — process launches, login attempts, service changes. System-level monitoring catches malware that doesn't generate network traffic.\n\nExample:\nEDR detects cmd.exe spawned from word.exe (process chain indicates macro malware). Windows Event Log ID 4624 (successful login), 4625 (failed login), 4688 (process creation).\n\nContrast:\nApplication monitoring = events within apps; System monitoring = OS-level process, login, and configuration events.",trick:"Exam map: Monitoring computing resources > Systems"},
{cat:3,catName:"D4 Operations",acr:"Applications",full:"4.4 Explain security alerting",def:"Definition:\nMonitoring category: watching application-generated events for security indicators. Application monitoring covers: authentication attempts (login success/failure, account lockouts), data access patterns, transaction anomalies, error rates (sudden spike may indicate exploitation), API call patterns, and session management events. Application logs reveal SQL injection attempts, brute force, and lateral movement within business applications.\n\nClue:\nLook for monitoring within software applications — web app logs, database query logs, authentication logs from business apps. Application-level visibility catches attacks that bypass network controls.\n\nExample:\nWeb application log shows 10,000 login attempts in one minute from one IP — classic brute force. Application monitoring alerts → block IP, investigate account lockouts.\n\nContrast:\nSystem monitoring = OS-level events; Application monitoring = events generated within software applications; Network monitoring = traffic between systems.",trick:"Exam map: Monitoring computing resources > Applications"},
{cat:3,catName:"D4 Operations",acr:"Log aggregation",full:"4.4 Explain security alerting",def:"Definition:\nCollecting logs from multiple sources into one place.\n\nClue:\nLook for the exact scenario words and match them to the safest, most specific answer.\n\nExample:\nServers send logs to SIEM.\n\nContrast:\nCompare it with nearby terms in the same objective to see why this answer fits best.",trick:"Exam map: Activities > Log aggregation"},
{cat:3,catName:"D4 Operations",acr:"Alerting",full:"4.4 Explain security alerting",def:"Definition:\nNotifying people or systems when a condition or event requires attention.\n\nClue:\nLook for the exact scenario words and match them to the safest, most specific answer.\n\nExample:\nEmail sent for admin login.\n\nContrast:\nCompare it with nearby terms in the same objective to see why this answer fits best.",trick:"Exam map: Activities > Alerting"},
{cat:3,catName:"D4 Operations",acr:"Scanning",full:"4.4 Explain security alerting",def:"Definition:\nAutomated inspection for assets, vulnerabilities, or indicators.\n\nClue:\nLook for the exact scenario words and match them to the safest, most specific answer.\n\nExample:\nNetwork scanner finds open ports.\n\nContrast:\nCompare it with nearby terms in the same objective to see why this answer fits best.",trick:"Exam map: Activities > Scanning"},
{cat:3,catName:"D4 Operations",acr:"Archiving",full:"4.4 Explain security alerting",def:"Definition:\nLong-term storage of logs, records, or evidence.\n\nClue:\nLook for the exact scenario words and match them to the safest, most specific answer.\n\nExample:\nKeep logs for compliance.\n\nContrast:\nCompare it with nearby terms in the same objective to see why this answer fits best.",trick:"Exam map: Activities > Archiving"},
{cat:3,catName:"D4 Operations",acr:"Quarantine",full:"4.4 Explain security alerting",def:"Definition:\nIsolating a file, system, or user to prevent spread or damage.\n\nClue:\nLook for whether the control must stop, detect, fix, discourage, substitute, or limit damage.\n\nExample:\nIsolate infected laptop.\n\nContrast:\nCompare it with nearby terms in the same objective to see why this answer fits best.",trick:"Exam map: Activities > Archiving > Quarantine"},
{cat:3,catName:"D4 Operations",acr:"Simple Network Management",full:"4.4 Explain security alerting",def:"Definition:\nSNMP (Simple Network Management Protocol) — protocol for monitoring and managing network devices (routers, switches, printers, servers). Versions matter enormously: SNMPv1 and v2c use plaintext community strings (weak — avoid on exam). SNMPv3 adds authentication (MD5/SHA) and encryption (DES/AES) — always prefer SNMPv3. Community string 'public' is the insecure default; change it.\n\nClue:\nOn the exam: SNMPv3 = secure (encrypted + authenticated). SNMPv1/v2c = insecure (plaintext community strings). Any question about monitoring network devices securely → SNMPv3.\n\nExample:\nNetwork team needs to monitor all switches. Using SNMPv2c with community string 'public' — attacker on the network can read full device configs. Fix: upgrade to SNMPv3 with authentication and encryption.\n\nContrast:\nSNMPv1/v2c = community strings, plaintext, insecure; SNMPv3 = authentication + encryption, secure. Same protocol family but v3 is the only acceptable version.",trick:"Exam map: Monitoring activities > SNMP (Simple Network Management Protocol)"},
{cat:3,catName:"D4 Operations",acr:"Vulnerability scanners",full:"4.4 Explain security alerting",def:"Definition:\nAutomated tools that identify known vulnerabilities, missing patches, open ports, and misconfigurations. Key distinction: Authenticated scan (scanner logs in with credentials) = finds more vulnerabilities, sees installed software versions, gets accurate results. Unauthenticated scan = external view, fewer results, may miss internal issues. Examples: Nessus, OpenVAS, Qualys, Rapid7 InsightVM. Must keep scanner updated with latest plugin signatures.\n\nClue:\nAuthenticated vs. unauthenticated is the key exam distinction. Authenticated = more complete, internal view. Unauthenticated = attacker's view, fewer results.\n\nExample:\nUnauthenticated scan of web server finds 5 vulnerabilities. Authenticated scan of same server finds 23 — including missing patches and weak configurations that only logged-in access reveals.\n\nContrast:\nPenetration testing = actively tries to exploit; Vulnerability scanning = passive identification without exploitation.",trick:"Exam map: Monitoring activities > Vulnerability scanners"},
{cat:3,catName:"D4 Operations",acr:"Alert tuning",full:"4.4 Explain security alerting",def:"Definition:\nAdjusting alert rules to reduce noise and improve useful detections.\n\nClue:\nLook for the exact scenario words and match them to the safest, most specific answer.\n\nExample:\nSuppress harmless repeated alert.\n\nContrast:\nCompare it with nearby terms in the same objective to see why this answer fits best.",trick:"Exam map: Activities > - - > Alert tuning"},
{cat:3,catName:"D4 Operations",acr:"Benchmarks",full:"4.4 Explain security alerting",def:"Definition:\nSecurity configuration standards used to compare and harden systems.\n\nClue:\nLook for the exact scenario words and match them to the safest, most specific answer.\n\nExample:\nCIS benchmark for Linux.\n\nContrast:\nCompare it with nearby terms in the same objective to see why this answer fits best.",trick:"Exam map: Activities > Benchmarks"},
{cat:3,catName:"D4 Operations",acr:"Agents/agentless",full:"4.4 Explain security alerting",def:"Definition:\nAgent-based monitoring installs software on endpoints; agentless monitoring collects data remotely.\n\nClue:\nLook for the exact scenario words and match them to the safest, most specific answer.\n\nExample:\nEDR agent vs network scan.\n\nContrast:\nCompare it with nearby terms in the same objective to see why this answer fits best.",trick:"Exam map: Activities > Agents/agentless"},
{cat:3,catName:"D4 Operations",acr:"Security information and event",full:"4.4 Explain security alerting",def:"Definition:\nSIEM (Security Information and Event Management) — central platform that aggregates logs from all sources (firewalls, endpoints, servers, apps), correlates events to detect attacks, generates alerts, provides dashboards, and stores logs for forensics and compliance. Key capabilities: log aggregation, correlation rules, alerting, dashboards, long-term retention. Examples: Splunk, Microsoft Sentinel, IBM QRadar, ArcSight.\n\nClue:\nSIEM = the central brain that sees everything across the environment. On the exam: if the scenario involves collecting logs from multiple sources and detecting patterns across them → SIEM. Alert tuning reduces false positives.\n\nExample:\nSIEM correlation rule: if same user has 5+ failed logins in 5 minutes from different IPs → alert for password spraying. Without SIEM, individual system logs wouldn't reveal the pattern.\n\nContrast:\nIDS/IPS = monitors network traffic; SIEM = aggregates all log types and correlates across sources. SOAR adds automated response to SIEM alerts.",trick:"Exam map: Monitoring activities > SIEM (Security Information and Event Management)"},
{cat:3,catName:"D4 Operations",acr:"Firewall •",full:"4.5 Given a scenario, modify enterprise capabilities to enhance security.",def:"Definition:\nControl that filters traffic based on rules, ports, protocols, applications, or identities.\n\nClue:\nLook for whether the control must stop, detect, fix, discourage, substitute, or limit damage.\n\nExample:\nBlock inbound port 3389.\n\nContrast:\nThreat/vulnerability = problem; control/mitigation = defense.",trick:"Exam map: 4.0 Security Operations"},
{cat:3,catName:"D4 Operations",acr:"Group Policy",full:"4.5 Given a scenario, modify enterprise capabilities to enhance security.",def:"Definition:\nWindows centralized configuration system for enforcing settings across users and computers.\n\nClue:\nLook for ownership, documentation, testing scope, evidence, compliance, or risk decisions.\n\nExample:\nEnforce screen lock domain-wide.\n\nContrast:\nThreat/vulnerability = problem; control/mitigation = defense.",trick:"Exam map: Firewall • > Group Policy"},
{cat:3,catName:"D4 Operations",acr:"SELinux Implementation of secure protocols",full:"4.5 Given a scenario, modify enterprise capabilities to enhance security.",def:"Definition:\nTwo linked topics: SELinux (Security-Enhanced Linux) = mandatory access control (MAC) module for Linux that enforces fine-grained access policies beyond standard Unix DAC. Processes run in confined domains — even root is restricted by policy. Implementation of secure protocols = selecting and configuring encrypted, authenticated protocols: SSH instead of Telnet, SFTP/FTPS instead of FTP, HTTPS instead of HTTP, LDAPS instead of LDAP, SNMPv3 instead of v1/v2c.\n\nClue:\nSELinux: look for Linux hardening with enforcing mode (actively enforces) vs. permissive mode (logs violations without blocking). Secure protocols: whenever a question asks which protocol to use, pick the encrypted version.\n\nExample:\nSELinux enforcing mode prevents a compromised Apache process from reading /etc/shadow even though Apache runs as root equivalent. Protocol: replace FTP with SFTP for file transfers.\n\nContrast:\nSELinux = MAC operating at OS kernel level; Host firewall = network-level filtering; Both can be on the same system for defense-in-depth.",trick:"Exam map: Enterprise controls > SELinux / Implementation of secure protocols"},
{cat:3,catName:"D4 Operations",acr:"Protocol selection",full:"4.5 Given a scenario, modify enterprise capabilities to enhance security.",def:"Definition:\nChoosing the safest and most appropriate protocol for a service or use case.\n\nClue:\nLook for whether the control must stop, detect, fix, discourage, substitute, or limit damage.\n\nExample:\nChoose SFTP instead of FTP.\n\nContrast:\nInsecure protocol = avoid when confidentiality is needed; secure protocol = prefer for protected communication.",trick:"Exam map: Firewall • > Protocol selection"},
{cat:3,catName:"D4 Operations",acr:"Port selection",full:"4.5 Given a scenario, modify enterprise capabilities to enhance security.",def:"Definition:\nChoosing or controlling network ports used by services.\n\nClue:\nLook for whether the control must stop, detect, fix, discourage, substitute, or limit damage.\n\nExample:\nAllow 443, block 23.\n\nContrast:\nInsecure protocol = avoid when confidentiality is needed; secure protocol = prefer for protected communication.",trick:"Exam map: Firewall • > Port selection"},
{cat:3,catName:"D4 Operations",acr:"Transport method",full:"4.5 Given a scenario, modify enterprise capabilities to enhance security.",def:"Definition:\nHow data is carried between systems, including whether it is encrypted or tunneled.\n\nClue:\nLook for whether the control must stop, detect, fix, discourage, substitute, or limit damage.\n\nExample:\nSend over TLS, not plaintext.\n\nContrast:\nInsecure protocol = avoid when confidentiality is needed; secure protocol = prefer for protected communication.",trick:"Exam map: Firewall • > Transport method"},
{cat:3,catName:"D4 Operations",acr:"Domain-based Message",full:"4.5 Given a scenario, modify enterprise capabilities to enhance security.",def:"Definition:\nDMARC (Domain-based Message Authentication, Reporting, and Conformance) — email authentication policy that builds on SPF and DKIM to tell receiving mail servers what to do with messages that fail authentication (none/quarantine/reject). Prevents email spoofing and phishing from your domain. Also provides reporting on who is sending email using your domain.\n\nClue:\nEmail security trio to memorize: SPF = authorized sending IPs; DKIM = cryptographic signature; DMARC = policy (what to do on failure) + reporting. DMARC requires both SPF and DKIM to work.\n\nExample:\nDMARC policy 'p=reject': if email claiming to be from company.com fails SPF and DKIM, receiving server rejects it outright — phishing emails spoofing your domain never reach the inbox.\n\nContrast:\nSPF = IP-based sender authorization; DKIM = cryptographic signature on messages; DMARC = enforcement policy and reporting layer that uses both SPF and DKIM results.",trick:"Exam map: Email security > DMARC (Domain-based Message Authentication, Reporting, and Conformance)"},
{cat:3,catName:"D4 Operations",acr:"Gateway",full:"4.5 Given a scenario, modify enterprise capabilities to enhance security.",def:"Definition:\nSecurity or network point that traffic passes through for inspection or routing.\n\nClue:\nLook for whether the control must stop, detect, fix, discourage, substitute, or limit damage.\n\nExample:\nEmail gateway scans attachments.\n\nContrast:\nThreat/vulnerability = problem; control/mitigation = defense.",trick:"Exam map: Firewall • > Gateway"},
{cat:3,catName:"D4 Operations",acr:"File integrity monitoring",full:"4.5 Given a scenario, modify enterprise capabilities to enhance security.",def:"Definition:\nFIM (File Integrity Monitoring) — continuously calculates and compares cryptographic hashes of critical files (OS binaries, config files, web content, registry keys) against known-good baselines. Alerts when any monitored file is added, modified, or deleted unexpectedly. Key PCI DSS requirement. Tools: Tripwire, AIDE, Windows SFC, many SIEM/EDR platforms.\n\nClue:\nLook for detecting unauthorized changes to critical files — FIM = the control. A changed system file when no maintenance was scheduled = IOC. FIM catches rootkits, web shells, config tampering.\n\nExample:\nFIM detects /etc/passwd modified at 2 AM with no change ticket. Investigation reveals attacker added a backdoor account. Without FIM, the change would have been invisible.\n\nContrast:\nAV/EDR = looks for malicious code behavior; FIM = looks for unauthorized changes to specific files regardless of how the change was made.",trick:"Exam map: Enterprise controls > File Integrity Monitoring (FIM)"},
{cat:3,catName:"D4 Operations",acr:"User behavior analytics",full:"4.5 Given a scenario, modify enterprise capabilities to enhance security.",def:"Definition:\nAnalyzing normal user behavior to detect suspicious deviations.\n\nClue:\nLook for the exact scenario words and match them to the safest, most specific answer.\n\nExample:\nUser downloads 10,000 files at midnight.\n\nContrast:\nCompare it with nearby terms in the same objective to see why this answer fits best.",trick:"Exam map: 4.0 Security Operations"},
{cat:3,catName:"D4 Operations",acr:"Rules",full:"4.5 Given a scenario, modify enterprise capabilities to enhance security.",def:"Definition:\nSpecific logic that tells a security tool what to allow, block, alert on, or enforce.\n\nClue:\nLook for the exact scenario words and match them to the safest, most specific answer.\n\nExample:\nDeny traffic from bad IP.\n\nContrast:\nCompare it with nearby terms in the same objective to see why this answer fits best.",trick:"Exam map: User behavior analytics > Rules"},
{cat:3,catName:"D4 Operations",acr:"Access lists",full:"4.5 Given a scenario, modify enterprise capabilities to enhance security.",def:"Definition:\nOrdered rules that permit or deny traffic or access.\n\nClue:\nLook for proving identity, assigning access, limiting privileges, or removing access.\n\nExample:\nACL permits web traffic only.\n\nContrast:\nAuthentication proves identity; authorization decides access.",trick:"Exam map: User behavior analytics > Access lists"},
{cat:3,catName:"D4 Operations",acr:"Ports/protocols",full:"4.5 Given a scenario, modify enterprise capabilities to enhance security.",def:"Definition:\nNetwork ports identify services; protocols define how communication works.\n\nClue:\nLook for what service is being connected, whether it is encrypted, and the safer protocol choice.\n\nExample:\nHTTPS uses TCP 443.\n\nContrast:\nInsecure protocol = avoid when confidentiality is needed; secure protocol = prefer for protected communication.",trick:"Exam map: User behavior analytics > Ports/protocols"},
{cat:3,catName:"D4 Operations",acr:"Screened subnets",full:"4.5 Given a scenario, modify enterprise capabilities to enhance security.",def:"Definition:\nSubnet placed between internal and external networks to host exposed services with added filtering.\n\nClue:\nLook for the exact scenario words and match them to the safest, most specific answer.\n\nExample:\nDMZ hosts web server.\n\nContrast:\nCompare it with nearby terms in the same objective to see why this answer fits best.",trick:"Exam map: User behavior analytics > Screened subnets"},
{cat:3,catName:"D4 Operations",acr:"IDS/IPS",full:"4.5 Given a scenario, modify enterprise capabilities to enhance security.",def:"Definition:\nIDS = Intrusion Detection System: monitors and alerts but does NOT block (passive/detective). IPS = Intrusion Prevention System: monitors AND actively blocks (inline/preventive). NIDS/NIPS = network-based (monitors traffic). HIDS/HIPS = host-based (monitors a specific endpoint). Detection methods: Signature-based (matches known attack patterns, low false positives, misses zero-days) vs. Anomaly-based (deviates from baseline, catches new attacks but higher false positives).\n\nClue:\nIDS = detect only (alerts); IPS = detect and block. Signature = known threats. Anomaly = behavioral baseline. Inline placement required for IPS to block. Network-based sees all traffic; Host-based sees one device.\n\nExample:\nIDS in tap mode alerts SOC about port scan. IPS inline blocks the scan before it reaches targets. HIDS on server detects privilege escalation attempt on the host itself.\n\nContrast:\nIDS passive (alerts only); IPS active (blocks). Signature = known attacks; Anomaly = behavioral deviation. NIDS/NIPS = network visibility; HIDS/HIPS = host-level visibility.",trick:"Exam map: Enterprise controls > IDS/IPS"},
{cat:3,catName:"D4 Operations",acr:"Trends",full:"4.5 Given a scenario, modify enterprise capabilities to enhance security.",def:"Definition:\nPatterns over time that help identify abnormal or increasing activity.\n\nClue:\nLook for the exact scenario words and match them to the safest, most specific answer.\n\nExample:\nFailed logins rising all week.\n\nContrast:\nCompare it with nearby terms in the same objective to see why this answer fits best.",trick:"Exam map: IDS/IPS > Trends"},
{cat:3,catName:"D4 Operations",acr:"Signatures",full:"4.5 Given a scenario, modify enterprise capabilities to enhance security.",def:"Definition:\nKnown patterns used to detect malware, attacks, or suspicious traffic.\n\nClue:\nLook for the exact scenario words and match them to the safest, most specific answer.\n\nExample:\nIDS detects malware string.\n\nContrast:\nCompare it with nearby terms in the same objective to see why this answer fits best.",trick:"Exam map: IDS/IPS > Signatures"},
{cat:3,catName:"D4 Operations",acr:"Web filter",full:"4.5 Given a scenario, modify enterprise capabilities to enhance security.",def:"Definition:\nControl that blocks or allows web access based on URL, content, category, or reputation.\n\nClue:\nLook for whether the control must stop, detect, fix, discourage, substitute, or limit damage.\n\nExample:\nBlock gambling sites.\n\nContrast:\nThreat/vulnerability = problem; control/mitigation = defense.",trick:"Exam map: 4.0 Security Operations"},
{cat:3,catName:"D4 Operations",acr:"Agent-based",full:"4.5 Given a scenario, modify enterprise capabilities to enhance security.",def:"Definition:\nTool model that installs software on the endpoint being managed or monitored.\n\nClue:\nLook for whether the control must stop, detect, fix, discourage, substitute, or limit damage.\n\nExample:\nEDR agent on laptop.\n\nContrast:\nThreat/vulnerability = problem; control/mitigation = defense.",trick:"Exam map: Web filter > Agent-based"},
{cat:3,catName:"D4 Operations",acr:"Centralized proxy",full:"4.5 Given a scenario, modify enterprise capabilities to enhance security.",def:"Definition:\nProxy architecture where web traffic is routed through a central inspection point.\n\nClue:\nLook for whether the control must stop, detect, fix, discourage, substitute, or limit damage.\n\nExample:\nAll web traffic through proxy.\n\nContrast:\nThreat/vulnerability = problem; control/mitigation = defense.",trick:"Exam map: Web filter > Centralized proxy"},
{cat:3,catName:"D4 Operations",acr:"Content categorization",full:"4.5 Given a scenario, modify enterprise capabilities to enhance security.",def:"Definition:\nClassifying websites or content into categories for filtering decisions.\n\nClue:\nLook for whether the control must stop, detect, fix, discourage, substitute, or limit damage.\n\nExample:\nSocial media category blocked.\n\nContrast:\nThreat/vulnerability = problem; control/mitigation = defense.",trick:"Exam map: Web filter > Content categorization"},
{cat:3,catName:"D4 Operations",acr:"Block rules",full:"4.5 Given a scenario, modify enterprise capabilities to enhance security.",def:"Definition:\nRules that deny access, traffic, or actions matching defined criteria.\n\nClue:\nLook for whether the control must stop, detect, fix, discourage, substitute, or limit damage.\n\nExample:\nDeny traffic to malicious domain.\n\nContrast:\nThreat/vulnerability = problem; control/mitigation = defense.",trick:"Exam map: Web filter > Block rules"},
{cat:3,catName:"D4 Operations",acr:"Reputation",full:"4.5 Given a scenario, modify enterprise capabilities to enhance security.",def:"Definition:\nTrust score based on history, behavior, or intelligence about an IP, domain, file, or sender.\n\nClue:\nLook for whether the control must stop, detect, fix, discourage, substitute, or limit damage.\n\nExample:\nBad IP reputation blocks email.\n\nContrast:\nThreat/vulnerability = problem; control/mitigation = defense.",trick:"Exam map: Web filter > Reputation"},
{cat:3,catName:"D4 Operations",acr:"Provisioning/de-provisioning user accounts",full:"4.6 Given a scenario, implement and maintain identity and access management.",def:"Definition:\nCreating, modifying, disabling, or deleting accounts as users join, change roles, or leave.\n\nClue:\nLook for proving identity, assigning access, limiting privileges, or removing access.\n\nExample:\nDisable account on termination.\n\nContrast:\nAuthentication proves identity; authorization decides access.",trick:"Exam map: 4.0 Security Operations"},
{cat:3,catName:"D4 Operations",acr:"Permission assignments and implications",full:"4.6 Given a scenario, implement and maintain identity and access management.",def:"Definition:\nGranting access rights and understanding the security impact of those rights.\n\nClue:\nLook for proving identity, assigning access, limiting privileges, or removing access.\n\nExample:\nWrite permission can change records.\n\nContrast:\nAuthentication proves identity; authorization decides access.",trick:"Exam map: 4.0 Security Operations"},
{cat:3,catName:"D4 Operations",acr:"Identity proofing",full:"4.6 Given a scenario, implement and maintain identity and access management.",def:"Definition:\nVerifying that a person is who they claim before issuing credentials.\n\nClue:\nLook for proving identity, assigning access, limiting privileges, or removing access.\n\nExample:\nCheck ID before issuing badge.\n\nContrast:\nAuthentication proves identity; authorization decides access.",trick:"Exam map: 4.0 Security Operations"},
{cat:3,catName:"D4 Operations",acr:"Federation",full:"4.6 Given a scenario, implement and maintain identity and access management.",def:"Definition:\nTrust relationship that lets identities from one organization or provider access resources in another.\n\nClue:\nLook for one trusted identity provider giving access to other systems.\n\nExample:\nSign in with company SSO to a vendor app.\n\nContrast:\nSSO = one login experience; Federation = trust across identity providers or organizations.",trick:"Exam map: 4.0 Security Operations"},
{cat:3,catName:"D4 Operations",acr:"Security Assertions Markup",full:"4.6 Given a scenario, implement and maintain identity and access management.",def:"Definition:\nSAML (Security Assertion Markup Language) — XML-based open standard for SSO authentication. Three roles: Identity Provider (IdP, authenticates users and issues SAML assertions), Service Provider (SP, application that trusts the IdP), User/Subject. User authenticates to IdP → IdP sends signed XML assertion to SP → SP grants access. Browser-based SSO. Common in enterprise federation (e.g., corporate IdP to cloud apps).\n\nClue:\nSAML = enterprise SSO, browser-based, XML assertions. Remember the flow: user → IdP (authenticate) → SP (access granted). Exam will ask when to use SAML vs. OAuth/OIDC: SAML = authentication/SSO; OAuth/OIDC = API authorization/modern apps.\n\nExample:\nEmployee visits Salesforce → redirected to corporate IdP login → authenticates with MFA → IdP sends signed SAML assertion to Salesforce → Salesforce grants access without a separate Salesforce password.\n\nContrast:\nSAML = XML-based, enterprise SSO, authentication focused; OAuth 2.0 = token-based, API authorization, modern apps; OIDC = OAuth + authentication layer.",trick:"Exam map: SSO > SAML (Security Assertion Markup Language)"},
{cat:3,catName:"D4 Operations",acr:"Interoperability",full:"4.6 Given a scenario, implement and maintain identity and access management.",def:"Definition:\nAbility of systems, tools, or identity providers to work together.\n\nClue:\nLook for proving identity, assigning access, limiting privileges, or removing access.\n\nExample:\nSAML works across apps.\n\nContrast:\nAuthentication proves identity; authorization decides access.",trick:"Exam map: 4.0 Security Operations"},
{cat:3,catName:"D4 Operations",acr:"Attestation",full:"4.6 Given a scenario, implement and maintain identity and access management.",def:"Definition:\nFormal confirmation that something is true, compliant, or reviewed.\n\nClue:\nLook for proving identity, assigning access, limiting privileges, or removing access.\n\nExample:\nManager confirms access review.\n\nContrast:\nAuthentication proves identity; authorization decides access.",trick:"Exam map: 4.0 Security Operations"},
{cat:3,catName:"D4 Operations",acr:"Access controls",full:"4.6 Given a scenario, implement and maintain identity and access management.",def:"Definition:\nCategory covering models that determine how access to resources is granted. Models: MAC (Mandatory) = system enforces labels, user cannot change — used in classified environments. DAC (Discretionary) = owner decides who gets access. RBAC (Role-based) = access based on job role. ABAC (Attribute-based) = access based on user/resource attributes. Rule-based = access based on rules like time-of-day or location.\n\nClue:\nMatch the scenario to the model: classified labels = MAC; file owner shares = DAC; job title determines access = RBAC; department + device type + location = ABAC; only 9-5 access = Rule-based.\n\nExample:\nTop Secret clearance with SCI compartment labels on documents = MAC. User shares folder with a colleague = DAC. HR role gets HR system access = RBAC.\n\nContrast:\nMAC = most restrictive, system-enforced; DAC = flexible, owner-controlled; RBAC = scalable for large orgs; ABAC = most granular and flexible but complex.",trick:"Exam map: Identity and access management > Access control models"},
{cat:3,catName:"D4 Operations",acr:"Mandatory",full:"4.6 Given a scenario, implement and maintain identity and access management.",def:"Definition:\nAccess control where the system enforces labels and users cannot change permissions.\n\nClue:\nLook for proving identity, assigning access, limiting privileges, or removing access.\n\nExample:\nClassified labels control files.\n\nContrast:\nThreat/vulnerability = problem; control/mitigation = defense.",trick:"Exam map: Access controls > Mandatory"},
{cat:3,catName:"D4 Operations",acr:"Discretionary",full:"4.6 Given a scenario, implement and maintain identity and access management.",def:"Definition:\nAccess control where resource owners can decide who gets access.\n\nClue:\nLook for proving identity, assigning access, limiting privileges, or removing access.\n\nExample:\nFile owner shares folder.\n\nContrast:\nThreat/vulnerability = problem; control/mitigation = defense.",trick:"Exam map: Access controls > Discretionary"},
{cat:3,catName:"D4 Operations",acr:"Role-based",full:"4.6 Given a scenario, implement and maintain identity and access management.",def:"Definition:\nAccess control based on job role or function.\n\nClue:\nLook for proving identity, assigning access, limiting privileges, or removing access.\n\nExample:\nHR role gets HR app.\n\nContrast:\nThreat/vulnerability = problem; control/mitigation = defense.",trick:"Exam map: Access controls > Role-based"},
{cat:3,catName:"D4 Operations",acr:"Rule-based",full:"4.6 Given a scenario, implement and maintain identity and access management.",def:"Definition:\nAccess control based on rules such as time, location, or conditions.\n\nClue:\nLook for proving identity, assigning access, limiting privileges, or removing access.\n\nExample:\nLogin allowed only 8 AM to 6 PM.\n\nContrast:\nThreat/vulnerability = problem; control/mitigation = defense.",trick:"Exam map: Access controls > Rule-based"},
{cat:3,catName:"D4 Operations",acr:"Attribute-based",full:"4.6 Given a scenario, implement and maintain identity and access management.",def:"Definition:\nAccess control based on attributes of users, resources, actions, and environment.\n\nClue:\nLook for proving identity, assigning access, limiting privileges, or removing access.\n\nExample:\nDepartment + device + location.\n\nContrast:\nThreat/vulnerability = problem; control/mitigation = defense.",trick:"Exam map: Access controls > Attribute-based"},
{cat:3,catName:"D4 Operations",acr:"Time-of-day restrictions",full:"4.6 Given a scenario, implement and maintain identity and access management.",def:"Definition:\nAccess control that allows or denies access based on time.\n\nClue:\nLook for proving identity, assigning access, limiting privileges, or removing access.\n\nExample:\nContractor login only during business hours.\n\nContrast:\nThreat/vulnerability = problem; control/mitigation = defense.",trick:"Exam map: Access controls > Time-of-day restrictions"},
{cat:3,catName:"D4 Operations",acr:"Least privilege Multifactor authentication",full:"4.6 Given a scenario, implement and maintain identity and access management.",def:"Definition:\nTwo foundational IAM controls: Least privilege = grant only the minimum permissions necessary for a task — reduces blast radius if account is compromised. MFA (Multifactor Authentication) = require two or more factors from different categories (something you know + something you have + something you are) — prevents account takeover even when password is stolen.\n\nClue:\nLeast privilege + MFA together = the two most important access controls on the exam. Least privilege limits damage from a breach; MFA prevents the breach in the first place.\n\nExample:\nAdmin account: MFA required at login (MFA prevents unauthorized use) + role limited to only the systems that admin manages (least privilege limits damage if admin is compromised).\n\nContrast:\nLeast privilege = authorization control (limits what you can do); MFA = authentication control (verifies who you are). Both are needed — MFA without least privilege still allows over-privileged access.",trick:"Exam map: IAM > Least privilege / Multifactor authentication (MFA)"},
{cat:3,catName:"D4 Operations",acr:"Somewhere you are Password concepts",full:"4.6 Given a scenario, implement and maintain identity and access management.",def:"Definition:\nTwo linked topics: 'Somewhere you are' = location-based authentication factor using geolocation, IP address, or GPS to verify the user's location matches expected patterns — can restrict access to specific countries or offices. Password concepts = the foundational knowledge for creating and managing passwords securely: length (longer = stronger), complexity, no reuse, expiration policy, and password managers.\n\nClue:\n'Somewhere you are' is the fourth MFA factor type (alongside know/have/are). Password concepts: on the exam, NIST 800-63B guidance now discourages forced rotation (unless breached) and emphasizes length over complexity.\n\nExample:\nBank blocks login from Russia if user's account is only used in the US ('somewhere you are'). Password policy: 16+ chars minimum, checked against breach databases, no mandatory rotation.\n\nContrast:\nSomewhere you are = location factor; Something you are = biometric factor; Something you know = password; Something you have = token.",trick:"Exam map: Authentication > Somewhere you are / Password concepts"},
{cat:3,catName:"D4 Operations",acr:"Password best practices",full:"4.6 Given a scenario, implement and maintain identity and access management.",def:"Definition:\nGuidelines for creating, storing, rotating, and protecting passwords safely.\n\nClue:\nLook for proving identity, assigning access, limiting privileges, or removing access.\n\nExample:\n16-character password in manager.\n\nContrast:\nThreat/vulnerability = problem; control/mitigation = defense.",trick:"Exam map: Access controls > Password best practices"},
{cat:3,catName:"D4 Operations",acr:"Length",full:"4.6 Given a scenario, implement and maintain identity and access management.",def:"Definition:\nPassword length is the most impactful factor for password strength. Each additional character multiplies the brute-force search space exponentially. NIST 800-63B recommends minimum 8 characters for user-chosen, but 12-16+ is best practice. Passphrases (multiple words) achieve length with memorability. Long passwords defeat brute-force faster than complexity requirements alone.\n\nClue:\nOn the exam, length beats complexity. 'correct-horse-battery-staple' (28 chars, all lowercase) is vastly stronger than 'P@ssw0rd' (8 chars, 'complex'). Modern guidance: length first, complexity second.\n\nExample:\nA 16-character lowercase passphrase takes billions of years to brute-force; an 8-character 'complex' password (uppercase + number + symbol) can be cracked in hours with a GPU.\n\nContrast:\nLength = exponential strength increase; Complexity = linear strength increase. Length matters more for brute-force resistance.",trick:"Exam map: Password best practices > Length"},
{cat:3,catName:"D4 Operations",acr:"Complexity",full:"4.6 Given a scenario, implement and maintain identity and access management.",def:"Definition:\nAdded difficulty in understanding, operating, or securing a system.\n\nClue:\nLook for proving identity, assigning access, limiting privileges, or removing access.\n\nExample:\nHard-to-manage automation chain.\n\nContrast:\nThreat/vulnerability = problem; control/mitigation = defense.",trick:"Exam map: Access controls > Password best practices > Complexity"},
{cat:3,catName:"D4 Operations",acr:"Reuse",full:"4.6 Given a scenario, implement and maintain identity and access management.",def:"Definition:\nPassword reuse = using the same password across multiple accounts. Critical security risk: when one site is breached, attackers take those credentials and try them against banks, email, and work accounts (credential stuffing). Policy: prevent reuse of previous N passwords (password history). Solution: unique password for every account, stored in a password manager.\n\nClue:\nLook for credential stuffing attacks (automated use of leaked credentials) — they only work because of password reuse. Password history enforcement prevents recycling.\n\nExample:\nUser reuses work password for a gaming site. Gaming site breached. Attacker uses credential stuffing with leaked gaming credentials → logs into work VPN with same password.\n\nContrast:\nPassword reuse risk = defeated by credential stuffing; Password manager = solution enabling unique passwords for every account without memorization burden.",trick:"Exam map: Password best practices > Reuse"},
{cat:3,catName:"D4 Operations",acr:"Expiration",full:"4.6 Given a scenario, implement and maintain identity and access management.",def:"Definition:\nPassword expiration = forcing users to change passwords after a set period. Traditional policy: change every 90 days. Modern NIST 800-63B guidance: don't force regular rotation unless there's evidence of compromise — frequent forced changes lead to predictable patterns (adding a number, e.g., Password1 → Password2). Instead: monitor for breached passwords and force change only when compromise is detected.\n\nClue:\nExam question: NIST recommends against mandatory password expiration unless compromise suspected. Traditional orgs may still use 90-day cycles. Recognize both — and know NIST's current guidance favors breach-triggered changes.\n\nExample:\nOld policy: change password every 90 days → users set Password_Q1, Password_Q2, etc. (predictable). NIST approach: long passphrase, no expiration unless in breach database.\n\nContrast:\nAge = how long a password has existed; Expiration = when a password must be changed; History = how many previous passwords are blocked from reuse.",trick:"Exam map: Password best practices > Expiration"},
{cat:3,catName:"D4 Operations",acr:"Age",full:"4.6 Given a scenario, implement and maintain identity and access management.",def:"Definition:\nPassword age settings control two things: Minimum age = how many days before a user can change their password again (prevents immediate reuse to bypass password history — user can't change 24 times in a row to get back to the original). Maximum age = maximum days before the password must be changed (expiration window). Both work together with password history to enforce proper rotation.\n\nClue:\nMinimum age prevents history bypass (can't cycle through 24 passwords in one day). Maximum age enforces expiration. Remember: NIST now discourages forced maximum age unless compromise is detected.\n\nExample:\nPolicy: minimum age 1 day, maximum age 90 days, history 12 passwords. User tries to immediately cycle through 12 passwords to reuse old password — blocked by minimum age (must wait 1 day per change).\n\nContrast:\nMinimum age = prevents too-frequent changes (history bypass); Maximum age = expiration deadline; History = how many previous passwords are blocked.",trick:"Exam map: Password best practices > Age (minimum/maximum)"},
{cat:3,catName:"D4 Operations",acr:"Password managers",full:"4.6 Given a scenario, implement and maintain identity and access management.",def:"Definition:\nTools that store and generate strong unique passwords.\n\nClue:\nLook for proving identity, assigning access, limiting privileges, or removing access.\n\nExample:\nOne strong master password.\n\nContrast:\nThreat/vulnerability = problem; control/mitigation = defense.",trick:"Exam map: Access controls > Password managers"},
{cat:3,catName:"D4 Operations",acr:"Passwordless",full:"4.6 Given a scenario, implement and maintain identity and access management.",def:"Definition:\nAuthentication method that avoids passwords, often using biometrics, keys, or trusted devices.\n\nClue:\nLook for login without typing a password.\n\nExample:\nSecurity key login.\n\nContrast:\nMFA may still use a password; Passwordless removes the password factor.",trick:"Exam map: Access controls > Passwordless"},
{cat:3,catName:"D4 Operations",acr:"Just-in-time permissions",full:"4.6 Given a scenario, implement and maintain identity and access management.",def:"Definition:\nTemporary privilege granted only when needed and removed afterward.\n\nClue:\nLook for temporary elevated access granted only when needed.\n\nExample:\n30-minute privileged access.\n\nContrast:\nThreat/vulnerability = problem; control/mitigation = defense.",trick:"Exam map: Access controls > Just-in-time permissions"},
{cat:3,catName:"D4 Operations",acr:"Password vaulting",full:"4.6 Given a scenario, implement and maintain identity and access management.",def:"Definition:\nSecure storage and controlled checkout of privileged passwords.\n\nClue:\nLook for proving identity, assigning access, limiting privileges, or removing access.\n\nExample:\nCheck out root password.\n\nContrast:\nThreat/vulnerability = problem; control/mitigation = defense.",trick:"Exam map: Access controls > Password vaulting"},
{cat:3,catName:"D4 Operations",acr:"Ephemeral credentials",full:"4.6 Given a scenario, implement and maintain identity and access management.",def:"Definition:\nShort-lived credentials that expire automatically.\n\nClue:\nLook for proving identity, assigning access, limiting privileges, or removing access.\n\nExample:\nTemporary cloud token.\n\nContrast:\nThreat/vulnerability = problem; control/mitigation = defense.",trick:"Exam map: Access controls > Ephemeral credentials"},
{cat:3,catName:"D4 Operations",acr:"Biometrics",full:"4.6 Given a scenario, implement and maintain identity and access management.",def:"Definition:\nAuthentication using physical or behavioral traits such as fingerprint, face, or voice.\n\nClue:\nLook for fingerprint, face, iris, voice, or body-based authentication.\n\nExample:\nFingerprint unlock.\n\nContrast:\nSomething you know = password; Biometrics = something you are.",trick:"Exam map: Access controls > Ephemeral credentials > Biometrics"},
{cat:3,catName:"D4 Operations",acr:"Hard/soft authentication",full:"4.6 Given a scenario, implement and maintain identity and access management.",def:"Definition:\nHardware tokens are physical devices; software tokens are apps or software-based authenticators.\n\nClue:\nLook for proving identity, assigning access, limiting privileges, or removing access.\n\nExample:\nYubiKey vs authenticator app.\n\nContrast:\nThreat/vulnerability = problem; control/mitigation = defense.",trick:"Exam map: Access controls > Ephemeral credentials > Hard/soft authentication"},
{cat:3,catName:"D4 Operations",acr:"Something you know",full:"4.6 Given a scenario, implement and maintain identity and access management.",def:"Definition:\nAuthentication factor based on knowledge, such as a password or PIN.\n\nClue:\nLook for proving identity, assigning access, limiting privileges, or removing access.\n\nExample:\nPassword.\n\nContrast:\nThreat/vulnerability = problem; control/mitigation = defense.",trick:"Exam map: Access controls > Ephemeral credentials > Something you know"},
{cat:3,catName:"D4 Operations",acr:"Something you have",full:"4.6 Given a scenario, implement and maintain identity and access management.",def:"Definition:\nAuthentication factor based on possession, such as a token, smart card, or phone.\n\nClue:\nLook for proving identity, assigning access, limiting privileges, or removing access.\n\nExample:\nPhone or token.\n\nContrast:\nThreat/vulnerability = problem; control/mitigation = defense.",trick:"Exam map: Access controls > Ephemeral credentials > Something you have"},
{cat:3,catName:"D4 Operations",acr:"Something you are",full:"4.6 Given a scenario, implement and maintain identity and access management.",def:"Definition:\nAuthentication factor based on biometric traits.\n\nClue:\nLook for proving identity, assigning access, limiting privileges, or removing access.\n\nExample:\nFace scan.\n\nContrast:\nThreat/vulnerability = problem; control/mitigation = defense.",trick:"Exam map: Access controls > Ephemeral credentials > Something you are"},
{cat:3,catName:"D4 Operations",acr:"Use cases of automation and scripting",full:"4.7 Explain the importance to secure operations.",def:"Definition:\nCategory covering how automation and scripting improve security operations. Key use cases: user/resource provisioning, guard rails (preventive policy enforcement), security group management, ticket creation and escalation, CI/CD pipeline security testing, enabling/disabling services, and integration with other security tools. Benefits: consistency, speed, reduced human error, workforce scaling.\n\nClue:\nLook for any scenario where repetitive security tasks are automated — account creation, access reviews, incident response actions, compliance checks. Automation removes manual delay and human error.\n\nExample:\nSOAR playbook: alert fires → script queries threat intel → if confirmed malicious → auto-isolate endpoint + create ticket + notify SOC — all in seconds vs. minutes manually.\n\nContrast:\nManual processes = slower, error-prone, harder to scale; Automation = consistent, fast, scalable — but misconfigured automation can cause widespread errors.",trick:"Exam map: Automation and scripting use cases"},
{cat:3,catName:"D4 Operations",acr:"User provisioning",full:"4.7 Explain the importance to secure operations.",def:"Definition:\nAutomated or manual creation and configuration of user access.\n\nClue:\nLook for proving identity, assigning access, limiting privileges, or removing access.\n\nExample:\nNew employee gets accounts.\n\nContrast:\nInsecure protocol = avoid when confidentiality is needed; secure protocol = prefer for protected communication.",trick:"Exam map: Use cases of automation and scripting > User provisioning"},
{cat:3,catName:"D4 Operations",acr:"Resource provisioning",full:"4.7 Explain the importance to secure operations.",def:"Definition:\nAutomated or manual creation and configuration of resources such as servers or cloud services.\n\nClue:\nLook for proving identity, assigning access, limiting privileges, or removing access.\n\nExample:\nCreate cloud server from template.\n\nContrast:\nInsecure protocol = avoid when confidentiality is needed; secure protocol = prefer for protected communication.",trick:"Exam map: Use cases of automation and scripting > Resource provisioning"},
{cat:3,catName:"D4 Operations",acr:"Guard rails",full:"4.7 Explain the importance to secure operations.",def:"Definition:\nAutomated boundaries that prevent unsafe actions or enforce approved configurations.\n\nClue:\nLook for what service is being connected, whether it is encrypted, and the safer protocol choice.\n\nExample:\nCloud policy prevents public storage bucket.\n\nContrast:\nInsecure protocol = avoid when confidentiality is needed; secure protocol = prefer for protected communication.",trick:"Exam map: Use cases of automation and scripting > Guard rails"},
{cat:3,catName:"D4 Operations",acr:"Security groups",full:"4.7 Explain the importance to secure operations.",def:"Definition:\nLogical groups used to apply access or firewall rules to users, systems, or cloud resources.\n\nClue:\nLook for what service is being connected, whether it is encrypted, and the safer protocol choice.\n\nExample:\nAllow web servers to database.\n\nContrast:\nInsecure protocol = avoid when confidentiality is needed; secure protocol = prefer for protected communication.",trick:"Exam map: Use cases of automation and scripting > Security groups"},
{cat:3,catName:"D4 Operations",acr:"Ticket creation",full:"4.7 Explain the importance to secure operations.",def:"Definition:\nCreating a tracked work item for action, escalation, or documentation.\n\nClue:\nLook for what service is being connected, whether it is encrypted, and the safer protocol choice.\n\nExample:\nIncident creates help desk ticket.\n\nContrast:\nInsecure protocol = avoid when confidentiality is needed; secure protocol = prefer for protected communication.",trick:"Exam map: Use cases of automation and scripting > Ticket creation"},
{cat:3,catName:"D4 Operations",acr:"Escalation",full:"4.7 Explain the importance to secure operations.",def:"Definition:\nRaising an issue to a higher support, security, or management level.\n\nClue:\nLook for what service is being connected, whether it is encrypted, and the safer protocol choice.\n\nExample:\nTier 1 sends incident to SOC.\n\nContrast:\nInsecure protocol = avoid when confidentiality is needed; secure protocol = prefer for protected communication.",trick:"Exam map: Use cases of automation and scripting > Escalation"},
{cat:3,catName:"D4 Operations",acr:"Enabling/disabling services",full:"4.7 Explain the importance to secure operations.",def:"Definition:\nAutomated or scripted control of which services run on systems — a key hardening and operations task. Disabling: remove attack surface by stopping Telnet, FTP, SMBv1, RDP, unnecessary scheduled tasks, unused Windows services. Enabling: ensure critical security services are running (Windows Defender, audit logging, FIM). Scripts can enforce consistent service state across hundreds of systems simultaneously.\n\nClue:\nLook for scenarios involving stopping unused or insecure services (disabling = hardening) or ensuring required security services are running (enabling = detection/protection). Automation makes this consistent at scale.\n\nExample:\nScript runs on all new servers: disables SMBv1, stops Telnet service, stops FTP service, enables Windows Defender, enables Windows audit logging — applied consistently across 500 servers in minutes.\n\nContrast:\nDisabling services = reduces attack surface (hardening); Enabling services = ensures security controls are active (detection). Both use the same mechanism but for opposite goals.",trick:"Exam map: Automation use cases > Enabling/disabling services"},
{cat:3,catName:"D4 Operations",acr:"Continuousintegrationandtesting",full:"4.7 Explain the importance to secure operations.",def:"Definition:\nAutomated building, testing, and validation of code changes.\n\nClue:\nLook for what service is being connected, whether it is encrypted, and the safer protocol choice.\n\nExample:\nCode commit triggers security tests.\n\nContrast:\nInsecure protocol = avoid when confidentiality is needed; secure protocol = prefer for protected communication.",trick:"Exam map: Use cases of automation and scripting > Continuousintegrationandtesting"},
{cat:3,catName:"D4 Operations",acr:"Integrations and Application",full:"4.7 Explain the importance to secure operations.",def:"Definition:\nConnecting automation and scripting with other security tools via APIs and integrations. SOAR (Security Orchestration Automation and Response) platforms integrate SIEM, threat intel, ticketing, MDM, firewall, and identity systems — allowing automated cross-tool workflows. Application programming interfaces (APIs) are the mechanism; security and authentication of those APIs (API keys, OAuth) is critical.\n\nClue:\nLook for scenarios where multiple security tools work together automatically — SIEM alert triggers SOAR → SOAR calls firewall API to block IP → creates ServiceNow ticket. That chain = integrations and application of automation.\n\nExample:\nSIEM detects beaconing → SOAR workflow queries threat intel API → confirms C2 IP → calls firewall API to block → calls EDR API to isolate endpoint → opens ticket — all automated, no human needed.\n\nContrast:\nManual integrations = analyst runs queries across multiple tools; Automated integrations = tools talk directly via APIs and orchestrate response automatically.",trick:"Exam map: Automation use cases > Integrations and application programming interfaces"},
{cat:3,catName:"D4 Operations",acr:"Efficiency/time saving",full:"4.7 Explain the importance to secure operations.",def:"Definition:\nReducing manual work and time through automation or better process design.\n\nClue:\nLook for what service is being connected, whether it is encrypted, and the safer protocol choice.\n\nExample:\nScript creates accounts.\n\nContrast:\nInsecure protocol = avoid when confidentiality is needed; secure protocol = prefer for protected communication.",trick:"Exam map: Use cases of automation and scripting > Efficiency/time saving"},
{cat:3,catName:"D4 Operations",acr:"Enforcing baselines",full:"4.7 Explain the importance to secure operations.",def:"Definition:\nAutomatically applying or checking required secure configurations.\n\nClue:\nLook for whether the control must stop, detect, fix, discourage, substitute, or limit damage.\n\nExample:\nAuto-remediate insecure setting.\n\nContrast:\nInsecure protocol = avoid when confidentiality is needed; secure protocol = prefer for protected communication.",trick:"Exam map: Use cases of automation and scripting > Enforcing baselines"},
{cat:3,catName:"D4 Operations",acr:"Standard infrastructure",full:"4.7 Explain the importance to secure operations.",def:"Definition:\nUsing automation to deploy consistent, pre-approved infrastructure from standardized templates (Infrastructure as Code — IaC, e.g., Terraform, CloudFormation). Every server built from the same hardened image inherits the same security controls. Eliminates configuration drift. New systems automatically get security agents, correct firewall rules, logging enabled, and approved software — no manual steps to forget.\n\nClue:\nLook for using templates or code to deploy infrastructure — the security benefit is consistency. Every instance built the same = every instance has the same controls = no snowflake servers that were manually configured differently.\n\nExample:\nCloud team uses Terraform to deploy web servers — every instance automatically gets: EDR agent, security group rules, encrypted EBS volume, CloudWatch logging, and approved AMI. No manual configuration.\n\nContrast:\nManually configured servers = configuration drift, missed steps; Standard infrastructure via IaC = consistent, auditable, reproducible security configuration.",trick:"Exam map: Automation use cases > Standard infrastructure (IaC)"},
{cat:3,catName:"D4 Operations",acr:"Scaling in a secure manner",full:"4.7 Explain the importance to secure operations.",def:"Definition:\nGrowing systems or services while maintaining security controls.\n\nClue:\nLook for what service is being connected, whether it is encrypted, and the safer protocol choice.\n\nExample:\nNew cloud servers inherit security group.\n\nContrast:\nInsecure protocol = avoid when confidentiality is needed; secure protocol = prefer for protected communication.",trick:"Exam map: Use cases of automation and scripting > Scaling in a secure manner"},
{cat:3,catName:"D4 Operations",acr:"Employee retention",full:"4.7 Explain the importance to secure operations.",def:"Definition:\nKeeping staff by reducing repetitive work and improving job sustainability.\n\nClue:\nLook for what service is being connected, whether it is encrypted, and the safer protocol choice.\n\nExample:\nFewer repetitive manual tickets.\n\nContrast:\nInsecure protocol = avoid when confidentiality is needed; secure protocol = prefer for protected communication.",trick:"Exam map: Use cases of automation and scripting > Employee retention"},
{cat:3,catName:"D4 Operations",acr:"Reaction time",full:"4.7 Explain the importance to secure operations.",def:"Definition:\nHow quickly a team or system responds to an event.\n\nClue:\nLook for what service is being connected, whether it is encrypted, and the safer protocol choice.\n\nExample:\nSOAR disables account immediately.\n\nContrast:\nInsecure protocol = avoid when confidentiality is needed; secure protocol = prefer for protected communication.",trick:"Exam map: Use cases of automation and scripting > Reaction time"},
{cat:3,catName:"D4 Operations",acr:"Workforce multiplier",full:"4.7 Explain the importance to secure operations.",def:"Definition:\nAutomation or orchestration that lets a small team accomplish more work.\n\nClue:\nLook for what service is being connected, whether it is encrypted, and the safer protocol choice.\n\nExample:\nOne script handles 100 alerts.\n\nContrast:\nInsecure protocol = avoid when confidentiality is needed; secure protocol = prefer for protected communication.",trick:"Exam map: Use cases of automation and scripting > Workforce multiplier"},
{cat:3,catName:"D4 Operations",acr:"Single point of failure",full:"4.7 Explain the importance to secure operations.",def:"Definition:\nOne component whose failure can stop an entire service or process.\n\nClue:\nLook for what service is being connected, whether it is encrypted, and the safer protocol choice.\n\nExample:\nOne auth server with no backup.\n\nContrast:\nInsecure protocol = avoid when confidentiality is needed; secure protocol = prefer for protected communication.",trick:"Exam map: Other considerations > Single point of failure"},
{cat:3,catName:"D4 Operations",acr:"Technical debt",full:"4.7 Explain the importance to secure operations.",def:"Definition:\nFuture cost created by shortcuts, outdated designs, or deferred maintenance.\n\nClue:\nLook for what service is being connected, whether it is encrypted, and the safer protocol choice.\n\nExample:\nOld script nobody understands.\n\nContrast:\nInsecure protocol = avoid when confidentiality is needed; secure protocol = prefer for protected communication.",trick:"Exam map: Other considerations > Technical debt"},
{cat:3,catName:"D4 Operations",acr:"Ongoing supportability",full:"4.7 Explain the importance to secure operations.",def:"Definition:\nAbility to maintain and support a system over time.\n\nClue:\nLook for what service is being connected, whether it is encrypted, and the safer protocol choice.\n\nExample:\nTool still has vendor support.\n\nContrast:\nInsecure protocol = avoid when confidentiality is needed; secure protocol = prefer for protected communication.",trick:"Exam map: Other considerations > Ongoing supportability"},
{cat:3,catName:"D4 Operations",acr:"Preparation",full:"4.8 Explain appropriate incident response activities.",def:"Definition:\nIncident response phase where plans, tools, roles, and training are established.\n\nClue:\nLook for the exact scenario words and match them to the safest, most specific answer.\n\nExample:\nBuild incident playbooks.\n\nContrast:\nCompare it with nearby terms in the same objective to see why this answer fits best.",trick:"Exam map: Process > Preparation"},
{cat:3,catName:"D4 Operations",acr:"Detection",full:"4.8 Explain appropriate incident response activities.",def:"Definition:\nIncident response phase where suspicious activity is identified.\n\nClue:\nLook for the exact scenario words and match them to the safest, most specific answer.\n\nExample:\nSIEM alert triggers investigation.\n\nContrast:\nCompare it with nearby terms in the same objective to see why this answer fits best.",trick:"Exam map: Process > Detection"},
{cat:3,catName:"D4 Operations",acr:"Containment",full:"4.8 Explain appropriate incident response activities.",def:"Definition:\nIncident response phase focused on limiting spread or damage.\n\nClue:\nLook for the exact scenario words and match them to the safest, most specific answer.\n\nExample:\nIsolate infected host.\n\nContrast:\nCompare it with nearby terms in the same objective to see why this answer fits best.",trick:"Exam map: Process > Containment"},
{cat:3,catName:"D4 Operations",acr:"Eradication",full:"4.8 Explain appropriate incident response activities.",def:"Definition:\nIncident response phase where the root cause or malicious presence is removed.\n\nClue:\nLook for the exact scenario words and match them to the safest, most specific answer.\n\nExample:\nDelete malware and close backdoor.\n\nContrast:\nCompare it with nearby terms in the same objective to see why this answer fits best.",trick:"Exam map: Process > Eradication"},
{cat:3,catName:"D4 Operations",acr:"Lessons learned",full:"4.8 Explain appropriate incident response activities.",def:"Definition:\nPost-incident review used to improve controls and response.\n\nClue:\nLook for the exact scenario words and match them to the safest, most specific answer.\n\nExample:\nUpdate playbook after incident.\n\nContrast:\nCompare it with nearby terms in the same objective to see why this answer fits best.",trick:"Exam map: Process > Lessons learned"},
{cat:3,catName:"D4 Operations",acr:"Training",full:"4.8 Explain appropriate incident response activities.",def:"Definition:\nIncident response training prepares teams to execute plans correctly under pressure. Types: role-based technical training (SOC analysts, IR team, forensics), tabletop exercises (discussion-based scenario walkthroughs), simulation exercises (hands-on, system-level practice), and full-scale drills (live systems, real response). Training must be regular and kept current as threats evolve.\n\nClue:\nLook for training as the preparation phase of incident response — teams must know their roles before an incident. Tabletop = low cost, no systems needed. Simulation = higher fidelity, uses live systems.\n\nExample:\nIncident response team does monthly tabletop exercises using ransomware scenarios. Each person knows their role: who calls legal, who images drives, who communicates to management.\n\nContrast:\nTabletop = verbal walkthrough, no live systems; Simulation = hands-on with real or simulated systems; Parallel processing = old and new systems running simultaneously during actual changeover.",trick:"Exam map: Incident response > Training"},
{cat:3,catName:"D4 Operations",acr:"Tabletop exercise",full:"4.8 Explain appropriate incident response activities.",def:"Definition:\nDiscussion-based incident response exercise where team members verbally walk through a simulated scenario around a table (or virtually). No actual systems are used or affected. Tests plans, decision-making, communication paths, and role clarity. Low cost, low risk, high value for identifying gaps in plans and procedures. Most common starting point for IR preparedness testing.\n\nClue:\nLook for verbal/discussion-based testing with no systems involved — 'what would you do if...' scenarios. Tabletop = cheapest and safest form of IR exercise. If systems are involved, it's a simulation.\n\nExample:\nIR team gathers: 'Ransomware has encrypted the file server. Walk through: who does what, in what order, who gets notified, what decisions need approval?' — no systems touched, plan gaps identified.\n\nContrast:\nTabletop = discussion only; Simulation = uses real or simulated systems; Full-scale drill = live systems, real response actions; Parallel processing = testing while old system still runs.",trick:"Exam map: Incident response > Tabletop exercise"},
{cat:3,catName:"D4 Operations",acr:"Root cause analysis",full:"4.8 Explain appropriate incident response activities.",def:"Definition:\nProcess of finding the underlying reason an incident or failure occurred.\n\nClue:\nLook for the exact scenario words and match them to the safest, most specific answer.\n\nExample:\nWeak password caused breach.\n\nContrast:\nCompare it with nearby terms in the same objective to see why this answer fits best.",trick:"Exam map: 4.0 Security Operations"},
{cat:3,catName:"D4 Operations",acr:"Threat hunting",full:"4.8 Explain appropriate incident response activities.",def:"Definition:\nProactive search for threats that automated tools may not have detected.\n\nClue:\nLook for the exact scenario words and match them to the safest, most specific answer.\n\nExample:\nSearch for suspicious PowerShell.\n\nContrast:\nMitigation/control = defense; this term describes the problem or weakness.",trick:"Exam map: 4.0 Security Operations"},
{cat:3,catName:"D4 Operations",acr:"Digital forensics",full:"4.8 Explain appropriate incident response activities.",def:"Definition:\nCollection and analysis of digital evidence while preserving integrity.\n\nClue:\nLook for the exact scenario words and match them to the safest, most specific answer.\n\nExample:\nImage a hard drive.\n\nContrast:\nCompare it with nearby terms in the same objective to see why this answer fits best.",trick:"Exam map: 4.0 Security Operations"},
{cat:3,catName:"D4 Operations",acr:"Legal hold",full:"4.8 Explain appropriate incident response activities.",def:"Definition:\nProcess that preserves relevant data because of legal or regulatory requirements.\n\nClue:\nLook for preserving evidence because of legal action.\n\nExample:\nDo not delete mailbox under lawsuit.\n\nContrast:\nChain of custody tracks handling; Legal hold prevents deletion.",trick:"Exam map: Digital forensics > Legal hold"},
{cat:3,catName:"D4 Operations",acr:"Chain of custody",full:"4.8 Explain appropriate incident response activities.",def:"Definition:\nDocumented record of who handled evidence and when.\n\nClue:\nLook for evidence handling records: who, when, where, and what.\n\nExample:\nRecord who handled laptop.\n\nContrast:\nLegal hold preserves data; Chain of custody tracks evidence handling.",trick:"Exam map: Digital forensics > Chain of custody"},
{cat:3,catName:"D4 Operations",acr:"Acquisition",full:"4.8 Explain appropriate incident response activities.",def:"Definition:\nForensic collection of data, images, or evidence.\n\nClue:\nLook for the exact scenario words and match them to the safest, most specific answer.\n\nExample:\nCapture disk image.\n\nContrast:\nCompare it with nearby terms in the same objective to see why this answer fits best.",trick:"Exam map: Digital forensics > Acquisition"},
{cat:3,catName:"D4 Operations",acr:"Preservation",full:"4.8 Explain appropriate incident response activities.",def:"Definition:\nProtecting evidence from alteration or destruction.\n\nClue:\nLook for the exact scenario words and match them to the safest, most specific answer.\n\nExample:\nStore image read-only.\n\nContrast:\nCompare it with nearby terms in the same objective to see why this answer fits best.",trick:"Exam map: Digital forensics > Preservation"},
{cat:3,catName:"D4 Operations",acr:"E-discovery",full:"4.8 Explain appropriate incident response activities.",def:"Definition:\nIdentifying and producing electronic evidence for legal matters.\n\nClue:\nLook for the exact scenario words and match them to the safest, most specific answer.\n\nExample:\nProduce relevant emails.\n\nContrast:\nCompare it with nearby terms in the same objective to see why this answer fits best.",trick:"Exam map: Digital forensics > E-discovery"},
{cat:3,catName:"D4 Operations",acr:"Log data",full:"4.9 Given a scenario, use data sources to support an investigation.",def:"Definition:\nCategory of data sources used in security investigations. Key log types: Firewall logs (allowed/denied connections), Application logs (user activity, errors, transactions), Endpoint/OS logs (process execution, logins, file changes), IDS/IPS logs (attack detections and blocks), Network logs (traffic flows, DHCP, DNS), Metadata (timestamps, file owners, source IPs). Each type provides different visibility for reconstructing events.\n\nClue:\nMatch the investigation question to the log type: 'who connected from outside?' = firewall logs; 'what process ran on the server?' = endpoint/OS logs; 'what attack signatures fired?' = IDS/IPS logs; 'what website did the user visit?' = proxy/DNS logs.\n\nExample:\nInvestigating a breach: firewall logs show external connection to port 3389, OS logs show RDP login with domain admin, endpoint logs show new service installed — three log types together tell the full story.\n\nContrast:\nEach log type has different visibility: firewall = network boundary; endpoint = individual host; IDS/IPS = known attack patterns; metadata = attributes about data, not the data itself.",trick:"Exam map: Investigation data sources > Log data"},
{cat:3,catName:"D4 Operations",acr:"Firewall logs",full:"4.9 Given a scenario, use data sources to support an investigation.",def:"Definition:\nRecords of traffic allowed, denied, or inspected by a firewall.\n\nClue:\nLook for where the asset lives, what can fail, and how the design protects or restores CIA.\n\nExample:\nShows blocked connection attempts.\n\nContrast:\nInsecure protocol = avoid when confidentiality is needed; secure protocol = prefer for protected communication.",trick:"Exam map: Log data > Firewall logs"},
{cat:3,catName:"D4 Operations",acr:"Application logs",full:"4.9 Given a scenario, use data sources to support an investigation.",def:"Definition:\nRecords generated by applications about events, errors, users, or transactions.\n\nClue:\nLook for where the asset lives, what can fail, and how the design protects or restores CIA.\n\nExample:\nShows failed checkout errors.\n\nContrast:\nInsecure protocol = avoid when confidentiality is needed; secure protocol = prefer for protected communication.",trick:"Exam map: Log data > Application logs"},
{cat:3,catName:"D4 Operations",acr:"Endpoint logs",full:"4.9 Given a scenario, use data sources to support an investigation.",def:"Definition:\nRecords from workstations, servers, or mobile devices.\n\nClue:\nLook for where the asset lives, what can fail, and how the design protects or restores CIA.\n\nExample:\nLaptop logs process execution.\n\nContrast:\nInsecure protocol = avoid when confidentiality is needed; secure protocol = prefer for protected communication.",trick:"Exam map: Log data > Endpoint logs"},
{cat:3,catName:"D4 Operations",acr:"OS-specific security logs",full:"4.9 Given a scenario, use data sources to support an investigation.",def:"Definition:\nOperating system logs related to authentication, permissions, policy, and security events.\n\nClue:\nLook for where the asset lives, what can fail, and how the design protects or restores CIA.\n\nExample:\nWindows event log shows login failure.\n\nContrast:\nInsecure protocol = avoid when confidentiality is needed; secure protocol = prefer for protected communication.",trick:"Exam map: Log data > OS-specific security logs"},
{cat:3,catName:"D4 Operations",acr:"IPS/IDS logs",full:"4.9 Given a scenario, use data sources to support an investigation.",def:"Definition:\nRecords of events detected and acted upon by IDS/IPS systems. IDS logs = alerts on suspicious traffic patterns matching signatures or anomaly baselines. IPS logs = alerts plus records of traffic that was blocked/dropped. Key investigation value: shows attack attempts, lateral movement, exploit attempts, and reconnaissance activity that traversed the network — including what was blocked and what got through.\n\nClue:\nLook for investigating what attacks were attempted and which succeeded vs. were blocked. IDS/IPS logs show the attacker's footprint on the network — scan activity, exploit attempts, C2 communication attempts.\n\nExample:\nInvestigation finds IPS log from 3 days ago: blocked exploit attempt against CVE-2021-44228 from external IP. Same IP shows in firewall logs making a different connection 2 hours later — first attempt blocked, second method succeeded.\n\nContrast:\nFirewall logs = connection-level allowed/denied; IDS/IPS logs = pattern/signature-matched attack detection with context about the specific attack type.",trick:"Exam map: Log data > IPS/IDS logs"},
{cat:3,catName:"D4 Operations",acr:"Network logs",full:"4.9 Given a scenario, use data sources to support an investigation.",def:"Definition:\nRecords from network devices and services.\n\nClue:\nLook for where the asset lives, what can fail, and how the design protects or restores CIA.\n\nExample:\nSwitch logs port changes.\n\nContrast:\nInsecure protocol = avoid when confidentiality is needed; secure protocol = prefer for protected communication.",trick:"Exam map: Log data > Network logs"},
{cat:3,catName:"D4 Operations",acr:"Metadata",full:"4.9 Given a scenario, use data sources to support an investigation.",def:"Definition:\nData about data, such as timestamps, source, size, location, or owner.\n\nClue:\nLook for data about data, such as timestamps, owner, source, or size.\n\nExample:\nFile created time and owner.\n\nContrast:\nInsecure protocol = avoid when confidentiality is needed; secure protocol = prefer for protected communication.",trick:"Exam map: Log data > Metadata"},
{cat:3,catName:"D4 Operations",acr:"Vulnerability scans",full:"4.9 Given a scenario, use data sources to support an investigation.",def:"Definition:\nAs an investigation data source: results of vulnerability scans provide context for how an attacker may have gained initial access or moved laterally. During incident response, reviewing vulnerability scan results for affected systems reveals which weaknesses existed — helping reconstruct the attack path and identify other systems at risk from the same vulnerability.\n\nClue:\nLook for using scan results to support investigation — not just to prioritize patching, but to understand how an attacker got in. If a breached server had a critical CVE, the scan data confirms the likely attack vector.\n\nExample:\nAfter a breach, IR team pulls vulnerability scan data for the compromised web server — scan shows CVE-2021-21985 (VMware vCenter) was unpatched, confirming the likely initial access method.\n\nContrast:\nVulnerability scan as proactive activity = find and fix weaknesses. Vulnerability scan as investigation data source = understand attack path by knowing what weaknesses existed at time of breach.",trick:"Exam map: Investigation data sources > Vulnerability scans"},
{cat:3,catName:"D4 Operations",acr:"Automated reports",full:"4.9 Given a scenario, use data sources to support an investigation.",def:"Definition:\nReports generated by tools or scheduled processes.\n\nClue:\nLook for where the asset lives, what can fail, and how the design protects or restores CIA.\n\nExample:\nWeekly vuln summary.\n\nContrast:\nInsecure protocol = avoid when confidentiality is needed; secure protocol = prefer for protected communication.",trick:"Exam map: Data sources > Automated reports"},
{cat:3,catName:"D4 Operations",acr:"Dashboards",full:"4.9 Given a scenario, use data sources to support an investigation.",def:"Definition:\nVisual displays of security or operational metrics.\n\nClue:\nLook for where the asset lives, what can fail, and how the design protects or restores CIA.\n\nExample:\nSOC screen shows alerts.\n\nContrast:\nInsecure protocol = avoid when confidentiality is needed; secure protocol = prefer for protected communication.",trick:"Exam map: Data sources > Dashboards"},
{cat:3,catName:"D4 Operations",acr:"Packet captures",full:"4.9 Given a scenario, use data sources to support an investigation.",def:"Definition:\nRecorded network packets used for traffic analysis and investigation.\n\nClue:\nLook for where the asset lives, what can fail, and how the design protects or restores CIA.\n\nExample:\nWireshark PCAP shows DNS requests.\n\nContrast:\nInsecure protocol = avoid when confidentiality is needed; secure protocol = prefer for protected communication.",trick:"Exam map: Data sources > Packet captures"},
{cat:4,catName:"D5 Governance & Risk",acr:"Information security policies",full:"5.0 Objective topic from Security Program Management and Oversight",def:"Definition:\nPolicies that define how the organization protects information and systems.\n\nClue:\nLook for ownership, documentation, testing scope, evidence, compliance, or risk decisions.\n\nExample:\nData classification policy.\n\nContrast:\nTechnical control = system defense; governance term = decision, evidence, responsibility, or requirement.",trick:"Exam map: Policies > Information security policies"},
{cat:4,catName:"D5 Governance & Risk",acr:"Business continuity",full:"5.0 Objective topic from Security Program Management and Oversight",def:"Definition:\nPlanning to keep essential business functions operating during disruption.\n\nClue:\nLook for ownership, documentation, testing scope, evidence, compliance, or risk decisions.\n\nExample:\nContinue orders during outage.\n\nContrast:\nTechnical control = system defense; governance term = decision, evidence, responsibility, or requirement.",trick:"Exam map: Policies > Business continuity"},
{cat:4,catName:"D5 Governance & Risk",acr:"Disaster recovery",full:"5.0 Objective topic from Security Program Management and Oversight",def:"Definition:\nPlanning to restore IT systems and data after a disaster.\n\nClue:\nLook for where the asset lives, what can fail, and how the design protects or restores CIA.\n\nExample:\nRestore servers after flood.\n\nContrast:\nTechnical control = system defense; governance term = decision, evidence, responsibility, or requirement.",trick:"Exam map: Policies > Disaster recovery"},
{cat:4,catName:"D5 Governance & Risk",acr:"Change management",full:"5.0 Objective topic from Security Program Management and Oversight",def:"Definition:\nControlled process for requesting, approving, testing, and documenting changes.\n\nClue:\nLook for ownership, documentation, testing scope, evidence, compliance, or risk decisions.\n\nExample:\nApprove router update.\n\nContrast:\nTechnical control = system defense; governance term = decision, evidence, responsibility, or requirement.",trick:"Exam map: Policies > Change management"},
{cat:4,catName:"D5 Governance & Risk",acr:"Password",full:"5.0 Objective topic from Security Program Management and Oversight",def:"Definition:\nPassword standards define organizational requirements for password creation, storage, and management. Modern guidance (NIST 800-63B): minimum 8 characters (longer preferred), no mandatory complexity rules, no mandatory periodic rotation (unless compromised), check against known-breached password lists (HaveIBeenPwned), allow passphrases, no hints or knowledge-based authentication. Storage: bcrypt/PBKDF2/Argon2 with salt — never plain MD5 or SHA-1.\n\nClue:\nNIST 800-63B is the exam reference: length over complexity, no forced rotation, check breach databases. Traditional standards required complexity (uppercase + number + symbol) and 90-day rotation — NIST now says this leads to predictable weak passwords.\n\nExample:\nNIST-compliant policy: minimum 15 characters, no complexity requirement, no expiration unless user requests or breach detected, passphrase 'blue-horse-battery-sunrise' encouraged over 'P@ssw0rd1!'.\n\nContrast:\nTraditional password standards = complexity + 90-day rotation; NIST 800-63B = length + breach checking + no forced rotation. Both appear on the exam — know which is current guidance.",trick:"Exam map: Standards > Password standards (NIST 800-63B)"},
{cat:4,catName:"D5 Governance & Risk",acr:"Onboarding/offboarding",full:"5.0 Objective topic from Security Program Management and Oversight",def:"Definition:\nProcesses for granting access when people join and removing access when they leave.\n\nClue:\nLook for ownership, documentation, testing scope, evidence, compliance, or risk decisions.\n\nExample:\nRemove accounts when employee leaves.\n\nContrast:\nTechnical control = system defense; governance term = decision, evidence, responsibility, or requirement.",trick:"Exam map: Procedures > Onboarding/offboarding"},
{cat:4,catName:"D5 Governance & Risk",acr:"Playbooks",full:"5.0 Objective topic from Security Program Management and Oversight",def:"Definition:\nDetailed action guides for common operational or incident scenarios.\n\nClue:\nLook for ownership, documentation, testing scope, evidence, compliance, or risk decisions.\n\nExample:\nPhishing playbook.\n\nContrast:\nTechnical control = system defense; governance term = decision, evidence, responsibility, or requirement.",trick:"Exam map: Procedures > Playbooks"},
{cat:4,catName:"D5 Governance & Risk",acr:"Regulatory",full:"5.0 Objective topic from Security Program Management and Oversight",def:"Definition:\nSecurity or privacy requirements created or enforced by government or industry regulators.\n\nClue:\nLook for ownership, documentation, testing scope, evidence, compliance, or risk decisions.\n\nExample:\nHIPAA requirements.\n\nContrast:\nTechnical control = system defense; governance term = decision, evidence, responsibility, or requirement.",trick:"Exam map: External considerations > Regulatory"},
{cat:4,catName:"D5 Governance & Risk",acr:"Legal",full:"5.0 Objective topic from Security Program Management and Oversight",def:"Definition:\nSecurity requirements, risks, or actions related to laws, contracts, investigations, liability, or court obligations.\n\nClue:\nLook for ownership, documentation, testing scope, evidence, compliance, or risk decisions.\n\nExample:\nPreserve evidence for lawsuit.\n\nContrast:\nTechnical control = system defense; governance term = decision, evidence, responsibility, or requirement.",trick:"Exam map: External considerations > Legal"},
{cat:4,catName:"D5 Governance & Risk",acr:"Industry",full:"5.0 Objective topic from Security Program Management and Oversight",def:"Definition:\nSecurity requirements or expectations that apply to a specific business sector.\n\nClue:\nLook for ownership, documentation, testing scope, evidence, compliance, or risk decisions.\n\nExample:\nPCI DSS for payment cards.\n\nContrast:\nTechnical control = system defense; governance term = decision, evidence, responsibility, or requirement.",trick:"Exam map: External considerations > Industry"},
{cat:4,catName:"D5 Governance & Risk",acr:"Local/regional",full:"5.0 Objective topic from Security Program Management and Oversight",def:"Definition:\nSecurity or privacy requirements that apply to a specific local area, state, province, or region.\n\nClue:\nLook for ownership, documentation, testing scope, evidence, compliance, or risk decisions.\n\nExample:\nState privacy law.\n\nContrast:\nTechnical control = system defense; governance term = decision, evidence, responsibility, or requirement.",trick:"Exam map: External considerations > Local/regional"},
{cat:4,catName:"D5 Governance & Risk",acr:"National",full:"5.0 Objective topic from Security Program Management and Oversight",def:"Definition:\nRequirements or risks that apply at the country level.\n\nClue:\nLook for ownership, documentation, testing scope, evidence, compliance, or risk decisions.\n\nExample:\nFederal regulation.\n\nContrast:\nTechnical control = system defense; governance term = decision, evidence, responsibility, or requirement.",trick:"Exam map: External considerations > National"},
{cat:4,catName:"D5 Governance & Risk",acr:"Global",full:"5.0 Objective topic from Security Program Management and Oversight",def:"Definition:\nRequirements or risks that apply across multiple countries or regions.\n\nClue:\nLook for ownership, documentation, testing scope, evidence, compliance, or risk decisions.\n\nExample:\nGDPR for EU users.\n\nContrast:\nTechnical control = system defense; governance term = decision, evidence, responsibility, or requirement.",trick:"Exam map: External considerations > Global"},
{cat:4,catName:"D5 Governance & Risk",acr:"Monitoring and revision",full:"5.0 Objective topic from Security Program Management and Oversight",def:"Definition:\nRegular review and updating of governance documents and controls.\n\nClue:\nLook for ownership, documentation, testing scope, evidence, compliance, or risk decisions.\n\nExample:\nUpdate policy yearly.\n\nContrast:\nThreat/vulnerability = problem; control/mitigation = defense.",trick:"Exam map: 5.0 Security Program Management and Oversight"},
{cat:4,catName:"D5 Governance & Risk",acr:"Types of governance structures",full:"5.0 Objective topic from Security Program Management and Oversight",def:"Definition:\nOrganizational models that determine how security decisions are made and who has authority. Structures: Boards (executive oversight, sets risk appetite), Committees (working groups for specific areas like security steering committee), Government entities (regulatory bodies with authority to mandate requirements), and Centralized vs. Decentralized governance (single authority vs. distributed decision-making across business units).\n\nClue:\nLook for who has authority over security decisions in the scenario. Board = highest strategic oversight. Committee = working group. Centralized = one SOC/policy for all. Decentralized = each business unit makes its own decisions.\n\nExample:\nLarge multinational: centralized governance = one global security policy enforced everywhere. Decentralized = each regional subsidiary sets its own security standards (inconsistency risk).\n\nContrast:\nGovernance structure determines accountability and authority; Technical controls are what the governance structure mandates. Without governance, no one owns the risk decisions.",trick:"Exam map: Governance > Types of governance structures"},
{cat:4,catName:"D5 Governance & Risk",acr:"Boards",full:"5.0 Objective topic from Security Program Management and Oversight",def:"Definition:\nGovernance bodies that provide oversight and decision-making.\n\nClue:\nLook for ownership, documentation, testing scope, evidence, compliance, or risk decisions.\n\nExample:\nBoard reviews cyber risk.\n\nContrast:\nTechnical control = system defense; governance term = decision, evidence, responsibility, or requirement.",trick:"Exam map: Types of governance structures > Boards"},
{cat:4,catName:"D5 Governance & Risk",acr:"Committees",full:"5.0 Objective topic from Security Program Management and Oversight",def:"Definition:\nGroups assigned to review, coordinate, or govern specific areas.\n\nClue:\nLook for ownership, documentation, testing scope, evidence, compliance, or risk decisions.\n\nExample:\nSecurity steering committee.\n\nContrast:\nTechnical control = system defense; governance term = decision, evidence, responsibility, or requirement.",trick:"Exam map: Types of governance structures > Committees"},
{cat:4,catName:"D5 Governance & Risk",acr:"Government entities",full:"5.0 Objective topic from Security Program Management and Oversight",def:"Definition:\nPublic agencies or bodies that create or enforce requirements.\n\nClue:\nLook for ownership, documentation, testing scope, evidence, compliance, or risk decisions.\n\nExample:\nRegulator audits compliance.\n\nContrast:\nTechnical control = system defense; governance term = decision, evidence, responsibility, or requirement.",trick:"Exam map: Types of governance structures > Government entities"},
{cat:4,catName:"D5 Governance & Risk",acr:"Centralized/decentralized",full:"5.0 Objective topic from Security Program Management and Oversight",def:"Definition:\nGovernance structure where authority is either concentrated centrally or distributed across groups.\n\nClue:\nLook for ownership, documentation, testing scope, evidence, compliance, or risk decisions.\n\nExample:\nCentral SOC vs branch teams.\n\nContrast:\nTechnical control = system defense; governance term = decision, evidence, responsibility, or requirement.",trick:"Exam map: Types of governance structures > Centralized/decentralized"},
{cat:4,catName:"D5 Governance & Risk",acr:"Roles and responsibilities for systems and data",full:"5.0 Objective topic from Security Program Management and Oversight",def:"Definition:\nClear accountability structure for data and system security. Key roles: Data Owner = business owner accountable for data, approves access and classification. Data Custodian/Steward = IT staff responsible for maintaining and protecting data per owner requirements. Controller = decides WHY and HOW personal data is processed (GDPR term). Processor = processes personal data on controller's behalf. User = accesses data to do their job.\n\nClue:\nMemorize: Owner = accountable (approves), Custodian = responsible (maintains), Controller = decides processing purpose (GDPR), Processor = executes processing. On the exam: who approves new access? Data Owner. Who implements the controls? Custodian.\n\nExample:\nHR Director (Data Owner) approves who gets access to employee records. DBA (Custodian) implements database permissions. Payroll vendor (Processor) processes the payroll data on HR's behalf.\n\nContrast:\nData Owner = business accountability; Custodian = technical responsibility; User = operational use. Owner cannot be the same person as the Custodian (separation of duties).",trick:"Exam map: Governance > Roles and responsibilities for systems and data"},
{cat:4,catName:"D5 Governance & Risk",acr:"Owners",full:"5.0 Objective topic from Security Program Management and Oversight",def:"Definition:\nPeople accountable for data, systems, or business processes.\n\nClue:\nLook for where the asset lives, what can fail, and how the design protects or restores CIA.\n\nExample:\nData owner approves access.\n\nContrast:\nTechnical control = system defense; governance term = decision, evidence, responsibility, or requirement.",trick:"Exam map: Roles and responsibilities for systems and data > Owners"},
{cat:4,catName:"D5 Governance & Risk",acr:"Controllers",full:"5.0 Objective topic from Security Program Management and Oversight",def:"Definition:\nEntities that decide why and how personal data is processed.\n\nClue:\nLook for where the asset lives, what can fail, and how the design protects or restores CIA.\n\nExample:\nCompany collecting customer info.\n\nContrast:\nThreat/vulnerability = problem; control/mitigation = defense.",trick:"Exam map: Roles and responsibilities for systems and data > Controllers"},
{cat:4,catName:"D5 Governance & Risk",acr:"Processors",full:"5.0 Objective topic from Security Program Management and Oversight",def:"Definition:\nEntities that process personal data on behalf of controllers.\n\nClue:\nLook for where the asset lives, what can fail, and how the design protects or restores CIA.\n\nExample:\nPayroll vendor processes employee data.\n\nContrast:\nTechnical control = system defense; governance term = decision, evidence, responsibility, or requirement.",trick:"Exam map: Roles and responsibilities for systems and data > Processors"},
{cat:4,catName:"D5 Governance & Risk",acr:"Custodians/stewards",full:"5.0 Objective topic from Security Program Management and Oversight",def:"Definition:\nPeople responsible for handling, maintaining, or protecting data according to owner requirements.\n\nClue:\nLook for where the asset lives, what can fail, and how the design protects or restores CIA.\n\nExample:\nDBA maintains database security.\n\nContrast:\nTechnical control = system defense; governance term = decision, evidence, responsibility, or requirement.",trick:"Exam map: Roles and responsibilities for systems and data > Custodians/stewards"},
{cat:4,catName:"D5 Governance & Risk",acr:"Ad hoc",full:"5.2 Explain elements of the risk management process.",def:"Definition:\nAn activity performed when needed instead of on a regular schedule.\n\nClue:\nLook for “as needed,” unscheduled, or event-driven work.\n\nExample:\nSpecial risk review after merger.\n\nContrast:\nRecurring = scheduled; Ad hoc = only when needed.",trick:"Exam map: Risk assessment > Ad hoc"},
{cat:4,catName:"D5 Governance & Risk",acr:"Recurring",full:"5.2 Explain elements of the risk management process.",def:"Definition:\nAn activity that repeats on a planned schedule, such as annual training or quarterly access reviews.\n\nClue:\nLook for scheduled reviews, repeated training, quarterly scans, or annual audits.\n\nExample:\nAnnual security training.\n\nContrast:\nOne-time = once; Continuous = ongoing all the time.",trick:"Exam map: Risk assessment > Recurring"},
{cat:4,catName:"D5 Governance & Risk",acr:"One-time",full:"5.2 Explain elements of the risk management process.",def:"Definition:\nAn activity performed once for a specific event, project, or requirement.\n\nClue:\nTriggered by a single event, new system, audit, deployment, or special requirement.\n\nExample:\nAudit before launch.\n\nContrast:\nContinuous = ongoing monitoring; Recurring = repeated on a schedule.",trick:"Exam map: Risk assessment > One-time"},
{cat:4,catName:"D5 Governance & Risk",acr:"Continuous",full:"5.2 Explain elements of the risk management process.",def:"Definition:\nAn activity performed constantly or near constantly, such as continuous monitoring.\n\nClue:\nLook for ongoing, always-on, real-time, or constant monitoring.\n\nExample:\nContinuous vulnerability monitoring.\n\nContrast:\nOne-time = performed once; Recurring = repeated on a schedule.",trick:"Exam map: Risk assessment > Continuous"},
{cat:4,catName:"D5 Governance & Risk",acr:"Qualitative",full:"5.2 Explain elements of the risk management process.",def:"Definition:\nRisk analysis using descriptive ratings such as low, medium, or high.\n\nClue:\nLook for ownership, documentation, testing scope, evidence, compliance, or risk decisions.\n\nExample:\nHigh, medium, low.\n\nContrast:\nTechnical control = system defense; governance term = decision, evidence, responsibility, or requirement.",trick:"Exam map: Risk analysis > Qualitative"},
{cat:4,catName:"D5 Governance & Risk",acr:"Quantitative",full:"5.2 Explain elements of the risk management process.",def:"Definition:\nRisk analysis using numeric values, money, or measurable probabilities.\n\nClue:\nLook for ownership, documentation, testing scope, evidence, compliance, or risk decisions.\n\nExample:\n$50,000 expected loss.\n\nContrast:\nTechnical control = system defense; governance term = decision, evidence, responsibility, or requirement.",trick:"Exam map: Risk analysis > Quantitative"},
{cat:4,catName:"D5 Governance & Risk",acr:"Probability",full:"5.2 Explain elements of the risk management process.",def:"Definition:\nA numeric or estimated measure of how likely an event is to occur.\n\nClue:\nLook for ownership, documentation, testing scope, evidence, compliance, or risk decisions.\n\nExample:\n20% chance per year.\n\nContrast:\nTechnical control = system defense; governance term = decision, evidence, responsibility, or requirement.",trick:"Exam map: Risk analysis > Probability"},
{cat:4,catName:"D5 Governance & Risk",acr:"Likelihood",full:"5.2 Explain elements of the risk management process.",def:"Definition:\nThe estimated chance that a risk, threat, or event will happen.\n\nClue:\nLook for ownership, documentation, testing scope, evidence, compliance, or risk decisions.\n\nExample:\nVery likely phishing attempts.\n\nContrast:\nTechnical control = system defense; governance term = decision, evidence, responsibility, or requirement.",trick:"Exam map: Risk analysis > Likelihood"},
{cat:4,catName:"D5 Governance & Risk",acr:"Impact",full:"5.2 Explain elements of the risk management process.",def:"Definition:\nThe amount of harm, cost, downtime, or business damage that happens if a risk or incident occurs.\n\nClue:\nLook for ownership, documentation, testing scope, evidence, compliance, or risk decisions.\n\nExample:\nCustomer data breach damage.\n\nContrast:\nTechnical control = system defense; governance term = decision, evidence, responsibility, or requirement.",trick:"Exam map: Risk analysis > Impact"},
{cat:4,catName:"D5 Governance & Risk",acr:"Key risk indicators",full:"5.2 Explain elements of the risk management process.",def:"Definition:\nMetrics that signal increasing or decreasing risk.\n\nClue:\nLook for how the attack or weakness behaves, what it targets, and what reduces the damage.\n\nExample:\nFailed login spikes.\n\nContrast:\nTechnical control = system defense; governance term = decision, evidence, responsibility, or requirement.",trick:"Exam map: Risk register > Key risk indicators"},
{cat:4,catName:"D5 Governance & Risk",acr:"Risk owners",full:"5.2 Explain elements of the risk management process.",def:"Definition:\nPeople accountable for managing specific risks.\n\nClue:\nLook for ownership, documentation, testing scope, evidence, compliance, or risk decisions.\n\nExample:\nCFO owns payment fraud risk.\n\nContrast:\nTechnical control = system defense; governance term = decision, evidence, responsibility, or requirement.",trick:"Exam map: Risk register > Risk owners"},
{cat:4,catName:"D5 Governance & Risk",acr:"Risk threshold",full:"5.2 Explain elements of the risk management process.",def:"Definition:\nPoint where risk becomes unacceptable or requires action.\n\nClue:\nLook for the point where risk becomes unacceptable.\n\nExample:\nCritical vulnerabilities fixed in 7 days.\n\nContrast:\nRisk tolerance = acceptable range; Threshold = line that triggers action.",trick:"Exam map: Risk register > Risk threshold"},
{cat:4,catName:"D5 Governance & Risk",acr:"Expansionary",full:"5.2 Explain elements of the risk management process.",def:"Definition:\nA risk appetite style where an organization accepts more risk to grow, innovate, or move quickly.\n\nClue:\nLook for ownership, documentation, testing scope, evidence, compliance, or risk decisions.\n\nExample:\nAccept risk to enter new market.\n\nContrast:\nTechnical control = system defense; governance term = decision, evidence, responsibility, or requirement.",trick:"Exam map: Risk appetite > Expansionary"},
{cat:4,catName:"D5 Governance & Risk",acr:"Conservative",full:"5.2 Explain elements of the risk management process.",def:"Definition:\nA risk appetite style where an organization avoids or minimizes risk, even if progress is slower.\n\nClue:\nLook for ownership, documentation, testing scope, evidence, compliance, or risk decisions.\n\nExample:\nAvoid risky vendors.\n\nContrast:\nTechnical control = system defense; governance term = decision, evidence, responsibility, or requirement.",trick:"Exam map: Risk appetite > Conservative"},
{cat:4,catName:"D5 Governance & Risk",acr:"Neutral",full:"5.2 Explain elements of the risk management process.",def:"Definition:\nA balanced risk appetite style that weighs opportunity against protection without being overly aggressive or overly cautious.\n\nClue:\nLook for ownership, documentation, testing scope, evidence, compliance, or risk decisions.\n\nExample:\nAccept moderate risk with controls.\n\nContrast:\nTechnical control = system defense; governance term = decision, evidence, responsibility, or requirement.",trick:"Exam map: Risk appetite > Neutral"},
{cat:4,catName:"D5 Governance & Risk",acr:"Transfer",full:"5.2 Explain elements of the risk management process.",def:"Definition:\nRisk strategy that shifts financial or operational impact to another party.\n\nClue:\nLook for shifting financial impact to another party, such as insurance.\n\nExample:\nBuy cyber insurance.\n\nContrast:\nAccept = keep the risk; Transfer = shift impact to another party.",trick:"Exam map: Risk management strategies > Transfer"},
{cat:4,catName:"D5 Governance & Risk",acr:"Accept",full:"5.2 Explain elements of the risk management process.",def:"Definition:\nRisk strategy where the organization knowingly takes no further action beyond acknowledging the risk.\n\nClue:\nLook for knowingly living with the risk.\n\nExample:\nAccept low-risk legacy issue.\n\nContrast:\nAvoid = stop activity; Accept = live with the risk.",trick:"Exam map: Risk management strategies > Accept"},
{cat:4,catName:"D5 Governance & Risk",acr:"Exemption",full:"5.2 Explain elements of the risk management process.",def:"Definition:\nApproved release from a requirement.\n\nClue:\nLook for ownership, documentation, testing scope, evidence, compliance, or risk decisions.\n\nExample:\nSystem exempt from one policy.\n\nContrast:\nTechnical control = system defense; governance term = decision, evidence, responsibility, or requirement.",trick:"Exam map: Risk management strategies > Accept > Exemption"},
{cat:4,catName:"D5 Governance & Risk",acr:"Exception",full:"5.2 Explain elements of the risk management process.",def:"Definition:\nApproved temporary deviation from a requirement.\n\nClue:\nLook for ownership, documentation, testing scope, evidence, compliance, or risk decisions.\n\nExample:\n30-day patch exception.\n\nContrast:\nTechnical control = system defense; governance term = decision, evidence, responsibility, or requirement.",trick:"Exam map: Risk management strategies > Accept > Exception"},
{cat:4,catName:"D5 Governance & Risk",acr:"Avoid",full:"5.2 Explain elements of the risk management process.",def:"Definition:\nRisk strategy that stops the risky activity entirely.\n\nClue:\nLook for stopping the risky activity entirely.\n\nExample:\nCancel unsafe project.\n\nContrast:\nMitigate = reduce risk; Avoid = eliminate by not doing the activity.",trick:"Exam map: Risk management strategies > Accept > Avoid"},
{cat:4,catName:"D5 Governance & Risk",acr:"Mitigate",full:"5.2 Explain elements of the risk management process.",def:"Definition:\nRisk strategy that reduces likelihood or impact with controls.\n\nClue:\nLook for reducing likelihood or impact.\n\nExample:\nAdd MFA to reduce account takeover.\n\nContrast:\nTransfer shifts impact; Mitigate reduces likelihood or impact.",trick:"Exam map: Risk management strategies > Mitigate"},
{cat:4,catName:"D5 Governance & Risk",acr:"Right-to-audit clause",full:"5.2 Explain elements of the risk management process.",def:"Definition:\nContract language giving a party permission to audit another party.\n\nClue:\nLook for ownership, documentation, testing scope, evidence, compliance, or risk decisions.\n\nExample:\nAudit vendor controls.\n\nContrast:\nTechnical control = system defense; governance term = decision, evidence, responsibility, or requirement.",trick:"Exam map: Vendor assessment > Right-to-audit clause"},
{cat:4,catName:"D5 Governance & Risk",acr:"Evidence of internal audits",full:"5.2 Explain elements of the risk management process.",def:"Definition:\nProof that a vendor or organization performs its own audits.\n\nClue:\nLook for ownership, documentation, testing scope, evidence, compliance, or risk decisions.\n\nExample:\nVendor provides audit reports.\n\nContrast:\nTechnical control = system defense; governance term = decision, evidence, responsibility, or requirement.",trick:"Exam map: Vendor assessment > Evidence of internal audits"},
{cat:4,catName:"D5 Governance & Risk",acr:"Independent assessments",full:"5.2 Explain elements of the risk management process.",def:"Definition:\nReviews performed by outside parties.\n\nClue:\nLook for ownership, documentation, testing scope, evidence, compliance, or risk decisions.\n\nExample:\nThird-party security assessment.\n\nContrast:\nTechnical control = system defense; governance term = decision, evidence, responsibility, or requirement.",trick:"Exam map: Vendor assessment > Independent assessments"},
{cat:4,catName:"D5 Governance & Risk",acr:"Supply chain analysis",full:"5.2 Explain elements of the risk management process.",def:"Definition:\nReview of third-party dependencies and risks across suppliers and providers.\n\nClue:\nLook for ownership, documentation, testing scope, evidence, compliance, or risk decisions.\n\nExample:\nReview software dependencies.\n\nContrast:\nTechnical control = system defense; governance term = decision, evidence, responsibility, or requirement.",trick:"Exam map: Vendor assessment > Supply chain analysis"},
{cat:4,catName:"D5 Governance & Risk",acr:"Due diligence",full:"5.2 Explain elements of the risk management process.",def:"Definition:\nReasonable investigation before making a decision or selecting a vendor.\n\nClue:\nLook for ownership, documentation, testing scope, evidence, compliance, or risk decisions.\n\nExample:\nReview vendor security before contract.\n\nContrast:\nTechnical control = system defense; governance term = decision, evidence, responsibility, or requirement.",trick:"Exam map: Vendor selection > Due diligence"},
{cat:4,catName:"D5 Governance & Risk",acr:"Conflict of interest",full:"5.2 Explain elements of the risk management process.",def:"Definition:\nSituation where personal or business interests could improperly influence decisions.\n\nClue:\nLook for ownership, documentation, testing scope, evidence, compliance, or risk decisions.\n\nExample:\nBuyer has stake in vendor.\n\nContrast:\nTechnical control = system defense; governance term = decision, evidence, responsibility, or requirement.",trick:"Exam map: Vendor selection > Conflict of interest"},
{cat:4,catName:"D5 Governance & Risk",acr:"Compliance",full:"5.5 Explain types and purposes of audits and assessments.",def:"Definition:\nMeeting required laws, regulations, standards, contracts, or policies.\n\nClue:\nLook for ownership, documentation, testing scope, evidence, compliance, or risk decisions.\n\nExample:\nMeet PCI DSS for card data.\n\nContrast:\nTechnical control = system defense; governance term = decision, evidence, responsibility, or requirement.",trick:"Exam map: Internal > Compliance"},
{cat:4,catName:"D5 Governance & Risk",acr:"Audit committee",full:"5.5 Explain types and purposes of audits and assessments.",def:"Definition:\nGroup responsible for oversight of audit activities and findings.\n\nClue:\nLook for ownership, documentation, testing scope, evidence, compliance, or risk decisions.\n\nExample:\nReviews audit findings.\n\nContrast:\nTechnical control = system defense; governance term = decision, evidence, responsibility, or requirement.",trick:"Exam map: Internal > Audit committee"},
{cat:4,catName:"D5 Governance & Risk",acr:"Self-assessments",full:"5.5 Explain types and purposes of audits and assessments.",def:"Definition:\nInternal reviews performed by the organization itself.\n\nClue:\nLook for ownership, documentation, testing scope, evidence, compliance, or risk decisions.\n\nExample:\nInternal control checklist.\n\nContrast:\nTechnical control = system defense; governance term = decision, evidence, responsibility, or requirement.",trick:"Exam map: Internal > Self-assessments"},
{cat:4,catName:"D5 Governance & Risk",acr:"Examinations",full:"5.5 Explain types and purposes of audits and assessments.",def:"Definition:\nFormal reviews by regulators or authorized bodies.\n\nClue:\nLook for ownership, documentation, testing scope, evidence, compliance, or risk decisions.\n\nExample:\nRegulator examination.\n\nContrast:\nTechnical control = system defense; governance term = decision, evidence, responsibility, or requirement.",trick:"Exam map: External > Examinations"},
{cat:4,catName:"D5 Governance & Risk",acr:"Assessment",full:"5.5 Explain types and purposes of audits and assessments.",def:"Definition:\nEvaluation of controls, risks, or compliance status.\n\nClue:\nLook for ownership, documentation, testing scope, evidence, compliance, or risk decisions.\n\nExample:\nSecurity risk assessment.\n\nContrast:\nTechnical control = system defense; governance term = decision, evidence, responsibility, or requirement.",trick:"Exam map: External > Assessment"},
{cat:4,catName:"D5 Governance & Risk",acr:"Independent third-",full:"5.5 Explain types and purposes of audits and assessments.",def:"Definition:\nIndependent third-party audits — reviews conducted by external auditors with no affiliation to the organization being audited. Provides objective, unbiased assessment of controls, compliance, and security posture. Required for many compliance frameworks (SOC 2, ISO 27001, PCI DSS, HIPAA). Results carry more credibility than self-assessments because the auditor has no financial interest in the outcome.\n\nClue:\nLook for external, unaffiliated auditors providing objective evidence — this is what SOC 2 Type II, ISO 27001 certification, and PCI QSA assessments are. If it's internal staff reviewing themselves, it's a self-assessment, not independent third-party.\n\nExample:\nCompany needs SOC 2 Type II for enterprise customers. Hires CPA firm (not their own employees) to audit controls over 12 months → issues independent attestation report that customers use as evidence.\n\nContrast:\nSelf-assessment = organization reviews its own controls; Independent third-party = external auditor with no stake in the outcome — provides much stronger compliance evidence.",trick:"Exam map: External audits > Independent third-party"},
{cat:4,catName:"D5 Governance & Risk",acr:"Offensive",full:"5.5 Explain types and purposes of audits and assessments.",def:"Definition:\nSecurity testing that actively attempts to find and exploit weaknesses.\n\nClue:\nLook for ownership, documentation, testing scope, evidence, compliance, or risk decisions.\n\nExample:\nRed team tries to exploit systems.\n\nContrast:\nTechnical control = system defense; governance term = decision, evidence, responsibility, or requirement.",trick:"Exam map: Penetration testing > Offensive"},
{cat:4,catName:"D5 Governance & Risk",acr:"Defensive",full:"5.5 Explain types and purposes of audits and assessments.",def:"Definition:\nSecurity testing focused on detection, response, and control effectiveness.\n\nClue:\nLook for ownership, documentation, testing scope, evidence, compliance, or risk decisions.\n\nExample:\nBlue team detects attack simulation.\n\nContrast:\nTechnical control = system defense; governance term = decision, evidence, responsibility, or requirement.",trick:"Exam map: Penetration testing > Defensive"},
{cat:4,catName:"D5 Governance & Risk",acr:"Integrated",full:"5.5 Explain types and purposes of audits and assessments.",def:"Definition:\nTesting that combines multiple teams, methods, or environments.\n\nClue:\nLook for ownership, documentation, testing scope, evidence, compliance, or risk decisions.\n\nExample:\nRed and blue teams exercise response.\n\nContrast:\nTechnical control = system defense; governance term = decision, evidence, responsibility, or requirement.",trick:"Exam map: Penetration testing > Integrated"},
{cat:4,catName:"D5 Governance & Risk",acr:"Known environment",full:"5.5 Explain types and purposes of audits and assessments.",def:"Definition:\nTest where the tester has full information about the target.\n\nClue:\nLook for ownership, documentation, testing scope, evidence, compliance, or risk decisions.\n\nExample:\nFull documentation provided.\n\nContrast:\nTechnical control = system defense; governance term = decision, evidence, responsibility, or requirement.",trick:"Exam map: Penetration testing > Known environment"},
{cat:4,catName:"D5 Governance & Risk",acr:"Partially known environment",full:"5.5 Explain types and purposes of audits and assessments.",def:"Definition:\nTest where the tester has limited information about the target.\n\nClue:\nLook for ownership, documentation, testing scope, evidence, compliance, or risk decisions.\n\nExample:\nIP ranges only.\n\nContrast:\nTechnical control = system defense; governance term = decision, evidence, responsibility, or requirement.",trick:"Exam map: Penetration testing > Partially known environment"},
{cat:4,catName:"D5 Governance & Risk",acr:"Unknown environment",full:"5.5 Explain types and purposes of audits and assessments.",def:"Definition:\nTest where the tester starts with little or no information about the target.\n\nClue:\nLook for ownership, documentation, testing scope, evidence, compliance, or risk decisions.\n\nExample:\nNo internal details provided.\n\nContrast:\nTechnical control = system defense; governance term = decision, evidence, responsibility, or requirement.",trick:"Exam map: Penetration testing > Unknown environment"},
{cat:4,catName:"D5 Governance & Risk",acr:"Reconnaissance",full:"5.5 Explain types and purposes of audits and assessments.",def:"Definition:\nGathering information about a target before or during testing.\n\nClue:\nLook for ownership, documentation, testing scope, evidence, compliance, or risk decisions.\n\nExample:\nGather domains and employee names.\n\nContrast:\nTechnical control = system defense; governance term = decision, evidence, responsibility, or requirement.",trick:"Exam map: Penetration testing > Reconnaissance"},
{cat:4,catName:"D5 Governance & Risk",acr:"Passive",full:"5.5 Explain types and purposes of audits and assessments.",def:"Definition:\nTesting or monitoring that observes or collects information without directly touching or changing the target system.\n\nClue:\nLook for observing, researching, or collecting public data without touching the target.\n\nExample:\nRead public DNS records.\n\nContrast:\nActive = directly interacts with the target.",trick:"Exam map: Penetration testing > Reconnaissance > Passive"},
{cat:4,catName:"D5 Governance & Risk",acr:"Active",full:"5.5 Explain types and purposes of audits and assessments.",def:"Definition:\nTesting or monitoring that directly interacts with the target system. Active methods can create logs, traffic, or changes because they touch the target.\n\nClue:\nLook for scanning or testing that touches the target and may create logs.\n\nExample:\nPort scan a server.\n\nContrast:\nPassive = observes without touching the target.",trick:"Exam map: Penetration testing > Reconnaissance > Active"},
{cat:4,catName:"D5 Governance & Risk",acr:"Fines",full:"5.4 Summarize elements of effective security compliance.",def:"Definition:\nMonetary penalties for non-compliance.\n\nClue:\nLook for ownership, documentation, testing scope, evidence, compliance, or risk decisions.\n\nExample:\nPrivacy violation penalty.\n\nContrast:\nTechnical control = system defense; governance term = decision, evidence, responsibility, or requirement.",trick:"Exam map: Consequences of non-compliance > Fines"},
{cat:4,catName:"D5 Governance & Risk",acr:"Sanctions",full:"5.4 Summarize elements of effective security compliance.",def:"Definition:\nFormal penalties or restrictions imposed for violations.\n\nClue:\nLook for ownership, documentation, testing scope, evidence, compliance, or risk decisions.\n\nExample:\nRestrictions after non-compliance.\n\nContrast:\nTechnical control = system defense; governance term = decision, evidence, responsibility, or requirement.",trick:"Exam map: Consequences of non-compliance > Sanctions"},
{cat:4,catName:"D5 Governance & Risk",acr:"Reputational damage",full:"5.4 Summarize elements of effective security compliance.",def:"Definition:\nLoss of trust or public standing after a failure or incident.\n\nClue:\nLook for ownership, documentation, testing scope, evidence, compliance, or risk decisions.\n\nExample:\nCustomers leave after breach.\n\nContrast:\nTechnical control = system defense; governance term = decision, evidence, responsibility, or requirement.",trick:"Exam map: Consequences of non-compliance > Reputational damage"},
{cat:4,catName:"D5 Governance & Risk",acr:"Loss of license",full:"5.4 Summarize elements of effective security compliance.",def:"Definition:\nLosing legal or professional permission to operate.\n\nClue:\nLook for ownership, documentation, testing scope, evidence, compliance, or risk decisions.\n\nExample:\nRegulator revokes license.\n\nContrast:\nTechnical control = system defense; governance term = decision, evidence, responsibility, or requirement.",trick:"Exam map: Consequences of non-compliance > Loss of license"},
{cat:4,catName:"D5 Governance & Risk",acr:"Contractual impacts",full:"5.4 Summarize elements of effective security compliance.",def:"Definition:\nConsequences under contracts, such as penalties or termination.\n\nClue:\nLook for ownership, documentation, testing scope, evidence, compliance, or risk decisions.\n\nExample:\nSLA penalties after outage.\n\nContrast:\nTechnical control = system defense; governance term = decision, evidence, responsibility, or requirement.",trick:"Exam map: Consequences of non-compliance > Contractual impacts"},
{cat:4,catName:"D5 Governance & Risk",acr:"Due diligence/care",full:"5.4 Summarize elements of effective security compliance.",def:"Definition:\nReasonable investigation and responsible ongoing action to meet obligations.\n\nClue:\nLook for ownership, documentation, testing scope, evidence, compliance, or risk decisions.\n\nExample:\nMonitor vendor compliance.\n\nContrast:\nThreat/vulnerability = problem; control/mitigation = defense.",trick:"Exam map: Compliance monitoring > Due diligence/care"},
{cat:4,catName:"D5 Governance & Risk",acr:"Attestation and",full:"5.4 Summarize elements of effective security compliance.",def:"Definition:\nAttestation and examination — two compliance verification methods. Attestation = formal written declaration that controls are in place and operating effectively (e.g., a SOC 2 Type II report where an auditor attests to control effectiveness). Examination = regulatory or auditor inspection of systems, records, and personnel to directly verify compliance (e.g., PCI QSA on-site examination, regulatory examination by a bank regulator).\n\nClue:\nAttestation = written formal declaration of compliance (auditor's opinion). Examination = active inspection and testing of controls by an authorized reviewer. Both produce evidence for compliance purposes.\n\nExample:\nBank regulator conducts an examination: reviewers visit the data center, interview staff, test access controls, review logs — active examination. Resulting report = examination findings. SOC 2 report = independent attestation.\n\nContrast:\nSelf-assessment = organization checks itself; Attestation = third party formally declares controls work; Examination = regulator or auditor directly inspects and tests.",trick:"Exam map: Compliance monitoring > Attestation and examination"},
{cat:4,catName:"D5 Governance & Risk",acr:"Internal and external",full:"5.4 Summarize elements of effective security compliance.",def:"Definition:\nTwo compliance monitoring sources. Internal = the organization monitors its own compliance continuously (internal audit team, compliance team, automated monitoring tools, security reviews). External = third-party auditors, regulators, or customers assess compliance (mandatory for many frameworks). Both are needed: internal catches issues continuously, external provides objective validation and formal certifications.\n\nClue:\nInternal monitoring = continuous self-oversight (catches problems before external auditors do). External = periodic but authoritative (regulators and certifications). You need both — internal alone is insufficient for compliance evidence.\n\nExample:\nInternal: security team runs monthly access reviews, quarterly vulnerability scans, and automated SIEM checks. External: annual PCI DSS audit by QSA and ISO 27001 surveillance audit provide formal compliance evidence.\n\nContrast:\nInternal monitoring = frequent, catches drift early; External audit = periodic, authoritative, required for compliance certifications and regulatory requirements.",trick:"Exam map: Compliance monitoring > Internal and external"},
{cat:4,catName:"D5 Governance & Risk",acr:"Automation",full:"5.4 Summarize elements of effective security compliance.",def:"Definition:\nUsing tools or scripts to perform tasks consistently with less manual effort.\n\nClue:\nLook for ownership, documentation, testing scope, evidence, compliance, or risk decisions.\n\nExample:\nScript disables inactive accounts.\n\nContrast:\nThreat/vulnerability = problem; control/mitigation = defense.",trick:"Exam map: Compliance monitoring > Automation"},
{cat:4,catName:"D5 Governance & Risk",acr:"Legal implications",full:"5.4 Summarize elements of effective security compliance.",def:"Definition:\nLegal consequences or requirements related to a decision or activity.\n\nClue:\nLook for ownership, documentation, testing scope, evidence, compliance, or risk decisions.\n\nExample:\nData location triggers privacy law.\n\nContrast:\nTechnical control = system defense; governance term = decision, evidence, responsibility, or requirement.",trick:"Exam map: Privacy > Legal implications"},
{cat:4,catName:"D5 Governance & Risk",acr:"Data subject",full:"5.4 Summarize elements of effective security compliance.",def:"Definition:\nPerson the personal data is about.\n\nClue:\nLook for where the asset lives, what can fail, and how the design protects or restores CIA.\n\nExample:\nCustomer in privacy request.\n\nContrast:\nTechnical control = system defense; governance term = decision, evidence, responsibility, or requirement.",trick:"Exam map: Privacy > Data subject"},
{cat:4,catName:"D5 Governance & Risk",acr:"Controller vs. processor",full:"5.4 Summarize elements of effective security compliance.",def:"Definition:\nController decides how and why personal data is processed; processor acts on the controller’s behalf.\n\nClue:\nLook for ownership, documentation, testing scope, evidence, compliance, or risk decisions.\n\nExample:\nCompany decides, cloud vendor processes.\n\nContrast:\nThreat/vulnerability = problem; control/mitigation = defense.",trick:"Exam map: Privacy > Controller vs. processor"},
{cat:4,catName:"D5 Governance & Risk",acr:"Data inventory and retention",full:"5.4 Summarize elements of effective security compliance.",def:"Definition:\nCataloging data and defining how long it is kept.\n\nClue:\nLook for where the asset lives, what can fail, and how the design protects or restores CIA.\n\nExample:\nKeep tax records 7 years.\n\nContrast:\nTechnical control = system defense; governance term = decision, evidence, responsibility, or requirement.",trick:"Exam map: Privacy > Data inventory and retention"},
{cat:4,catName:"D5 Governance & Risk",acr:"Right to be forgotten",full:"5.4 Summarize elements of effective security compliance.",def:"Definition:\nPrivacy right to request deletion of personal data under certain conditions.\n\nClue:\nLook for ownership, documentation, testing scope, evidence, compliance, or risk decisions.\n\nExample:\nUser requests account data removal.\n\nContrast:\nTechnical control = system defense; governance term = decision, evidence, responsibility, or requirement.",trick:"Exam map: Privacy > Right to be forgotten"},
{cat:4,catName:"D5 Governance & Risk",acr:"Campaigns",full:"5.6 Given a scenario, implement security awareness practices.",def:"Definition:\nPlanned awareness or phishing exercises run over time.\n\nClue:\nLook for how the attack or weakness behaves, what it targets, and what reduces the damage.\n\nExample:\nMonthly phishing practice.\n\nContrast:\nTechnical control = system defense; governance term = decision, evidence, responsibility, or requirement.",trick:"Exam map: Phishing > Campaigns"},
{cat:4,catName:"D5 Governance & Risk",acr:"Recognizing a phishing attempt",full:"5.6 Given a scenario, implement security awareness practices.",def:"Definition:\nAbility to identify suspicious sender, links, urgency, attachments, and requests.\n\nClue:\nLook for how the attack or weakness behaves, what it targets, and what reduces the damage.\n\nExample:\nUrgent email with strange link.\n\nContrast:\nTechnical control = system defense; governance term = decision, evidence, responsibility, or requirement.",trick:"Exam map: Phishing > Recognizing a phishing attempt"},
{cat:4,catName:"D5 Governance & Risk",acr:"Responding to reported",full:"5.6 Given a scenario, implement security awareness practices.",def:"Definition:\nThe organizational process for handling user-reported phishing emails. Steps: (1) Receive report via dedicated button or mailbox, (2) Analyze the reported email (headers, links, attachments — safely in sandbox), (3) Search mailboxes to find all recipients of the same email, (4) Pull/quarantine the email from all mailboxes, (5) Identify who clicked links or opened attachments, (6) Reset credentials for those who interacted, (7) Update email filters to block the campaign, (8) Provide feedback to reporter. Encourages reporting culture.\n\nClue:\nLook for what happens AFTER a user reports a phishing email — the response process is what makes reporting valuable. If users report but nothing happens, they stop reporting.\n\nExample:\nUser clicks 'Report Phishing' → Security team pulls all copies from 200 mailboxes → finds 3 users clicked link → resets their passwords → blocks sender domain → thanks the reporter.\n\nContrast:\nRecognizing phishing = user skill (detection); Responding to reported = organizational process (response). Both are needed for effective phishing defense.",trick:"Exam map: Phishing > Responding to reported phishing"},
{cat:4,catName:"D5 Governance & Risk",acr:"Anomalous behavior recognition",full:"5.6 Given a scenario, implement security awareness practices.",def:"Definition:\nIdentifying behavior that differs from normal patterns.\n\nClue:\nLook for ownership, documentation, testing scope, evidence, compliance, or risk decisions.\n\nExample:\nUser logs in at 3 AM from new country.\n\nContrast:\nTechnical control = system defense; governance term = decision, evidence, responsibility, or requirement.",trick:"Exam map: 5.0 Security Program Management and Oversight"},
{cat:4,catName:"D5 Governance & Risk",acr:"Risky",full:"5.6 Given a scenario, implement security awareness practices.",def:"Definition:\nBehavior, condition, or decision that increases the chance or impact of a security problem.\n\nClue:\nLook for ownership, documentation, testing scope, evidence, compliance, or risk decisions.\n\nExample:\nSharing password in chat.\n\nContrast:\nTechnical control = system defense; governance term = decision, evidence, responsibility, or requirement.",trick:"Exam map: Anomalous behavior recognition > Risky"},
{cat:4,catName:"D5 Governance & Risk",acr:"Unexpected",full:"5.6 Given a scenario, implement security awareness practices.",def:"Definition:\nBehavior or activity that does not match normal patterns and may indicate error, misuse, or compromise.\n\nClue:\nLook for ownership, documentation, testing scope, evidence, compliance, or risk decisions.\n\nExample:\nPrinter sending outbound traffic.\n\nContrast:\nTechnical control = system defense; governance term = decision, evidence, responsibility, or requirement.",trick:"Exam map: Anomalous behavior recognition > Unexpected"},
{cat:4,catName:"D5 Governance & Risk",acr:"Unintentional",full:"5.6 Given a scenario, implement security awareness practices.",def:"Definition:\nAn accidental action that creates security risk without malicious intent.\n\nClue:\nLook for ownership, documentation, testing scope, evidence, compliance, or risk decisions.\n\nExample:\nEmail sent to wrong person.\n\nContrast:\nTechnical control = system defense; governance term = decision, evidence, responsibility, or requirement.",trick:"Exam map: Anomalous behavior recognition > Unintentional"},
{cat:4,catName:"D5 Governance & Risk",acr:"Policy/handbooks",full:"5.6 Given a scenario, implement security awareness practices.",def:"Definition:\nUser-facing documents that explain rules and expectations.\n\nClue:\nLook for ownership, documentation, testing scope, evidence, compliance, or risk decisions.\n\nExample:\nEmployee handbook explains security rules.\n\nContrast:\nTechnical control = system defense; governance term = decision, evidence, responsibility, or requirement.",trick:"Exam map: User guidance and training > Policy/handbooks"},
{cat:4,catName:"D5 Governance & Risk",acr:"Situational awareness",full:"5.6 Given a scenario, implement security awareness practices.",def:"Definition:\nUnderstanding current risk, environment, and warning signs.\n\nClue:\nLook for ownership, documentation, testing scope, evidence, compliance, or risk decisions.\n\nExample:\nNotice tailgating attempt.\n\nContrast:\nTechnical control = system defense; governance term = decision, evidence, responsibility, or requirement.",trick:"Exam map: User guidance and training > Situational awareness"},
{cat:4,catName:"D5 Governance & Risk",acr:"Password management",full:"5.6 Given a scenario, implement security awareness practices.",def:"Definition:\nCreating, storing, rotating, and protecting passwords properly.\n\nClue:\nLook for proving identity, assigning access, limiting privileges, or removing access.\n\nExample:\nUnique passwords in manager.\n\nContrast:\nTechnical control = system defense; governance term = decision, evidence, responsibility, or requirement.",trick:"Exam map: User guidance and training > Password management"},
{cat:4,catName:"D5 Governance & Risk",acr:"Removable media and cables",full:"5.6 Given a scenario, implement security awareness practices.",def:"Definition:\nPortable devices and cables that can introduce malware, data loss, or unauthorized access.\n\nClue:\nLook for ownership, documentation, testing scope, evidence, compliance, or risk decisions.\n\nExample:\nUnknown USB cable steals data.\n\nContrast:\nTechnical control = system defense; governance term = decision, evidence, responsibility, or requirement.",trick:"Exam map: User guidance and training > Removable media and cables"},
{cat:4,catName:"D5 Governance & Risk",acr:"Social engineering",full:"5.6 Given a scenario, implement security awareness practices.",def:"Definition:\nManipulating people into revealing information or performing unsafe actions.\n\nClue:\nLook for ownership, documentation, testing scope, evidence, compliance, or risk decisions.\n\nExample:\nFake IT call asks for MFA code.\n\nContrast:\nTechnical control = system defense; governance term = decision, evidence, responsibility, or requirement.",trick:"Exam map: User guidance and training > Social engineering"},
{cat:4,catName:"D5 Governance & Risk",acr:"Operational security",full:"5.6 Given a scenario, implement security awareness practices.",def:"Definition:\nProtecting sensitive operational details from exposure.\n\nClue:\nLook for ownership, documentation, testing scope, evidence, compliance, or risk decisions.\n\nExample:\nAvoid posting badge photos online.\n\nContrast:\nTechnical control = system defense; governance term = decision, evidence, responsibility, or requirement.",trick:"Exam map: User guidance and training > Operational security"},
{cat:4,catName:"D5 Governance & Risk",acr:"Hybrid/remote work",full:"5.6 Given a scenario, implement security awareness practices.",def:"Definition:\nSecurity awareness specific to distributed workforces. Key training topics: always use VPN or ZTNA before accessing corporate resources from home or public networks, secure the home Wi-Fi (WPA3, unique password, separate IoT VLAN), never use public Wi-Fi without VPN, be aware of physical security at home (shoulder surfing, device theft), use only approved company devices for work, watch for increased phishing targeting remote workers, lock screen when stepping away.\n\nClue:\nLook for scenarios where employees working from home or coffee shops create new risks — the office perimeter controls (firewall, IPS) are gone. Training fills the gap that technology can't fully cover.\n\nExample:\nEmployee works from coffee shop: VPN mandatory before accessing any corporate app, public Wi-Fi carries risk of on-path attacks, coworkers shouldn't see the screen (shoulder surfing), corporate device only.\n\nContrast:\nOn-premises workers = office network controls protect them; Remote workers = must follow training-based practices because enterprise security controls don't surround them.",trick:"Exam map: User guidance and training > Hybrid/remote work"},
{cat:4,catName:"D5 Governance & Risk",acr:"Initial",full:"5.6 Given a scenario, implement security awareness practices.",def:"Definition:\nThe first time a process, training, report, or monitoring activity happens.\n\nClue:\nLook for ownership, documentation, testing scope, evidence, compliance, or risk decisions.\n\nExample:\nNew hire awareness training.\n\nContrast:\nInsecure protocol = avoid when confidentiality is needed; secure protocol = prefer for protected communication.",trick:"Exam map: Reporting and monitoring > Initial"},
];
